INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('image/flux/0', 'image', 'flux', 'FLUX', '1-dev', '1-dev', 0, 'image', 'Prompt Guide: FLUX.1-dev', 'models/image/flux.1-dev.md', 4, 'Write in natural, descriptive language — full sentences and detailed prose — rather than SDXL-style keyword/tag soup. FLUX.1''s T5-XXL encoder was trained on prose, so grammar, word order, and spatial relationships (who/what is where, doing what) matter. Early words carry more weight. Describe what you want, affirmatively — there is no negative prompt, so "not X" must be rephrased as the desired alternative.', '[{"syntax":"Weighting (word:1.4)","supported":"no","notes":"Not natively supported by the FLUX.1 pipeline; weighting syntax is an SDXL-era convention. Some third-party UIs emulate it, but it is not part of the model''s semantics."},{"syntax":"Emphasis ((word))","supported":"no","notes":"Repeating words for \"fake emphasis\" is discouraged in FLUX prompting guidance; use more descriptive language instead."},{"syntax":"BREAK keyword","supported":"no","notes":"SDXL-era syntax; not applicable to FLUX.1''s T5-based conditioning."},{"syntax":"[from:to:step] blending","supported":"no","notes":"SDXL-era syntax; not applicable."},{"syntax":"Negative prompt","supported":"no","notes":"FLUX.1 is guidance-distilled: the CFG behavior is baked into the weights, so there is no unconditional branch for a negative prompt to plug into. BFL documents this as an intended constraint — rewrite negatives as affirmative descriptions."},{"syntax":"Special / trigger tokens","supported":"yes","notes":"Trigger words / LoRA trigger tokens work when a LoRA trained with one is loaded (e.g. <lora:...> naming conventions in ComfyUI); no model-native special tokens beyond the text encoders'' standard vocab."},{"syntax":"Regional / masked prompting","supported":"partial","notes":"Native inpainting/outpainting via FLUX.1 Fill [dev] with masks; masked/regional prompting is a feature of specific tools (e.g. FLUX.1 Fill), not the base dev model."}]', '[{"length":"Too short","effect":"Underspecifies the scene; the model fills in defaults that may not match intent. Very terse prompts (a few words) yield generic, less controlled results."},{"length":"Ideal","effect":"Paragraph-length descriptive prompts, roughly 50–150 words, with subject, action, style, environment, lighting, and camera specs. BFL''s recommended scaffold is Subject + Action + Style + Context; early tokens are weighted more heavily, so front-load the most important elements."},{"length":"Too long","effect":"Prompts beyond the 512-token T5-XXL context get truncated; detail beyond the limit is silently ignored. Extremely long prompts can also bury key details and dilute attention."}]', '[Subject] + [Action / Pose] + [Style / Medium] + [Environment / Context] + [Lighting] + [Camera / Lens] + [Quality / Finish]', '[{"include":"Affirmative descriptions (replaces negative prompts)","examples":"\"anatomically correct hands\", \"clean un-watermarked composition\", \"sharp focus throughout\""},{"include":"Camera specifications (FLUX.1 responds exceptionally well)","examples":"\"85mm portrait lens, f/1.4\", \"wide angle 24mm lens\", \"macro photography, 100mm lens\", \"shot on Canon 5D Mark IV\""},{"include":"Detailed lighting","examples":"\"natural window light\", \"golden hour sunlight\", \"dramatic Rembrandt lighting\", \"soft diffused studio lighting\""},{"include":"Materials, textures, colors","examples":"\"weathered oak table\", \"brushed stainless steel\", \"emerald green silk dress\""},{"include":"Spatial relationships in full sentences","examples":"\"The cat sits on the left side of the couch. A lamp glows behind it.\""},{"include":"Exact text in quotes (for text in image)","examples":"\"a neon sign that reads ''OPEN'' above the door\""},{"include":"Subject, age, ethnicity, expression for people","examples":"\"a man in his forties, weathered face, calm expression\""}]', '[{"instead":"Tag soup: beach, woman, sunset, realistic, 8k","write":"\"A woman standing on a beach at sunset. Photorealistic, warm golden light on the water.\""},{"instead":"Negative lists: no blur, no watermark, no extra fingers","write":"\"sharp focus throughout, clean un-watermarked composition, anatomically correct hands\""},{"instead":"Vague hype words: masterpiece, best quality, ultra detailed","write":"Concrete descriptors: \"intricate fabric weave, individual strands of hair, fine skin texture\""},{"instead":"Repeated words for fake emphasis: red red red dress","write":"\"a vivid crimson dress\""},{"instead":"Contradictory instructions: sitting, standing, walking","write":"Pick one: \"standing\""},{"instead":"Parenthesized weight syntax: (word:1.4)","write":"More descriptive language for that element"}]', '[{"param":"Steps","value":"28–50 (50 in the HF reference example; 20–30 is a common quality/speed trade-off)"},{"param":"Guidance / CFG Scale","value":"3.5 (default). Useful range roughly 2.5–4.5 for photorealism, 3.5–7 for stylized work. Note: this is a distilled guidance input, not true CFG — there is no negative prompt. Above ~6 risks over-saturation and distortion."},{"param":"Resolution","value":"1024×1024 default; any aspect ratio supported. Keep dimensions multiples of 16 for the VAE. 1 MP total is the reference; higher res benefits from upscaler workflows."},{"param":"Scheduler / Sampler","value":"FlowMatch Euler (default in diffusers); Euler is the standard community choice in ComfyUI."},{"param":"Dtype / Precision","value":"bfloat16 for the full model (~24 GB VRAM with T5-XXL). fp8 / quantized checkpoints (e.g. Kijai fp8, t5xxl_fp8_e4m3fn) run in ~16 GB VRAM."}]', '[{"title":"Using a negative prompt field","detail":"— FLUX.1 is guidance-distilled; there is no unconditional branch, so negative prompts are ignored (or dropped) by every production endpoint. Rewrite as affirmative descriptions."},{"title":"Tag-soup prompting","detail":"— comma-separated keyword lists underperform natural-language sentences on T5-XXL. Write prose, not tags."},{"title":"Cranking guidance above ~6","detail":"— guidance is a distilled conditioning scalar, not true CFG; values above ~6 cause over-saturation, plastic skin, and distorted hands rather than \"more prompt adherence.\""},{"title":"Treating (word:1.4) and BREAK as supported syntax","detail":"— these are SDXL-era conventions with no native support in the FLUX pipeline."},{"title":"Writing prompts longer than ~512 tokens","detail":"— the T5-XXL context ceiling silently truncates anything beyond it; put the essential subject and action early."}]', 'Target model: FLUX 1-dev (image).
How to prompt it: Write in natural, descriptive language — full sentences and detailed prose — rather than SDXL-style keyword/tag soup. FLUX.1''s T5-XXL encoder was trained on prose, so grammar, word order, and spatial relationships (who/what is where, doing what) matter. Early words carry more weight. Describe what you want, affirmatively — there is no negative prompt, so "not X" must be rephrased as the desired alternative.
Prompt length — too short: Underspecifies the scene; the model fills in defaults that may not match intent. Very terse prompts (a few words) yield generic, less controlled results. | ideal: Paragraph-length descriptive prompts, roughly 50–150 words, with subject, action, style, environment, lighting, and camera specs. BFL''s recommended scaffold is Subject + Action + Style + Context; early tokens are weighted more heavily, so front-load the most important elements. | too long: Prompts beyond the 512-token T5-XXL context get truncated; detail beyond the limit is silently ignored. Extremely long prompts can also bury key details and dilute attention.
Syntax — supported: Special / trigger tokens | partial: Regional / masked prompting | NOT supported: Weighting (word:1.4), Emphasis ((word)), BREAK keyword, [from:to:step] blending, Negative prompt
Negative prompt: NO — FLUX.1 is guidance-distilled: the CFG behavior is baked into the weights, so there is no unconditional branch for a negative prompt to plug into. BFL documents this as an intended constraint — rewrite negatives as affirmative descriptions.
Include: Affirmative descriptions (replaces negative prompts); Camera specifications (FLUX.1 responds exceptionally well); Detailed lighting; Materials, textures, colors; Spatial relationships in full sentences; Exact text in quotes (for text in image)
Avoid: Tag soup: beach, woman, sunset, realistic, 8k; Negative lists: no blur, no watermark, no extra fingers; Vague hype words: masterpiece, best quality, ultra detailed; Repeated words for fake emphasis: red red red dress; Contradictory instructions: sitting, standing, walking; Parenthesized weight syntax: (word:1.4)
Recommended settings: Steps 28–50 (50 in the HF reference example; 20–30 is a common quality/speed trade-off); Guidance / CFG Scale 3.5 (default). Useful range roughly 2.5–4.5 for photorealism, 3.5–7 for stylized work. Note: this is a distilled guidance input, not true CFG — there is no negative prompt. Above ~6 risks over-saturation and distortion.; Resolution 1024×1024 default; any aspect ratio supported. Keep dimensions multiples of 16 for the VAE. 1 MP total is the reference; higher res benefits from upscaler workflows.; Scheduler / Sampler FlowMatch Euler (default in diffusers); Euler is the standard community choice in ComfyUI.; Dtype / Precision bfloat16 for the full model (~24 GB VRAM with T5-XXL). fp8 / quantized checkpoints (e.g. Kijai fp8, t5xxl_fp8_e4m3fn) run in ~16 GB VRAM.
Common mistakes: Using a negative prompt field; Tag-soup prompting; Cranking guidance above ~6; Treating (word:1.4) and BREAK as supported syntax; Writing prompts longer than ~512 tokens', 'FLUX.1 [dev] is a 12-billion-parameter rectified-flow transformer for text-to-image generation, released August 2024 as the open-weights member of the FLUX.1 family (pro / dev / schnell). It is guidance-distilled from the unreleased FLUX.1 base model, which makes it efficient (28–50 steps, single forward pass per step) and removes the unconditional branch that negative prompts rely on. It excels at photorealism, complex lighting, accurate spatial relationships, and legible short text in images. Unlike SDXL-era models, it understands paragraph-length natural-language descriptions through its 512-token T5-XXL encoder rather than comma-separated tag lists.', '[{"url":"https://huggingface.co/black-forest-labs/FLUX.1-dev","note":"https://huggingface.co/black-forest-labs/FLUX.1-dev"},{"url":"https://github.com/glazed-ai/black-forest-labs-FLUX.1-dev","note":"https://github.com/glazed-ai/black-forest-labs-FLUX.1-dev"},{"url":"https://github.com/mohamedabdallah-14/prompt-to-asset/blob/HEAD/docs/research/06-stable-diffusion-flux/6b-flux-family-prompting.md","note":"https://github.com/mohamedabdallah-14/prompt-to-asset/blob/HEAD/docs/research/06-stable-diffusion-flux/6b-flux-family-prompting.md"},{"url":"https://huggingface.co/docs/diffusers/main/en/api/pipelines/flux","note":"https://huggingface.co/docs/diffusers/main/en/api/pipelines/flux"}]', 'd0760508436e9005c0c7bb2078fc10a0');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('image/flux/1', 'image', 'flux', 'FLUX', '2-Klein', '2-klein', 1, 'image', 'Prompt Guide: FLUX.2-Klein', 'models/image/flux.2-klein.md', 4, 'Describe the scene like a novelist, not a search engine — flowing prose with the subject first, then setting, details, and lighting. The Qwen3 encoder is an instruction-tuned LLM that understands relationships between elements, so sentences beat tag lists. Every source agrees: word order signals priority — the most important content comes first. Unlike FLUX.2 [dev], Klein does not auto-enhance or upsample your prompt: what you write is what you get, so iteration is cheap (sub-second) and the recommended loop is write → generate → adjust one detail at a time.', '[{"syntax":"Weighting (word:1.4)","supported":"no","notes":"Explicitly not supported: \"Flux 2 [klein] does not use explicit weight syntax\" (fal.ai guide). Signal priority with natural-language emphasis instead: \"prominently featuring\", \"with particular attention to\", \"especially detailed\"."},{"syntax":"Emphasis ((word))","supported":"no","notes":"Word repetition for fake emphasis (\"detailed detailed detailed\") is listed as an anti-pattern; use more descriptive language instead."},{"syntax":"BREAK keyword","supported":"unknown","notes":"No Klein-specific documentation found; leave unsupported."},{"syntax":"[from:to:step] blending","supported":"unknown","notes":"No Klein-specific documentation found; leave unsupported."},{"syntax":"Negative prompt","supported":"no","notes":"All distilled Klein variants are guidance-distilled and run at guidance 1.0 (CFG effectively off), so a negative prompt has no mechanism to act. Describe what you want, never what you don''t want. (Base/undistilled variants can use guidance > 1.0.)"},{"syntax":"Special / trigger tokens","supported":"unknown","notes":"No model-native special tokens documented for the base models; third-party Klein LoRAs may have their own trigger words."},{"syntax":"Regional / masked prompting","supported":"unknown","notes":"No documented Klein-native regional/masked prompting found."}]', '[{"length":"Too short","effect":"Works for quick concepts and style exploration, but with no prompt upsampling on Klein, a 3-word prompt leaves almost everything to the model. Underspecified prompts yield generic results — the model cannot enhance what you don''t describe."},{"length":"Ideal","effect":"Medium 30–80 words is \"usually ideal for most projects\" (BFL''s FLUX.2 guide). Klein-specific guidance adds a Long tier of 80–300+ words for complex editorial and detailed product shots — but only when every detail serves the image. fal.ai''s Klein guide warns prompts over ~100 words create confusion. Every sentence should add visual information."},{"length":"Too long","effect":"BFL documents prompt lengths up to 300+ words for complex scenes, but overstuffed prompts bury key details — with only 4 denoising steps on distilled variants, front-load what matters. The diffusers pipeline exposes max_sequence_length (default 512); explicit truncation behavior is not documented by BFL."}]', '[Subject] + [Action] + [Style] + [Context]   ← BFL''s official FLUX.2 scaffold → [Subject] → [Setting] → [Details] → [Lighting] → [Atmosphere]   ← Klein-specific ordering', '[{"include":"Photographer-grade lighting (single highest-impact element)","examples":"\"golden hour sunlight\", \"soft diffused light from a large window camera-left\", \"Rembrandt lighting\", \"rim light\", \"volumetric light\", \"chiaroscuro\", \"studio softbox\"; describe source, quality, direction, temperature, and how light interacts with surfaces (\"filters through\", \"catches\", \"reflects\")"},{"include":"Specific camera language","examples":"\"85mm portrait lens\", \"35mm film\", \"f/1.8\", \"Kodak Portra 400\", \"shot on Canon EOS R5\", \"80s vintage\", \"2000s digicam\""},{"include":"Concrete subject specifics","examples":"\"A woman in her mid-30s with shoulder-length auburn hair\" (not \"a person\")"},{"include":"Spatial relationships and composition","examples":"\"centered composition\", \"rule of thirds\", \"bird''s eye view\", \"the ocean behind her\""},{"include":"HEX color codes for precise colors","examples":"\"color #FF5733\", \"Apple: #0047AB\" — signal with \"color\" or \"hex\" and bind the code to a specific object; gradients also work"},{"include":"Exact text in quotation marks for in-image typography","examples":"\"a sign that reads ''OPEN'' in glowing capital letters\" — plus placement, style, size, color"},{"include":"Style/mood annotations at the end","examples":"\"Style: Country chic meets luxury lifestyle editorial. Mood: Serene, romantic, grounded.\""}]', '[{"instead":"Comma tag soup: beach, woman, camera, sitting, black dress, realistic","write":"\"A realistic photo of a woman sitting on a beach. She is looking at the camera. She is wearing a black dress. The ocean is behind her.\""},{"instead":"Quality-booster tags: masterpiece, best quality, ultra detailed","write":"Concrete visualizable detail: \"intricate fabric weave, individual strands of hair\""},{"instead":"Word repetition: detailed detailed detailed","write":"\"with particular attention to detail in the fabric\""},{"instead":"Contradictory instructions: sitting, standing, walking / photorealistic portrait, watercolor painting style","write":"Pick one per prompt; commit to a primary aesthetic"},{"instead":"Explicit negatives: no blur, without text, don''t make it dark","write":"Affirmative descriptions: \"sharp focus throughout\", \"bright, well-lit scene\""},{"instead":"Vague style: make it look good","write":"A concrete aesthetic: \"shot on 35mm film, muted greens and warm amber tones\""},{"instead":"Vague edit instructions: make it better, fix the image","write":"\"Change her dress from blue to deep burgundy\" / \"Add dramatic storm clouds to the sky\""}]', '[{"param":"Steps","value":"4 (distilled 4B / 9B / 9B KV — official HF example). Base variants: 50 steps, guidance 4.0 (official diffusers example)."},{"param":"Guidance / CFG Scale","value":"1.0 for distilled variants (CFG effectively off — distilled guidance). Base variants support guidance above 1.0 (e.g. 4.0)."},{"param":"Resolution","value":"1024×1024 is the official benchmark resolution and HF example. Family-wide guidance (BFL FLUX.2 guide): 1:1 → 1024×1024 / 1536×1536; 16:9 → 1920×1080; 9:16 → 1080×1920; 21:9 → 2048×864; min 64×64, max 4 MP; dimensions multiples of 16; up to 2 MP recommended for most use cases."},{"param":"Scheduler / Sampler","value":"Not documented for Klein by BFL — left blank (the model is a rectified-flow transformer)."},{"param":"Dtype / Precision","value":"bfloat16 in official examples; official FP8 and NVFP4 quantized variants available."}]', '[{"title":"Prompting like it''s SDXL or FLUX.1","detail":"— tag-soup keyword lists, quality tags, and (word:1.4) weighting are CLIP-era habits with no documented effect on Klein''s Qwen3 encoder. Write prose."},{"title":"Relying on negative prompts","detail":"— distilled Klein runs at guidance 1.0 (CFG off), so negatives have no effect. Describe what you want affirmatively."},{"title":"Expecting prompt upsampling","detail":"— unlike FLUX.2 [dev], Klein does not auto-enhance your prompt; \"what you write is what you get.\" Describe thoroughly on the first pass."},{"title":"Using distilled variants for fine-tuning","detail":"— distilled (4-step) variants are for production speed; Base variants (50-step, guidance-capable) are for fine-tuning, LoRA training, and maximum diversity."},{"title":"Burying key details in overlong prompts","detail":"— with only 4 denoising steps on distilled variants, front-load what matters; prompts over ~100 words risk confusing the model (fal.ai guide)."},{"title":"Vague edit instructions","detail":"— \"make it more professional\" is not actionable for the editor; specify the change and the target state."},{"title":"Not specifying lighting","detail":"— consistently the most-cited quality lever for Klein; photographer-grade lighting terms are the cheapest win."},{"title":"Contradictory style instructions","detail":"— \"photorealistic portrait\" + \"watercolor painting style\" in one prompt; commit to a primary aesthetic."}]', 'Target model: FLUX 2-Klein (image).
How to prompt it: Describe the scene like a novelist, not a search engine — flowing prose with the subject first, then setting, details, and lighting. The Qwen3 encoder is an instruction-tuned LLM that understands relationships between elements, so sentences beat tag lists. Every source agrees: word order signals priority — the most important content comes first. Unlike FLUX.2 [dev], Klein does not auto-enhance or upsample your prompt…
Prompt length — too short: Works for quick concepts and style exploration, but with no prompt upsampling on Klein, a 3-word prompt leaves almost everything to the model. Underspecified prompts yield generic results — the model cannot enhance what you don''t describe. | ideal: Medium 30–80 words is "usually ideal for most projects" (BFL''s FLUX.2 guide). Klein-specific guidance adds a Long tier of 80–300+ words for complex editorial and detailed product shots — but only when every detail serves the image. fal.ai''s Klein guide warns prompts over ~100 words create confusion. Every sentence should add visual information. | too long: BFL documents prompt lengths up to 300+ words for complex scenes, but overstuffed prompts bury key details — with only 4 denoising steps on distilled variants, front-load what matters. The diffusers pipeline exposes max_sequence_length (default 512); explicit truncation behavior is not documented by BFL.
Syntax — NOT supported: Weighting (word:1.4), Emphasis ((word)), Negative prompt
Negative prompt: NO — All distilled Klein variants are guidance-distilled and run at guidance 1.0 (CFG effectively off), so a negative prompt has no mechanism to act. Describe what you want, never what you don''t want. (Base/undistilled variants can use guidance > 1.0.)
Include: Photographer-grade lighting (single highest-impact element); Specific camera language; Concrete subject specifics; Spatial relationships and composition; HEX color codes for precise colors; Exact text in quotation marks for in-image typography
Avoid: Comma tag soup: beach, woman, camera, sitting, black dress, realistic; Quality-booster tags: masterpiece, best quality, ultra detailed; Word repetition: detailed detailed detailed; Contradictory instructions: sitting, standing, walking / photorealistic portrait, watercolor painting style; Explicit negatives: no blur, without text, don''t make it dark; Vague style: make it look good
Recommended settings: Steps 4 (distilled 4B / 9B / 9B KV — official HF example). Base variants: 50 steps, guidance 4.0 (official diffusers example).; Guidance / CFG Scale 1.0 for distilled variants (CFG effectively off — distilled guidance). Base variants support guidance above 1.0 (e.g. 4.0).; Resolution 1024×1024 is the official benchmark resolution and HF example. Family-wide guidance (BFL FLUX.2 guide): 1:1 → 1024×1024 / 1536×1536; 16:9 → 1920×1080; 9:16 → 1080×1920; 21:9 → 2048×864; min 64×64, max 4 MP; dimensions multiples of 16; up to 2 MP recommended for most use cases.; Scheduler / Sampler Not documented for Klein by BFL — left blank (the model is a rectified-flow transformer).; Dtype / Precision bfloat16 in official examples; official FP8 and NVFP4 quantized variants available.
Common mistakes: Prompting like it''s SDXL or FLUX.1; Relying on negative prompts; Expecting prompt upsampling; Using distilled variants for fine-tuning; Burying key details in overlong prompts', 'FLUX.2 [klein] is the compact, distilled member of the FLUX.2 family, released January 2026. It is a sub-second image generator designed for consumer GPUs: the distilled 4B and 9B variants run in just 4 steps at guidance 1.0. Unlike FLUX.1 (which used T5-XXL + CLIP-L) and FLUX.2 [dev]/[pro] (which use a Mistral-3 24B vision-language model), Klein uses a Qwen3 LLM as its sole text encoder — so prompting is pure natural-language prose aimed at an instruction-tuned language model, not CLIP-era tag lists. All distilled variants are step-distilled AND guidance-distilled (CFG effectively off), which means negative prompts have no mechanism to work. Base (undistilled) variants exist for fine-tuning and LoRA training, and official FP8 / NVFP4 quantized checkpoints reduce VRAM further. Variants: Variant Distilled? License Notes FLUX.2 [klein] 4B Yes (step + guidance) Apache 2.0 ~13 GB VRAM, sub-second consumer-GPU FLUX.2 [klein] 9B Yes (step + guidance) FLUX Non-Commercial ~29 GB VRAM (RTX 4090), flagship small model FLUX.2 [klein] 9B KV Yes (step + guidance) FLUX Non-Commercial KV caching for fast image editing — the recommended pick for multi-reference editing FLUX.2 [klein] 4B Base No (undistilled) Apache 2.0 For fine-tuning / LoRA / research; higher output diversity FLUX.2 [klein] 9B Base No (undistilled) FLUX Non-Commercial For fine-tuning / LoRA / maximum flexibility FP8 / NVFP4 quants — Same as parent size Official, built with NVIDIA: FP8 up to ~1.6× faster; NVFP4 up to ~2.7× faster on RTX 5080/5090', '[{"url":"https://bfl.ai/blog/flux2-klein-towards-interactive-visual-intelligence","note":"https://bfl.ai/blog/flux2-klein-towards-interactive-visual-intelligence"},{"url":"https://github.com/black-forest-labs/flux2","note":"https://github.com/black-forest-labs/flux2"},{"url":"https://huggingface.co/black-forest-labs/FLUX.2-klein-9B","note":"https://huggingface.co/black-forest-labs/FLUX.2-klein-9B"},{"url":"https://huggingface.co/black-forest-labs/FLUX.2-klein-4B","note":"https://huggingface.co/black-forest-labs/FLUX.2-klein-4B"},{"url":"https://huggingface.co/black-forest-labs/FLUX.2-klein-9b-kv","note":"https://huggingface.co/black-forest-labs/FLUX.2-klein-9b-kv"},{"url":"https://docs.bfl.ml/release-notes","note":"https://docs.bfl.ml/release-notes"},{"url":"https://docs.bfl.ai/guides/prompting_guide_flux2","note":"https://docs.bfl.ai/guides/prompting_guide_flux2"},{"url":"https://docs.bfl.ml/guides/prompting_unified_basics","note":"https://docs.bfl.ml/guides/prompting_unified_basics"},{"url":"https://docs.comfy.org/tutorials/flux/flux-2-klein","note":"https://docs.comfy.org/tutorials/flux/flux-2-klein"},{"url":"https://huggingface.co/docs/diffusers/main/api/pipelines/flux2","note":"https://huggingface.co/docs/diffusers/main/api/pipelines/flux2"},{"url":"https://fal.ai/learn/devs/flux-2-klein-prompt-guide","note":"https://fal.ai/learn/devs/flux-2-klein-prompt-guide"},{"url":"https://apatero.com/blog/flux-2-klein-prompting-techniques","note":"https://apatero.com/blog/flux-2-klein-prompting-techniques"},{"url":"https://github.com/mflux-community/mflux/blob/HEAD/src/mflux/models/flux2/README.md","note":"https://github.com/mflux-community/mflux/blob/HEAD/src/mflux/models/flux2/README.md"},{"url":"https://github.com/bmtaco/image-gen-prompting-guide/blob/HEAD/skills/flux/SKILL.md","note":"https://github.com/bmtaco/image-gen-prompting-guide/blob/HEAD/skills/flux/SKILL.md"},{"url":"https://github.com/cozy-art/super-skills/blob/HEAD/skills/image/flux-v2/SKILL.md","note":"https://github.com/cozy-art/super-skills/blob/HEAD/skills/image/flux-v2/SKILL.md"},{"url":"https://github.com/vincentgourbin/flux-2-swift-mlx/blob/HEAD/docs/TextEncoders.md","note":"https://github.com/vincentgourbin/flux-2-swift-mlx/blob/HEAD/docs/TextEncoders.md"},{"url":"https://aihaberleri.org/en/news/flux2-klein-the-ai-image-generation-revolution-in-under-a-second","note":"https://aihaberleri.org/en/news/flux2-klein-the-ai-image-generation-revolution-in-under-a-second"}]', 'c7c36ebeb403617ba08720b9b6604651');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('image/general-image/0', 'image', 'general-image', 'General Image Tips', 'Families & Universals', 'families & universals', 0, 'image', 'General Image-Prompting Tips (Cross-Family)', 'models/image/general-image-tips.md', 4, 'Describe what should be visible, concretely and in order of importance. Modern encoders (LLM/VLM or T5) reward specific visual language — subject, camera, light, material — and punish vague praise. The two things that do not transfer across families are negative-prompt behavior and tag-vs-prose style: those are architecture-specific and are called out per family below.', '[]', '[]', '', '[]', '[]', '[]', '[{"title":"Copying SDXL tag habits onto VLM/T5 models","detail":"(or vice versa) — tag soup, weight syntax, and booster tags are architecture-specific; check the family first."},{"title":"Assuming negative prompts behave the same everywhere","detail":"— essential on SDXL, sentence-form on Qwen-2.0 APIs, near-useless on 1.x-era Qwen, keyword-list on WAN, minimal effect on FLUX."},{"title":"Describing text instead of quoting it","detail":"— universal failure across all families."},{"title":"Vague adjectives as a substitute for camera/light/material language","detail":"— \"cinematic\" is not a lighting setup."},{"title":"Changing seed and wording simultaneously","detail":"— lock the seed to isolate what the wording changed."},{"title":"Expecting text rendering from models that are weak at it","detail":"(WAN, FLUX.1) — route text-heavy work to Qwen-Image/HunyuanImage."}]', 'Target model: General Image Tips Families & Universals (image).
How to prompt it: Describe what should be visible, concretely and in order of importance. Modern encoders (LLM/VLM or T5) reward specific visual language — subject, camera, light, material — and punish vague praise. The two things that do not transfer across families are negative-prompt behavior and tag-vs-prose style: those are architecture-specific and are called out per family below.
Common mistakes: Copying SDXL tag habits onto VLM/T5 models; Assuming negative prompts behave the same everywhere; Describing text instead of quoting it; Vague adjectives as a substitute for camera/light/material language; Changing seed and wording simultaneously', 'This file collects prompting knowledge that applies beyond a single model: universal principles that hold across nearly all modern image generators, plus per-family notes on Seedance (video-only — included so nobody looks for it here), the WAN image-capable models, and other major image families (Stable Diffusion 3.5, the SDXL/SD tag-style family, HunyuanImage, and brief notes where documentation exists). Every section marks what transfers and what does not.', '[{"url":"https://github.com/nickpittas/directorsconsole/blob/HEAD/CinemaPromptEngineering/Documentation/model_prompting/stable_diffusion_3.md","note":"https://github.com/nickpittas/directorsconsole/blob/HEAD/CinemaPromptEngineering/Documentation/model_prompting/stable_diffusion_3.md (SD 3.5 official-guidance summary: natural language, style first, structure)"},{"url":"https://stability.ai/learning-hub/stable-diffusion-3-5-prompt-guide","note":"https://stability.ai/learning-hub/stable-diffusion-3-5-prompt-guide (cited as the SD 3.5 source)"},{"url":"https://github.com/Wan-Video/Wan2.1","note":"https://github.com/Wan-Video/Wan2.1 (official: Wan2.1 unified image+video, t2i-14B task)"},{"url":"https://huggingface.co/Wan-AI/Wan2.1-FLF2V-14B-720P","note":"https://huggingface.co/Wan-AI/Wan2.1-FLF2V-14B-720P (official t2i command examples)"},{"url":"https://github.com/s-nagaev/chibi/blob/HEAD/skills/wan_prompting_skill.md","note":"https://github.com/s-nagaev/chibi/blob/HEAD/skills/wan_prompting_skill.md (WAN prompting skill: 100–150 word narrative, T5-XXL semantic understanding)"},{"url":"https://github.com/fastflair/wan2gp/blob/HEAD/docs/PROMPTS.md","note":"https://github.com/fastflair/wan2gp/blob/HEAD/docs/PROMPTS.md (instruction-style edit prompts; Wan2.1 Chrono Edit strictness)"},{"url":"https://gist.github.com/joshalanwagner/66fea2d0b2bf33e29a7527e7f225d11e","note":"https://gist.github.com/joshalanwagner/66fea2d0b2bf33e29a7527e7f225d11e (T2I shootout: WAN adherence wins, speed, anatomy issues)"},{"url":"https://github.com/issac-new/swarmteam/blob/HEAD/skills/devops/chinese-image-api-integration/SKILL.md","note":"https://github.com/issac-new/swarmteam/blob/HEAD/skills/devops/chinese-image-api-integration/SKILL.md (DashScope SKUs: qwen-image-3.0-pro, wanx2.1-t2i-plus/turbo, wan2.7-image, z-image-turbo)"},{"url":"https://github.com/modbender/skill-library-mcp/blob/HEAD/data/seedance2-api/SKILL.md","note":"https://github.com/modbender/skill-library-mcp/blob/HEAD/data/seedance2-api/SKILL.md (Seedance video-only workflow; Seedream 4.5 as the image companion)"},{"url":"https://pixverse.ai/en/blog/seedance-2-0-now-available-on-pixverse","note":"https://pixverse.ai/en/blog/seedance-2-0-now-available-on-pixverse (Seedance 2.0 T2V/I2V/transition/reference modes)"},{"url":"https://github.com/kinovi-ai/kinovi-models/blob/HEAD/models/seedance2-5/README.md","note":"https://github.com/kinovi-ai/kinovi-models/blob/HEAD/models/seedance2-5/README.md (Seedance 2.5 video generation)"},{"url":"https://huggingface.co/tencent/HunyuanImage-3.0/blob/main/system_prompt.py","note":"https://huggingface.co/tencent/HunyuanImage-3.0/blob/main/system_prompt.py (official recaption system prompt: style reinforcement 3–5×, subject/composition/environment/lighting dimensions)"},{"url":"https://github.com/Tencent-Hunyuan/HunyuanImage-3.0","note":"https://github.com/Tencent-Hunyuan/HunyuanImage-3.0 (official: prompt self-rewrite, showcase prompts with exact quoted bilingual copy)"},{"url":"https://huggingface.co/hollowstrawberry/stable-diffusion-guide","note":"https://huggingface.co/hollowstrawberry/stable-diffusion-guide (SD tag-style conventions: quality tags, EasyNegative)"},{"url":"https://www.bonsaistudio.io/blog/prompting-guide","note":"https://www.bonsaistudio.io/blog/prompting-guide (Danbooru tag prompting rules)"},{"url":"https://github.com/eagleeyevisionlabz/wayland-m3ta-0s/blob/HEAD/src/process/resources/skills-library/bodies/skills/design-creative/stable-diffusion-prompting/SKILL.md","note":"https://github.com/eagleeyevisionlabz/wayland-m3ta-0s/blob/HEAD/src/process/resources/skills-library/bodies/skills/design-creative/stable-diffusion-prompting/SKILL.md (FLUX natural-language rules, negative-prompt minimal effect)"},{"url":"https://github.com/slahiri/comfyui-ai-photography-toolkit/blob/HEAD/docs/Z-IMAGE-PROMPTING-GUIDE.md","note":"https://github.com/slahiri/comfyui-ai-photography-toolkit/blob/HEAD/docs/Z-IMAGE-PROMPTING-GUIDE.md (Z-Image vs SD differences table)"},{"url":"https://github.com/mohamedabdallah-14/prompt-to-asset/blob/HEAD/docs/research/06-stable-diffusion-flux/6b-flux-family-prompting.md","note":"https://github.com/mohamedabdallah-14/prompt-to-asset/blob/HEAD/docs/research/06-stable-diffusion-flux/6b-flux-family-prompting.md (FLUX family prompting research)"}]', '7baf1eb5bf574b7b8e5ce4d414229daf');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('image/krea-2/0', 'image', 'krea-2', 'Krea 2', 'Raw', 'raw', 0, 'image', 'Prompt Guide: Krea 2 (Raw)', 'models/image/krea-2.md', 4, 'Write flowing natural-language prose, not tag lists — Krea 2 was trained on natural language and punishes keyword stuffing. Describe the scene concretely in one cohesive paragraph: subject, setting, shot, camera, style, lighting. Start simple and add detail only where you need control; the model''s aesthetic sense fills gaps.', '[{"syntax":"Weighting (word:1.4)","supported":"no","notes":"No evidence of support; the model follows direct description — emphasize by describing, not weighting."},{"syntax":"Emphasis ((word))","supported":"no","notes":"Same as above; avoid CLIP-era syntax."},{"syntax":"BREAK keyword","supported":"no","notes":"CLIP-tooling-specific; not applicable to the Qwen3-VL encoder path."},{"syntax":"[from:to:step] blending","supported":"no","notes":"No evidence in official docs or community workflows."},{"syntax":"Negative prompt","supported":"yes","notes":"Raw runs real CFG, so a true negative prompt works — a meaningful difference from Turbo, whose negative is zeroed out."},{"syntax":"Special / trigger tokens","supported":"yes","notes":"LoRA trigger words are supported; Raw has the best LoRA fidelity of the family."},{"syntax":"Regional / masked prompting","supported":"unknown","notes":"No official documentation found."}]', '[{"length":"Too short","effect":"Under ~5 words → the model improvises freely; fine for exploration, unreliable for directed work."},{"length":"Ideal","effect":"30–80 words of flowing prose for controlled generation; 80–140 for complex multi-element scenes. One cohesive paragraph, no bullets/JSON/markdown."},{"length":"Too long","effect":"Over-specification backfires: inventing hyper-specific clothing/colors/materials the input doesn''t imply degrades faithfulness. Respect existing detail — polish, don''t bloat."}]', '[Subject with key attributes] + [setting/scene] + [shot type + camera/lens] + → [visual style/medium] + [lighting] + [mood] + [texture, palette, material detail]', '[{"include":"Flowing natural-language description","examples":"A tiny figure and a small white dog sit side-by-side in the deep green shadow of a massive tree"},{"include":"Real medium grounding (anti \"AI-plastic\")","examples":"shot on 35mm, Kodak Portra 400, visible grain, natural skin texture, visible pores, no retouching"},{"include":"Technical photo detail words","examples":"shallow depth of field, golden hour, soft natural lighting, bokeh background"},{"include":"Exact text in quotes for text rendering","examples":"a sign reading \"FRESH COFFEE\""},{"include":"Concrete spatial relationships","examples":"steps carefully through knee-deep water, rests in the lower left foreground"},{"include":"Mood words when tone matters","examples":"eerie folk horror mood, serene, cinematic noir"}]', '[{"instead":"Comma-soup tag lists (girl, neon, 8k, masterpiece)","write":"Full clauses: A cinematic close-up of a cyberpunk girl..."},{"instead":"Quality buzzwords (8k, masterpiece, ultra-detailed, trending on artstation)","write":"Nothing — drop them; they reduce prompt clarity and degrade accuracy"},{"instead":"flawless, smooth, perfect, hyperdetailed","write":"natural skin texture, visible pores, candid framing (avoids the glossy AI look)"},{"instead":"Contradictory styles (photorealistic oil painting)","write":"One medium: photorealistic OR oil painting"},{"instead":"Vague praise (beautiful, amazing, awesome)","write":"Concrete visual descriptors"},{"instead":"Over-specifying invented details","write":"Respect the input; don''t invent clothing/colors/materials it doesn''t imply"}]', '[{"param":"Steps","value":"~20–52 (official example: 52; community workflows: 20–28)"},{"param":"Guidance / CFG Scale","value":"3.0–5.5 (official example: 3.5; InvokeAI default maps guidance 4.5 ≈ CFG 5.5)"},{"param":"Resolution","value":"Up to 1K (trained to 1K); 1024×1024 default"},{"param":"Scheduler / Sampler","value":"Standard full sampler with CFG (reference inference.py pipeline)"},{"param":"Dtype / Precision","value":"FP8 recommended on 24GB cards; GGUF Q4_K for lower VRAM"}]', '[{"title":"Writing SDXL-style tag soup","detail":"→ Krea 2 is trained on natural language; keyword lists degrade accuracy. Use flowing sentences."},{"title":"Stuffing quality buzzwords","detail":"(8k, masterpiece, trending on artstation) → documented to reduce prompt clarity and visual accuracy on Krea 2."},{"title":"Using \"flawless / perfect / hyperdetailed\"","detail":"→ brings back the glossy AI-plastic look; ground with real medium + texture cues instead."},{"title":"Bullets, JSON, or markdown in the prompt","detail":"→ Krea''s base-agent rules require one cohesive paragraph; structured wrappers leak into nothing useful."},{"title":"Over-specifying invented details","detail":"→ if the input doesn''t imply specific clothing/colors/materials, don''t invent them; polish, don''t bloat."}]', 'Target model: Krea 2 Raw (image).
How to prompt it: Write flowing natural-language prose, not tag lists — Krea 2 was trained on natural language and punishes keyword stuffing. Describe the scene concretely in one cohesive paragraph: subject, setting, shot, camera, style, lighting. Start simple and add detail only where you need control; the model''s aesthetic sense fills gaps.
Prompt length — too short: Under ~5 words → the model improvises freely; fine for exploration, unreliable for directed work. | ideal: 30–80 words of flowing prose for controlled generation; 80–140 for complex multi-element scenes. One cohesive paragraph, no bullets/JSON/markdown. | too long: Over-specification backfires: inventing hyper-specific clothing/colors/materials the input doesn''t imply degrades faithfulness. Respect existing detail — polish, don''t bloat.
Syntax — supported: Negative prompt, Special / trigger tokens | NOT supported: Weighting (word:1.4), Emphasis ((word)), BREAK keyword, [from:to:step] blending
Negative prompt: YES — Raw runs real CFG, so a true negative prompt works — a meaningful difference from Turbo, whose negative is zeroed out.
Include: Flowing natural-language description; Real medium grounding (anti "AI-plastic"); Technical photo detail words; Exact text in quotes for text rendering; Concrete spatial relationships; Mood words when tone matters
Avoid: Comma-soup tag lists (girl, neon, 8k, masterpiece); Quality buzzwords (8k, masterpiece, ultra-detailed, trending on artstation); flawless, smooth, perfect, hyperdetailed; Contradictory styles (photorealistic oil painting); Vague praise (beautiful, amazing, awesome); Over-specifying invented details
Recommended settings: Steps ~20–52 (official example: 52; community workflows: 20–28); Guidance / CFG Scale 3.0–5.5 (official example: 3.5; InvokeAI default maps guidance 4.5 ≈ CFG 5.5); Resolution Up to 1K (trained to 1K); 1024×1024 default; Scheduler / Sampler Standard full sampler with CFG (reference inference.py pipeline); Dtype / Precision FP8 recommended on 24GB cards; GGUF Q4_K for lower VRAM
Common mistakes: Writing SDXL-style tag soup; Stuffing quality buzzwords; Using "flawless / perfect / hyperdetailed"; Bullets, JSON, or markdown in the prompt; Over-specifying invented details', 'Krea 2 is a ~12.9B-parameter diffusion-transformer text-to-image model paired with a Qwen3-VL 4B text encoder (roughly 17.3B parameters total), released by Krea AI. Unlike CLIP-era models it is trained on natural-language captions and is "faithfulness first": it follows direct, concrete descriptions accurately without needing artificial weighting or quality buzzwords. The Raw checkpoint is the undistilled base: it runs with real classifier-free guidance over ~20–52 steps, supports genuine negative prompts, generates natively up to 1K resolution, and is the recommended checkpoint for LoRA training (Krea''s official guidance: train LoRAs on Raw, apply them on Turbo for inference). For the distilled few-step variant, see the Turbo guide.', '[{"url":"https://github.com/krea-ai/krea-2/blob/main/docs/prompting.md","note":"https://github.com/krea-ai/krea-2/blob/main/docs/prompting.md (official prompting guidelines: natural language, long detailed prompts, quoted text rendering, example prompts; all examples generated on Turbo at 2K)"},{"url":"https://github.com/krea-ai/krea-2/blob/HEAD/README.md","note":"https://github.com/krea-ai/krea-2/blob/HEAD/README.md (Raw vs Turbo checkpoints, official inference settings: Raw 52 steps / CFG 3.5, Turbo 8 steps / CFG 0, mu 1.15; resolutions)"},{"url":"https://modl.run/guides/krea-2/","note":"https://modl.run/guides/krea-2/ (Raw vs Turbo table: steps, guidance, negatives, LoRA; Qwen3-VL 4B encoder; 12.9B MMDiT)"},{"url":"https://github.com/polymath-wtf/kinodel-ide/blob/HEAD/skills/prompt-engine/krea2/krea-prompting-guide.md","note":"https://github.com/polymath-wtf/kinodel-ide/blob/HEAD/skills/prompt-engine/krea2/krea-prompting-guide.md (base-agent structure: subject/mood/style/composition/lighting/grounded details; one-paragraph rule)"},{"url":"https://github.com/mskiller/wildcard-prompt-studio/blob/HEAD/docs/KREA2_PROMPTING_GUIDE.md","note":"https://github.com/mskiller/wildcard-prompt-studio/blob/HEAD/docs/KREA2_PROMPTING_GUIDE.md (natural language priority, faithfulness first, zero buzzword pollution; Turbo variant preset)"},{"url":"https://github.com/apothis/crucible/blob/HEAD/docs/KREA2.md","note":"https://github.com/apothis/crucible/blob/HEAD/docs/KREA2.md (natural-language prose ordering; anti-AI-plastic cues; negative-prompt behavior)"},{"url":"https://github.com/weikinhuang/dotfiles/blob/HEAD/./config/pi/skills/krea2-prompting/SKILL.md","note":"https://github.com/weikinhuang/dotfiles/blob/HEAD/./config/pi/skills/krea2-prompting/SKILL.md (word-count guidelines; quoted text rendering; no negative prompt on the distilled path)"}]', '75ca0e39a9507018deb33aef73dfb3b6');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('image/krea-2/1', 'image', 'krea-2', 'Krea 2', 'Turbo', 'turbo', 1, 'image', 'Prompt Guide: Krea 2 Turbo', 'models/image/krea-2-turbo.md', 4, 'Write concise, punchy natural language focused on subject, lighting, and camera angle — Turbo''s distilled weights already carry the aesthetic and guidance, so you steer with clear content and look, not with quality buzzwords, weighting syntax, or negatives (which are ignored). Keep it tight, generate fast, and iterate: Turbo''s speed makes the explore → refine loop the real prompt-engineering tool.', '[{"syntax":"Weighting (word:1.4)","supported":"no","notes":"No evidence of support; emphasize by describing."},{"syntax":"Emphasis ((word))","supported":"no","notes":"Same as above."},{"syntax":"BREAK keyword","supported":"no","notes":"CLIP-tooling-specific; not applicable."},{"syntax":"[from:to:step] blending","supported":"no","notes":"No evidence in official docs or community workflows."},{"syntax":"Negative prompt","supported":"no","notes":"Turbo is CFG-distilled: the negative conditioning is zeroed out (ConditioningZeroOut in ComfyUI graphs) and diffusers ignores negative_prompt when guidance ≤ 0. Exclusions must be phrased positively in the prompt."},{"syntax":"Special / trigger tokens","supported":"yes","notes":"LoRA trigger words work; official guidance is to train LoRAs on Raw and apply them on Turbo."},{"syntax":"Regional / masked prompting","supported":"unknown","notes":"No official documentation found."}]', '[{"length":"Too short","effect":"Under ~5 words → heavy improvisation; fine for Turbo''s fast exploration loops, unreliable for directed output."},{"length":"Ideal","effect":"10–40 words for quick iterations; 30–80 words of flowing prose for controlled generation. One cohesive paragraph, no bullets/JSON/markdown."},{"length":"Too long","effect":"Over-specification and buzzword padding waste Turbo''s main advantage (speed) and can muddy the few-step sampler; prefer clear clauses over long run-ons."}]', '[Subject with key attributes] + [setting] + [composition/shot] + → [lighting] + [medium/style] + [texture/palette detail]', '[{"include":"Concrete subject + action in plain sentences","examples":"A cinematic close-up of a cyberpunk girl with glowing neon implants..."},{"include":"Lighting and camera angle (Turbo''s highest-leverage tokens)","examples":"neon glow with deep shadows, dramatic rim lighting, low-angle, close-up"},{"include":"Real medium grounding","examples":"shot on 35mm, Kodak Portra 400, visible grain, natural skin texture"},{"include":"Exact quoted text for text rendering","examples":"a \"HELLO\" sign in neon"},{"include":"Specific colors, materials, spatial relations","examples":"oversized gold-rimmed aviator sunglasses, index finger touching a subtle smile"},{"include":"Mood in a word or two","examples":"noir, serene, eerie folk horror"}]', '[{"instead":"Relying on a negative prompt (negative: blurry, deformed)","write":"Phrase it positively: clean, sharp, well-formed hands — Turbo''s negative is zeroed"},{"instead":"Raising CFG to \"sharpen\" the image","write":"Leave CFG at 0/1.0 — raising it degrades Turbo output; iterate the prompt and seed instead"},{"instead":"Quality buzzwords (8k, masterpiece, trending on artstation)","write":"Nothing — they reduce clarity and degrade accuracy"},{"instead":"(word:1.4) / ((word)) / BREAK","write":"Plain descriptive sentences; the encoder doesn''t parse these"},{"instead":"Long over-engineered prompts for a quick test","write":"Start short (5–20 words), use Turbo''s speed to explore, then add detail"},{"instead":"flawless, smooth, perfect, hyperdetailed","write":"natural skin texture, visible pores, no retouching, candid framing"}]', '[{"param":"Steps","value":"8 (the checkpoint was distilled for 8 steps)"},{"param":"Guidance / CFG Scale","value":"0 (disabled) / 1.0 — do not raise; raising CFG degrades the image"},{"param":"Resolution","value":"1024–2048 (up to 2K); all official examples generated at 2K"},{"param":"Scheduler / Sampler","value":"Few-step distilled sampler per the reference inference.py pipeline"},{"param":"Timestep-shift mu","value":"1.15 recommended for Turbo (official README)"},{"param":"Dtype / Precision","value":"FP8 recommended on 24GB cards; GGUF Q4_K for lower VRAM"}]', '[{"title":"Raising CFG to \"improve\" Turbo","detail":"→ distilled models degrade with CFG > 0/1.0; iterate prompt and seed instead."},{"title":"Depending on a negative prompt","detail":"→ it''s zeroed out on Turbo; any exclusion must be stated positively in the prompt."},{"title":"Over-engineering the first prompt","detail":"→ Turbo''s advantage is speed; start at 5–20 words, explore, then narrow like an art director."},{"title":"CLIP-era syntax","detail":"((word:1.4), ((word)), BREAK) → inert on Krea 2; use descriptive sentences."},{"title":"Buzzword padding","detail":"(8k, masterpiece, trending on artstation) → documented to reduce clarity and accuracy."},{"title":"Training LoRAs on Turbo","detail":"→ not recommended; official guidance is train on Raw, apply on Turbo."}]', 'Target model: Krea 2 Turbo (image).
How to prompt it: Write concise, punchy natural language focused on subject, lighting, and camera angle — Turbo''s distilled weights already carry the aesthetic and guidance, so you steer with clear content and look, not with quality buzzwords, weighting syntax, or negatives (which are ignored). Keep it tight, generate fast, and iterate: Turbo''s speed makes the explore → refine loop the real prompt-engineering tool.
Prompt length — too short: Under ~5 words → heavy improvisation; fine for Turbo''s fast exploration loops, unreliable for directed output. | ideal: 10–40 words for quick iterations; 30–80 words of flowing prose for controlled generation. One cohesive paragraph, no bullets/JSON/markdown. | too long: Over-specification and buzzword padding waste Turbo''s main advantage (speed) and can muddy the few-step sampler; prefer clear clauses over long run-ons.
Syntax — supported: Special / trigger tokens | NOT supported: Weighting (word:1.4), Emphasis ((word)), BREAK keyword, [from:to:step] blending, Negative prompt
Negative prompt: NO — Turbo is CFG-distilled: the negative conditioning is zeroed out (ConditioningZeroOut in ComfyUI graphs) and diffusers ignores negative_prompt when guidance ≤ 0. Exclusions must be phrased positively in the prompt.
Include: Concrete subject + action in plain sentences; Lighting and camera angle (Turbo''s highest-leverage tokens); Real medium grounding; Exact quoted text for text rendering; Specific colors, materials, spatial relations; Mood in a word or two
Avoid: Relying on a negative prompt (negative: blurry, deformed); Raising CFG to "sharpen" the image; Quality buzzwords (8k, masterpiece, trending on artstation); (word:1.4) / ((word)) / BREAK; Long over-engineered prompts for a quick test; flawless, smooth, perfect, hyperdetailed
Recommended settings: Steps 8 (the checkpoint was distilled for 8 steps); Guidance / CFG Scale 0 (disabled) / 1.0 — do not raise; raising CFG degrades the image; Resolution 1024–2048 (up to 2K); all official examples generated at 2K; Scheduler / Sampler Few-step distilled sampler per the reference inference.py pipeline; Timestep-shift mu 1.15 recommended for Turbo (official README); Dtype / Precision FP8 recommended on 24GB cards; GGUF Q4_K for lower VRAM
Common mistakes: Raising CFG to "improve" Turbo; Depending on a negative prompt; Over-engineering the first prompt; CLIP-era syntax; Buzzword padding', 'Krea 2 Turbo is the distilled version of Krea 2 (same ~12.9B diffusion transformer + Qwen3-VL 4B text encoder), produced by TDM distillation into an 8-step sampler. Distillation bakes classifier-free guidance into the weights: CFG is disabled (0 / 1.0), and any negative prompt is zeroed out rather than encoded — the model "answers in one pass, already as though it had been guided." It generates natively at 1K–2K resolution and is the recommended checkpoint for everyday use and fast iteration; the undistilled Raw checkpoint remains the one for LoRA training and prompts that need real guidance. Prompting follows the same natural-language rules as Raw, but Turbo rewards concise, punchy prose and fast explore-iterate loops over heavy prompt engineering.', '[{"url":"https://github.com/krea-ai/krea-2/blob/main/docs/prompting.md","note":"https://github.com/krea-ai/krea-2/blob/main/docs/prompting.md (official prompting guidelines; all examples generated on Turbo at 2K)"},{"url":"https://github.com/krea-ai/krea-2/blob/HEAD/README.md","note":"https://github.com/krea-ai/krea-2/blob/HEAD/README.md (Turbo: 8 steps, CFG 0, mu 1.15, 1K–2K; Raw: 52 steps, CFG 3.5, 1K)"},{"url":"https://github.com/alperktt/krea-2-svdquant-comfyui/blob/HEAD/workflows/README.md","note":"https://github.com/alperktt/krea-2-svdquant-comfyui/blob/HEAD/workflows/README.md (Turbo vs base: cfg-distilled, negative zeroed via ConditioningZeroOut, raising cfg degrades)"},{"url":"https://modl.run/guides/krea-2/","note":"https://modl.run/guides/krea-2/ (Raw vs Turbo comparison table; encoder details; \"reach for Turbo when you want a picture, Raw when you want control\")"},{"url":"https://github.com/catnuko/gisflow/blob/HEAD/docs/src/content/docs/features/krea-2.mdx","note":"https://github.com/catnuko/gisflow/blob/HEAD/docs/src/content/docs/features/krea-2.mdx (Turbo 8 steps CFG 1.0; Raw ~28 steps CFG ~5.5 with negatives)"},{"url":"https://github.com/mskiller/wildcard-prompt-studio/blob/HEAD/docs/KREA2_PROMPTING_GUIDE.md","note":"https://github.com/mskiller/wildcard-prompt-studio/blob/HEAD/docs/KREA2_PROMPTING_GUIDE.md (Turbo preset: concise punchy natural language — subject, lighting, camera angle)"},{"url":"https://github.com/ling0322/libwaifu/commit/1c290aef49ac46a01d5c06b79c2cfc27eeb25064","note":"https://github.com/ling0322/libwaifu/commit/1c290aef49ac46a01d5c06b79c2cfc27eeb25064 (distilled models: no guider, negative_prompt ignored when guidance ≤ 0)"}]', 'a2c0fab085172c49d92f447fd628188f');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('image/qwen-image/0', 'image', 'qwen-image', 'Qwen-Image', '2.x', '2.x', 0, 'image', 'Prompt Guide: Qwen-Image 2.x', 'models/image/qwen-image-2.x.md', 6, 'Write natural-language sentences and paragraphs, not tag lists. The Qwen-VL text encoder weights earlier tokens more heavily, so the subject — the most important element — must come first.', '[{"syntax":"Weighting (word:1.4)","supported":"no","notes":"Not parsed by the VLM encoder; reported to cause artifacts"},{"syntax":"Emphasis ((word))","supported":"no","notes":"Same as above"},{"syntax":"BREAK keyword","supported":"no","notes":""},{"syntax":"[from:to:step] blending","supported":"no","notes":""},{"syntax":"Negative prompt","supported":"yes","notes":"2.0/API: works best as full NLP sentences, not keyword dumps. 1.x-era finding: negative prompts were nearly ineffective for content exclusion; mold docs recommend starting with no negative prompt at all and only adding one for a specific failure mode. 2.1: CFG is off by default; passing negative_prompt + true_cfg_scale > 1 turns guidance on (doubles compute per step)."},{"syntax":"Special / trigger tokens","supported":"partial","notes":"The 2.1 transparent mode uses a fixed natural-language trigger phrase (see Prompt Examples); no special token syntax"},{"syntax":"Regional / masked prompting","supported":"partial","notes":"2.1 supports local edits specified via circles, painted annotations, or separate masks; no token-based regional syntax"}]', '[{"length":"Too short","effect":"Under ~10 words leaves composition, lighting, and style to chance; the model''s prompt-rewrite/expansion features exist precisely because short prompts underperform"},{"length":"Ideal","effect":"15–50 words for simple portrait/landscape; 50–150 words for standard production images; 100–300 words for posters/products with text; 300–500+ words for infographics/slides (2.0, up to ~1,000 tokens). Alibaba recommends using the official prompt-rewriting models (Qwen-Image-2.1-PE-T2I / -PE-I2I) to expand short prompts into detailed descriptions"},{"length":"Too long","effect":"2.0 dense-layout ceiling ≈ 1,000 tokens; beyond that, later instructions lose attention (front-loading matters because the encoder weights early tokens more). Long prompts also interact badly with enable_prompt_expansion auto-rewrites on API endpoints"}]', '[Subject + Core Action] → [Environment / Setting] → [Style / Rendering Mode] → [Lighting / Atmosphere] → [Text / Layout (if needed)]', '[{"include":"Front-loaded subject","examples":"Put the most important element in the first sentence"},{"include":"Natural-language sentences","examples":"\"standing in soft window light indoors. Candid, unposed expression.\""},{"include":"Exact in-image text in quotes","examples":"The sign reads \"GRAND OPENING\" in bold red letters"},{"include":"Chinese characters written directly","examples":"通义千问, 欢迎光临 — never romanized, never described"},{"include":"Font style + color + spatial placement for text","examples":"\"serif, bold, cream white, top-center\"; \"small widely-spaced capitals directly beneath\""},{"include":"Multilingual script relationships","examples":"\"on the same line\", \"stacked directly beneath\" — matched size and weight"},{"include":"One clear style anchor","examples":"\"Editorial photography style\" / \"Flat editorial illustration, two-colour palette\""},{"include":"Camera language","examples":"\"aerial drone shot\", \"medium shot, eye level\", \"shallow depth of field\""},{"include":"Closing constraint for text work","examples":"\"No other text.\" — prevents invented lettering in margins"},{"include":"For RGBA (2.1)","examples":"This is an RGBA image with transparency. <description>. The image has alpha channel and the background is transparent."},{"include":"For multi-reference editing (2.1)","examples":"Explicit roles per image, e.g. \"Image 1: edit target, original cafe interior. Image 2: product identity reference.\""},{"include":"Magic quality suffix (1.0/2.0-era official examples)","examples":"English: , Ultra HD, 4K, cinematic composition. — Chinese: , 超清，4K，电影级构图."}]', '[{"instead":"masterpiece, best quality, 8k, ultra HD as quality boosters","write":"Describe the visual instead: \"sharp focus, fine fabric texture, crisp detail\" (these tokens are ignored by the VLM encoder)"},{"instead":"(keyword:1.4) or ((keyword)) weighting","write":"Plain emphasis through wording and front-loading"},{"instead":"Danbooru-style tag lists (1girl, blue_hair, sunset, ...)","write":"Full sentences: \"A young woman with blue hair standing at sunset\""},{"instead":"\"The Chinese word for orbit\" / describing text","write":"Paste the actual characters: 轨道力学"},{"instead":"Negation in the positive prompt (\"Not a child\", \"no people\")","write":"For 2.x this is unreliable; put exclusions in the negative-prompt parameter as sentences, or phrase positively (\"empty street, no people visible\" is inconsistent — describe the scene as if the unwanted element isn''t there)"},{"instead":"Generic negative keyword dumps (blurry, bad anatomy, ugly, deformed, watermark)","write":"Full sentences: \"No watermarks, no distorted faces, no blurry backgrounds, avoid artificial plastic skin texture\""},{"instead":"Leaving text-heavy margins undescribed","write":"End with \"no other text\" or list exactly which texts may appear"},{"instead":"enable_prompt_expansion: true during iteration","write":"Lock it to false — auto-rewrite makes results non-reproducible while testing wording"}]', '[{"param":"Steps","value":"2.0: 50 · 2.1: 40 (defaults; official recommendation)"},{"param":"Guidance / CFG Scale","value":"2.0: true_cfg_scale 4.0 · 2.1: off by default; true_cfg_scale > 1 + negative_prompt to enable"},{"param":"Resolution","value":"2.0: 1328×1328-class (1:1 → 1328×1328; 16:9 → 1664×928; 9:16 → 928×1664; 4:3 → 1472×1140; 3:4 → 1140×1472; 3:2 → 1584×1056; 2:3 → 1056×1584) · 2.1: native 2K (1:1 → 2048×2048; 4:3 → 2400×1792; 3:4 → 1792×2400; 3:2 → 2528×1696; 2:3 → 1696×2528; 16:9 → 2752×1536; 9:16 → 1536×2752)"},{"param":"Scheduler / Sampler","value":""},{"param":"Dtype / Precision","value":"bfloat16 recommended"}]', '[{"title":"Tag soup instead of sentences","detail":"— the VLM encoder was trained on language, not booru tags; tag lists produce worse results."},{"title":"Burying the subject","detail":"— anything after the first sentence gets less attention; front-load the key element."},{"title":"Describing text instead of quoting it","detail":"— \"a sign with Chinese characters\" never renders the intended words; paste them in quotes."},{"title":"SD-style weight syntax","detail":"— (word:1.3) is not parsed and may cause artifacts."},{"title":"Quality-booster padding","detail":"— \"masterpiece, 8k, ultra HD\" is ignored; describe observable detail instead."},{"title":"Iterating with prompt expansion on","detail":"— API auto-rewrite (enable_prompt_expansion) makes A/B comparisons meaningless; disable while testing."},{"title":"Negation in the positive prompt","detail":"— \"not a child\" introduces the word \"child\" and makes it worse; exclude via negative-prompt parameter or positive phrasing."}]', 'Target model: Qwen-Image 2.x (image).
How to prompt it: Write natural-language sentences and paragraphs, not tag lists. The Qwen-VL text encoder weights earlier tokens more heavily, so the subject — the most important element — must come first.
Prompt length — too short: Under ~10 words leaves composition, lighting, and style to chance; the model''s prompt-rewrite/expansion features exist precisely because short prompts underperform | ideal: 15–50 words for simple portrait/landscape; 50–150 words for standard production images; 100–300 words for posters/products with text; 300–500+ words for infographics/slides (2.0, up to ~1,000 tokens). Alibaba recommends using the official prompt-rewriting models (Qwen-Image-2.1-PE-T2I / -PE-I2I) to expand short prompts into detailed descriptions | too long: 2.0 dense-layout ceiling ≈ 1,000 tokens; beyond that, later instructions lose attention (front-loading matters because the encoder weights early tokens more). Long prompts also interact badly with enable_prompt_expansion auto-rewrites on API endpoints
Syntax — supported: Negative prompt | partial: Special / trigger tokens, Regional / masked prompting | NOT supported: Weighting (word:1.4), Emphasis ((word)), BREAK keyword, [from:to:step] blending
Negative prompt: YES — 2.0/API: works best as full NLP sentences, not keyword dumps. 1.x-era finding: negative prompts were nearly ineffective for content exclusion; mold docs recommend starting with no negative prompt at all and only adding one for a specific failure mode. 2.1: CFG is off by default; passing negative_prompt + true_cfg_scale > 1 turns guidance on (doubles compute per step).
Include: Front-loaded subject; Natural-language sentences; Exact in-image text in quotes; Chinese characters written directly; Font style + color + spatial placement for text; Multilingual script relationships
Avoid: masterpiece, best quality, 8k, ultra HD as quality boosters; (keyword:1.4) or ((keyword)) weighting; Danbooru-style tag lists (1girl, blue_hair, sunset, ...); "The Chinese word for orbit" / describing text; Negation in the positive prompt ("Not a child", "no people"); Generic negative keyword dumps (blurry, bad anatomy, ugly, deformed, watermark)
Recommended settings: Steps 2.0: 50 · 2.1: 40 (defaults; official recommendation); Guidance / CFG Scale 2.0: true_cfg_scale 4.0 · 2.1: off by default; true_cfg_scale > 1 + negative_prompt to enable; Resolution 2.0: 1328×1328-class (1:1 → 1328×1328; 16:9 → 1664×928; 9:16 → 928×1664; 4:3 → 1472×1140; 3:4 → 1140×1472; 3:2 → 1584×1056; 2:3 → 1056×1584) · 2.1: native 2K (1:1 → 2048×2048; 4:3 → 2400×1792; 3:4 → 1792×2400; 3:2 → 2528×1696; 2:3 → 1696×2528; 16:9 → 2752×1536; 9:16 → 1536×2752); Scheduler / Sampler ; Dtype / Precision bfloat16 recommended
Common mistakes: Tag soup instead of sentences; Burying the subject; Describing text instead of quoting it; SD-style weight syntax; Quality-booster padding', 'Qwen-Image 2.x is Alibaba''s second-generation image family (2026), aimed at "precision, variety, completeness, beauty, and authenticity." It is a unified text-to-image + image-editing architecture whose headline strength is multilingual text rendering (notably Chinese + English) inside images. Unlike 3.0 (closed, hosted-only), the 2.x line spans both hosted API releases and open weights. Prompting across the whole 2.x family is driven by one fact: the text encoder is a large vision-language LLM, not CLIP — so prompts behave like instructions to a language model. Per-version differences (documented): - Qwen-Image-2.0 (released May 2026): hosted/API flagship (fal.ai, DashScope qwen-image-2.0, qwen-image-2.0-pro). Recommended: 50 steps, true_cfg_scale 4.0, 1328×1328-class resolutions. Prompt budget up to ~1,000 tokens for dense layouts. - Qwen-Image-2.0-RL: RL-tuned variant of 2.0 (GRPO + on-policy distillation), reported +2.61 on Qwen-Image-Bench and arena Elo gains in T2I and edit. No separate prompting guidance published — use 2.0 guidance. - Qwen-Image-2512 (2025): open-weights sibling used for local/ComfyUI deployment; same prompt syntax as 2.0, prompt rewrites via enable_prompt_expansion on some endpoints. - Qwen-Image-2.1 (released 2026-09-20 — note: newer than 3.0): open weights under the Qwen Research License Agreement (non-commercial only), 7B visual-generation component (32 single-stream DiT layers) with Qwen3-VL encoding prompt + condition images jointly. New capabilities: native RGBA transparency, up to 10 reference images for editing, official prompt-rewriting models. Defaults: 40 steps, no guidance (CFG off) — guidance only activates if you pass negative_prompt together with true_cfg_scale > 1.', '[{"url":"https://github.com/QwenLM/Qwen-Image-2.1","note":"https://github.com/QwenLM/Qwen-Image-2.1 (official 2.1 README: defaults, aspect ratios, RGBA trigger phrase, prompt-rewrite models, multi-reference)"},{"url":"https://huggingface.co/Qwen/Qwen-Image-2.1/blob/main/README.md","note":"https://huggingface.co/Qwen/Qwen-Image-2.1/blob/main/README.md"},{"url":"https://huggingface.co/docs/diffusers/main/api/pipelines/qwenimage21","note":"https://huggingface.co/docs/diffusers/main/api/pipelines/qwenimage21 (Qwen3-VL joint encoding, 40 steps / no guidance defaults, negative_prompt + true_cfg_scale > 1 enables CFG)"},{"url":"https://www.orcarouter.ai/blog/qwen-image-2-1-vs-qwen-image-3-0","note":"https://www.orcarouter.ai/blog/qwen-image-2-1-vs-qwen-image-3-0 (version timeline, licensing positions, 2.1 newer than 3.0)"},{"url":"https://github.com/cozy-art/super-skills/blob/HEAD/skills/image/qwen-image-v2/SKILL.md","note":"https://github.com/cozy-art/super-skills/blob/HEAD/skills/image/qwen-image-v2/SKILL.md (front-loading rule, five-element framework, syntax rules, prompt-length table, negative-prompt format, workflow)"},{"url":"https://github.com/brndngln/nodetool/blob/HEAD/packages/system-skills/qwen-image-prompting/SKILL.md","note":"https://github.com/brndngln/nodetool/blob/HEAD/packages/system-skills/qwen-image-prompting/SKILL.md (\"quote the copy\" habits: write characters, state script relationships, close with \"no other text\")"},{"url":"https://github.com/yayimiko/astrbot_plugin_qwen_image/blob/HEAD/skills/qwen-image-21-prompt-expert/SKILL.md","note":"https://github.com/yayimiko/astrbot_plugin_qwen_image/blob/HEAD/skills/qwen-image-21-prompt-expert/SKILL.md (natural language over tags for 2.1, edit-mode policies)"},{"url":"https://github.com/utensils/mold/blob/HEAD/website/models/qwen-image.md","note":"https://github.com/utensils/mold/blob/HEAD/website/models/qwen-image.md (negative-prompt guidance: start with none; upstream Chinese negative prompt for full-precision paths)"},{"url":"https://blog.promptmaster.pro/posts/qwen-image-negative-prompts/","note":"https://blog.promptmaster.pro/posts/qwen-image-negative-prompts/ (community finding that 1.x-era negative prompts were ineffective for content exclusion)"},{"url":"https://arxiv.org/pdf/2606.27608","note":"https://arxiv.org/pdf/2606.27608 (Qwen-Image-2.0-RL technical report)"},{"url":"https://qwen-image.ai/blog/Qwen-Image-Practical-Guide","note":"https://qwen-image.ai/blog/Qwen-Image-Practical-Guide (text-rendering tips: font, size relationships, placement, quoting)"},{"url":"https://dev.to/aimodels-fyi/a-beginners-guide-to-the-qwen-image-2-pro-model-by-qwen-on-replicate-3k1","note":"https://dev.to/aimodels-fyi/a-beginners-guide-to-the-qwen-image-2-pro-model-by-qwen-on-replicate-3k1 (enable_prompt_expansion default-true behavior, negative-prompt notes)"}]', 'e88ee32aed5f3093cdfa57a11d151172');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('image/qwen-image/1', 'image', 'qwen-image', 'Qwen-Image', '3.x', '3.x', 1, 'image', 'Prompt Guide: Qwen-Image 3.x', 'models/image/qwen-image-3.x.md', 5, 'State the task first, then write the prompt as a layout/content specification, not a mood description. With a 4,500-token budget, the prompt''s job is to define the deliverable (use case, audience, reading order, exact verbatim copy, acceptance constraints) — adjectives like "stunning" or "epic" define no success criteria and should be replaced with observable composition, material, and lighting.', '[{"syntax":"Weighting (word:1.4)","supported":"no","notes":"(Generalization from 2.x: VLM-encoder family does not parse weight syntax — labeled generalization, not 3.0-documented)"},{"syntax":"Emphasis ((word))","supported":"no","notes":"(Same generalization)"},{"syntax":"BREAK keyword","supported":"unknown","notes":""},{"syntax":"[from:to:step] blending","supported":"unknown","notes":""},{"syntax":"Negative prompt","supported":"yes","notes":"API schema includes negative_prompt (cap ~500 chars on some endpoints); best as specific, executable constraints — see \"What to Avoid\""},{"syntax":"Special / trigger tokens","supported":"unknown","notes":""},{"syntax":"Regional / masked prompting","supported":"unknown","notes":""}]', '[{"length":"Too short","effect":"For short single-subject images the 4,500-token budget changes nothing; for dense layouts, underspecified prompts produce invented labels, numbers, and filler text"},{"length":"Ideal","effect":"Simple images: 15–50 words · standard production: 50–150 words · poster/product with text: 100–300 words · infographic/slide/multi-element layout: 300–500+ words. Use the full budget for multi-panel specs (example: nine infographic panels with diagrams, formulas, captions, and fine print rendered in a single pass)"},{"length":"Too long","effect":"\"Longer ≠ better\": give each line one responsibility; delete adjectives that don''t affect acceptance (replace \"8K, masterpiece\" with observable structure)"}]', '[Task layer] → [Visual layer] → [Content layer] → [Acceptance layer]', '[{"include":"The task in the first sentence","examples":"\"为一家社区咖啡馆制作 4:5 新店开业海报\" — what the image must accomplish, for whom"},{"include":"Exact copy as data, numbered verbatim","examples":"Text (verbatim): 1. \"城市缓慢生活节\" 2. \"WALK · TASTE · LISTEN\" 3. \"10.18—10.20\""},{"include":"A typography map for each text line","examples":"\"Line 1: 最大字号，现代宋体气质，顶部居中；Line 2: 窄体无衬线，全大写\""},{"include":"Layout skeleton before content","examples":"\"Layout: 3 columns × 3 rows, nine equal panels, 24px gutters.\" / \"Flow: left to right, exactly six nodes. Edges: 1→2→3→4→5→6, no branching.\""},{"include":"Reading order","examples":"\"Reading order: 标题 → 剖面主图 → 物种卡片 → 食物网 → 保护提示。\""},{"include":"Panel-by-panel specs for storyboards","examples":"\"Panel 1: a cat stares at an empty bowl, caption ''Monday''. Panel 2: cat knocks a mug off the table...\""},{"include":"Multilingual correspondence","examples":"Keep translated strings intact; state script relationships explicitly"},{"include":"Product lock for packaging","examples":"\"do not change silhouette, camera angle, cap, label size or liquid color\""},{"include":"Character identity anchor, repeated per panel","examples":"Visible traits list + \"Invariants: same identity, age, facial proportions, hairstyle, clothing colors and body proportions in every panel\""},{"include":"Reference-image roles for edits","examples":"\"Image 1: edit target ... Image 2: product identity reference\" — never \"参考一下这几张图\""},{"include":"Realism cues for photos","examples":"Lens + distance (\"50mm eye-level medium close-up\"), light source direction/size/color temperature, materials, imperfections, contact shadows"},{"include":"Anti-hallucination constraints","examples":"\"不翻译、不改写、不增加标点或宣传词\" / \"不生成任何其他可读文字\""}]', '[{"instead":"Style-first openers (\"高级、电影感\")","write":"Task-first: use case, audience, what must be understood"},{"instead":"Vague text requests (\"add a nice title\")","write":"Verbatim numbered copy + typography map + placement"},{"instead":"\"Free layout\" for dense content","write":"Explicit grids, node counts, edge lists"},{"instead":"Generic negative constraints (\"不要丑、不要 AI 感\")","write":"Executable: \"Avoid: duplicate products or floating props; malformed hands, mirrored labels or extra letters; unrelated logos, signatures and watermarks; decorative microtext that is not listed in Text (verbatim).\""},{"instead":"Demanding \"flawless\" AND \"candid\" simultaneously","write":"Decide: catalog product shot vs documentary photo"},{"instead":"Changing style mid-iteration when text is wrong","write":"Single-variable iteration: V1 composition → V2 exact text → V3 materials/light → V4 publish crop"}]', '[{"param":"Steps","value":""},{"param":"Guidance / CFG Scale","value":""},{"param":"Resolution","value":""},{"param":"Scheduler / Sampler","value":""},{"param":"Dtype / Precision","value":""}]', '[{"title":"Leading with style instead of the task","detail":"— \"stunning, cinematic\" defines no success criteria; lead with use case, audience, and what must be readable."},{"title":"Describing text instead of supplying it","detail":"— paste exact copy verbatim; the model renders what you give it, not what you mean."},{"title":"Leaving dense layouts \"free\"","detail":"— specify panel counts, grids, node/edge lists, and reading order."},{"title":"Skipping the acceptance layer","detail":"— without explicit prohibitions (\"no invented numbers\", \"no other text\"), the model fills gaps with plausible fabrications."},{"title":"Iterating on multiple variables at once","detail":"— if V2 changes style while fixing text, you can''t tell which change caused the result."},{"title":"Reviewing only at zoom","detail":"— check 10–14px small text at the intended display size, not just enlarged."},{"title":"Trusting model-generated facts","detail":"— for data/science/medical diagrams, supply reviewed content; use the model for layout, not derivation."}]', 'Target model: Qwen-Image 3.x (image).
How to prompt it: State the task first, then write the prompt as a layout/content specification, not a mood description. With a 4,500-token budget, the prompt''s job is to define the deliverable (use case, audience, reading order, exact verbatim copy, acceptance constraints) — adjectives like "stunning" or "epic" define no success criteria and should be replaced with observable composition, material, and lighting.
Prompt length — too short: For short single-subject images the 4,500-token budget changes nothing; for dense layouts, underspecified prompts produce invented labels, numbers, and filler text | ideal: Simple images: 15–50 words · standard production: 50–150 words · poster/product with text: 100–300 words · infographic/slide/multi-element layout: 300–500+ words. Use the full budget for multi-panel specs (example: nine infographic panels with diagrams, formulas, captions, and fine print rendered in a single pass) | too long: "Longer ≠ better": give each line one responsibility; delete adjectives that don''t affect acceptance (replace "8K, masterpiece" with observable structure)
Syntax — supported: Negative prompt | NOT supported: Weighting (word:1.4), Emphasis ((word))
Negative prompt: YES — API schema includes negative_prompt (cap ~500 chars on some endpoints); best as specific, executable constraints — see "What to Avoid"
Include: The task in the first sentence; Exact copy as data, numbered verbatim; A typography map for each text line; Layout skeleton before content; Reading order; Panel-by-panel specs for storyboards
Avoid: Style-first openers ("高级、电影感"); Vague text requests ("add a nice title"); "Free layout" for dense content; Generic negative constraints ("不要丑、不要 AI 感"); Demanding "flawless" AND "candid" simultaneously; Changing style mid-iteration when text is wrong
Recommended settings: Steps ; Guidance / CFG Scale ; Resolution ; Scheduler / Sampler ; Dtype / Precision 
Common mistakes: Leading with style instead of the task; Describing text instead of supplying it; Leaving dense layouts "free"; Skipping the acceptance layer; Iterating on multiple variables at once', 'Qwen-Image-3.0 (invite-only launch 2026-07-21, general availability 2026-08-05) is the third generation of Alibaba''s image line, and it is a different product line from 2.x — note that 2.1 (2026-09-20) is actually newer than 3.0. Where 2.x balances generation quality with open weights, 3.0 is closed: no weights, no stated license, no model card, no published parameter count, no technical report, and no published benchmark table at launch. It is reachable only through hosted APIs (Qwen Chat, Alibaba Cloud Model Studio / DashScope, fal.ai alibaba/qwen-image-3, third-party apps) in Standard and Pro editions — Pro positioned for production/API use, Standard for chat trial. The design goal is summed up as "Real"/useful: the model accepts prompts up to ~4,500 tokens (4.5× the previous generation), renders text legible down to ~10 pixels, supports 12 languages natively (incl. Japanese, Korean, Spanish), 20+ fonts, 100+ art styles, and full LaTeX rendering — built for information-dense, functional images: newspapers, complex infographics, exam sheets, storyboards, UI mockups, multi-panel comics. Prompting shifts from "describe a picture" to "write an executable visual specification." Qwen-Image-3.1: no evidence of a 3.1 release as of October 2026 — nothing below should be assumed to apply to a future 3.1.', '[{"url":"https://www.neura.market/news/alibaba-qwen-image-3-0-renders-infographics-tiny-text","note":"https://www.neura.market/news/alibaba-qwen-image-3-0-renders-infographics-tiny-text (4,500 tokens, 10px text, 12 languages, \"Real\" positioning, no open weights)"},{"url":"https://decrypt.co/374084/alibaba-qwen-image-3-ai-useful-not-just-pretty","note":"https://decrypt.co/374084/alibaba-qwen-image-3-ai-useful-not-just-pretty (launch coverage: rich content, authentic details, LaTeX, single-pass multi-panel demos)"},{"url":"https://tech-insider.org/how-to-use-qwen-image-3-0-2026/","note":"https://tech-insider.org/how-to-use-qwen-image-3-0-2026/ (no benchmarks/model card/weights at launch; 20+ fonts, 100+ art styles; Pro vs Standard)"},{"url":"https://www.orcarouter.ai/blog/qwen-image-2-1-vs-qwen-image-3-0","note":"https://www.orcarouter.ai/blog/qwen-image-2-1-vs-qwen-image-3-0 (timeline: 3.0 shipped 2026-07-21, GA 2026-08-05; 2.1 newer; licensing positions)"},{"url":"https://auraai.app/models/qwen-image-3","note":"https://auraai.app/models/qwen-image-3 (aspect ratios 16:9/9:16/1:1/4:3/3:4, example packaging/comic prompts)"},{"url":"https://miraflow.ai/blog/qwen-image-3-pro-prompts-infographics-text-layouts-2026","note":"https://miraflow.ai/blog/qwen-image-3-pro-prompts-infographics-text-layouts-2026 (Pro vs Standard positioning; 4,500-token budget practical notes)"},{"url":"https://github.com/bestimageai/awesome-qwen-image-3","note":"https://github.com/bestimageai/awesome-qwen-image-3 (180-prompt library; prompt-structure and multilingual-typography docs)"},{"url":"https://raw.githubusercontent.com/bestimageai/awesome-qwen-image-3/HEAD/docs/qwen-image-3-prompt-guide.md","note":"https://raw.githubusercontent.com/bestimageai/awesome-qwen-image-3/HEAD/docs/qwen-image-3-prompt-guide.md (four-layer structure, verbatim-text templates, panel specs, identity anchors, edit invariants, single-variable iteration)"},{"url":"https://github.com/yrn-dev/operator-alem-image-plus/blob/HEAD/skills/alem-image-plus/references/qwen-image-2512-guide.md","note":"https://github.com/yrn-dev/operator-alem-image-plus/blob/HEAD/skills/alem-image-plus/references/qwen-image-2512-guide.md (layout-spec approach for text-heavy graphics, \"same approximate person\" phrasing)"},{"url":"https://github.com/cozy-art/super-skills/blob/HEAD/skills/image/qwen-image-v2/SKILL.md","note":"https://github.com/cozy-art/super-skills/blob/HEAD/skills/image/qwen-image-v2/SKILL.md (prompt-length-by-use-case table, text workflow: PNG output, avoid high acceleration for text)"},{"url":"https://github.com/brndngln/nodetool/blob/HEAD/packages/system-skills/qwen-image-prompting/SKILL.md","note":"https://github.com/brndngln/nodetool/blob/HEAD/packages/system-skills/qwen-image-prompting/SKILL.md (prompt budget 5000 chars / negative 500 on API endpoints; \"no other text\" habit)"}]', '79c2a73a6df25d949121ad43bf13d73e');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('image/sdxl/0', 'image', 'sdxl', 'SDXL', 'SDXL', 'sdxl', 0, 'image', 'Prompt Guide: SDXL (Stable Diffusion XL)', 'models/image/sdxl.md', 4, 'Think in comma-separated descriptive phrases, front-loaded with the most important tokens — SDXL does not read long literary sentences the way newer T5/Qwen-encoder models do. Put quality tags and the main subject first, then refine with style, lighting, and camera tokens. Short, dense, ordered phrasing beats prose.', '[{"syntax":"Weighting (word:1.4)","supported":"yes","notes":"Frontend feature (A1111 / Forge / ComfyUI). Boosts a token''s cross-attention strength."},{"syntax":"Emphasis ((word))","supported":"yes","notes":"Each nesting ≈ ×1.1 in A1111-style frontends; ComfyUI parses nested parens the same way."},{"syntax":"BREAK keyword","supported":"yes","notes":"Supported natively by ComfyUI''s SDXL CLIP encoding and A1111. Forces the text before/after into separately encoded chunks — the standard fix for attribute bleed between subject and background."},{"syntax":"[from:to:step] blending","supported":"yes","notes":"A1111/Forge syntax for scheduling prompt swaps across steps; use the same-step blend variant [a:b:0.5] style only where the frontend supports it."},{"syntax":"Negative prompt","supported":"yes","notes":"Strongly supported and usually necessary — a curated quality/anatomy negative is standard practice for SDXL."},{"syntax":"Special / trigger tokens","supported":"yes","notes":"Textual-inversion and LoRA trigger words work, resolved per-encoder; diffusers also accepts a separate prompt_2/negative_prompt_2 targeted at the bigG encoder for style steering."},{"syntax":"Regional / masked prompting","supported":"yes","notes":"Via frontend tooling (A1111 \"latent couple\" / ComfyUI conditioning masks), not a prompt-string syntax."}]', '[{"length":"Too short","effect":"Under ~10 tokens → generic, under-specified results; the model falls back to its average aesthetic. Add subject detail, style, lighting."},{"length":"Ideal","effect":"~20–70 tokens of dense descriptive phrases plus a quality booster block. Front-load subject + style in the first ~30 tokens."},{"length":"Too long","effect":"Beyond 77 tokens per encoder the tail is silently dropped — key details vanish without warning. Split with BREAK or trim."}]', '[quality boosters] + [subject + key attributes] + [action/pose] + [environment/background] → + [medium/style] + [lighting] + [color/palette] + [camera/composition]', '[{"include":"Quality boosters (SDXL responds strongly to them)","examples":"masterpiece, best quality, 8k, highly detailed, sharp focus"},{"include":"Explicit medium/style tokens","examples":"photorealistic, oil painting, anime illustration, 3d render, film still"},{"include":"Lighting descriptors","examples":"golden hour, volumetric lighting, studio lighting, neon glow, soft shadows"},{"include":"Camera / lens language","examples":"85mm, wide angle, macro, shallow depth of field, bokeh"},{"include":"Spatial layout cues","examples":"in the foreground, in the background, left/right side, centered composition"},{"include":"Palette / mood tokens","examples":"muted colors, vibrant, cinematic color grading, monochrome"}]', '[{"instead":"Rambling prose sentences","write":"Dense comma-separated phrases"},{"instead":"One-word prompts like cat","write":"a fluffy orange tabby cat, green eyes, sitting on a windowsill, morning sunlight"},{"instead":"Putting blurry, low quality only in the positive as no blur","write":"Put blurry, low quality, deformed in the negative prompt"},{"instead":"Burying the subject after 60 tokens of style tags","write":"Subject within the first ~30 tokens"},{"instead":"Contradictory style tags (photorealistic oil painting watercolor)","write":"Pick one medium: photorealistic OR oil painting"},{"instead":"text, words, letters in the positive when you don''t want text","write":"text, watermark, signature in the negative prompt"}]', '[{"param":"Steps","value":"25–40 (30 is a solid baseline; 40–50 for maximum detail)"},{"param":"Guidance / CFG Scale","value":"5–8 (7 is the common default; lower ≈ more creative, higher ≈ more rigid)"},{"param":"Resolution","value":"1024×1024 native; official presets include 1152×896, 896×1152, 1216×832, 832×1216, 1344×768, 1536×640"},{"param":"Scheduler / Sampler","value":"DPMSolverMultistep, DPM++ 2M Karras, or Euler — all strong on SDXL"},{"param":"Dtype / Precision","value":"fp16"},{"param":"Refiner","value":"Optional: run refiner on the last ~20% (denoise start ≈ 0.8); base-only is standard for speed"}]', '[{"title":"Key detail past token 77","detail":"→ silently dropped by each encoder; trim or chunk with BREAK, and front-load the subject."},{"title":"No negative prompt","detail":"→ SDXL''s training data includes low-quality imagery; without a quality/anatomy negative, defects and watermarks appear far more often."},{"title":"Generating at 512×512 or odd resolutions","detail":"→ SDXL is trained at 1024px; small canvases produce distorted anatomy and mushy detail. Stay at/near 1024px per side."},{"title":"Writing \"no blur / no text\" in the positive prompt","detail":"→ negation in the positive is weak; those concepts belong in the negative prompt."},{"title":"Stacking contradictory mediums","detail":"(photorealistic oil painting watercolor 3d render) → pick one medium so the style tokens reinforce instead of canceling."}]', 'Target model: SDXL SDXL (image).
How to prompt it: Think in comma-separated descriptive phrases, front-loaded with the most important tokens — SDXL does not read long literary sentences the way newer T5/Qwen-encoder models do. Put quality tags and the main subject first, then refine with style, lighting, and camera tokens. Short, dense, ordered phrasing beats prose.
Prompt length — too short: Under ~10 tokens → generic, under-specified results; the model falls back to its average aesthetic. Add subject detail, style, lighting. | ideal: ~20–70 tokens of dense descriptive phrases plus a quality booster block. Front-load subject + style in the first ~30 tokens. | too long: Beyond 77 tokens per encoder the tail is silently dropped — key details vanish without warning. Split with BREAK or trim.
Syntax — supported: Weighting (word:1.4), Emphasis ((word)), BREAK keyword, [from:to:step] blending, Negative prompt, Special / trigger tokens, Regional / masked prompting
Negative prompt: YES — Strongly supported and usually necessary — a curated quality/anatomy negative is standard practice for SDXL.
Include: Quality boosters (SDXL responds strongly to them); Explicit medium/style tokens; Lighting descriptors; Camera / lens language; Spatial layout cues; Palette / mood tokens
Avoid: Rambling prose sentences; One-word prompts like cat; Putting blurry, low quality only in the positive as no blur; Burying the subject after 60 tokens of style tags; Contradictory style tags (photorealistic oil painting watercolor); text, words, letters in the positive when you don''t want text
Recommended settings: Steps 25–40 (30 is a solid baseline; 40–50 for maximum detail); Guidance / CFG Scale 5–8 (7 is the common default; lower ≈ more creative, higher ≈ more rigid); Resolution 1024×1024 native; official presets include 1152×896, 896×1152, 1216×832, 832×1216, 1344×768, 1536×640; Scheduler / Sampler DPMSolverMultistep, DPM++ 2M Karras, or Euler — all strong on SDXL; Dtype / Precision fp16; Refiner Optional: run refiner on the last ~20% (denoise start ≈ 0.8); base-only is standard for speed
Common mistakes: Key detail past token 77; No negative prompt; Generating at 512×512 or odd resolutions; Writing "no blur / no text" in the positive prompt; Stacking contradictory mediums', 'SDXL is a 3.5B-parameter latent diffusion model family (base UNet + dedicated refiner) built on two CLIP text encoders and trained natively at 1024px. It remains the reference open ecosystem for community checkpoints, LoRAs, and ControlNet workflows. Its CLIP encoders are tag-and-phrase biased: they respond best to comma-separated descriptive phrases and explicit quality boosters, and each encoder''s context truncates hard at 77 tokens. The base model handles composition while the optional refiner adds final detail; most production workflows run base only and skip the refiner for speed.', '[{"url":"https://huggingface.co/docs/diffusers/en/using-diffusers/sdxl","note":"https://huggingface.co/docs/diffusers/en/using-diffusers/sdxl (dual text encoders, prompt_2 per-encoder prompts, textual inversion, 1024×1024 native)"},{"url":"https://huggingface.co/docs/diffusers/v0.22.0/using-diffusers/sdxl","note":"https://huggingface.co/docs/diffusers/v0.22.0/using-diffusers/sdxl"},{"url":"https://github.com/aiforhumans/comfyui-xdev-nodes/blob/HEAD/docs/docs/sdxl.md","note":"https://github.com/aiforhumans/comfyui-xdev-nodes/blob/HEAD/docs/docs/sdxl.md (aspect presets, steps 25–50, refiner guidance)"},{"url":"https://github.com/mohamedabdallah-14/prompt-to-asset/blob/HEAD/docs/research/06-stable-diffusion-flux/6a-sd-15-21-xl-prompting-fundamentals.md","note":"https://github.com/mohamedabdallah-14/prompt-to-asset/blob/HEAD/docs/research/06-stable-diffusion-flux/6a-sd-15-21-xl-prompting-fundamentals.md (BREAK token-bleed mechanics on SDXL)"},{"url":"https://whatshuang.com/posts/stable-diffusion-prompts","note":"https://whatshuang.com/posts/stable-diffusion-prompts (universal SDXL negative prompt; bad-vs-good example pairs)"},{"url":"https://promptomania.com/models/stable-diffusion/sdxl-1-0","note":"https://promptomania.com/models/stable-diffusion/sdxl-1-0 (CFG 5–9, steps 20–50, weighting syntax, example prompts)"},{"url":"https://github.com/dwin-gharibi/runpod-sdxl","note":"https://github.com/dwin-gharibi/runpod-sdxl (30 steps / guidance 7.0 baseline; refiner denoise 0.7–0.85)"}]', 'eb951983b8cb2e8b4650218bce24314b');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('image/z-image/0', 'image', 'z-image', 'Z-Image', 'Z-Image', 'z-image', 0, 'image', 'Prompt Guide: Z-Image', 'models/image/z-image.md', 4, 'Write natural-language descriptive prompts, phrased positively — the Qwen-based encoder understands sentences, not tag soup, and responds best to concrete visual descriptions. If you want text rendered in the image, quote it exactly. Keep prompts descriptive rather than keyword-stuffed; the official Prompt Enhancer exists precisely to expand thin prompts for you.', '[{"syntax":"Weighting (word:1.4)","supported":"no","notes":"CLIP-era syntax; no evidence of support in Z-Image''s Qwen3-encoder pipeline. Emphasize by describing, not by weighting."},{"syntax":"Emphasis ((word))","supported":"no","notes":"Same as above — use richer description instead."},{"syntax":"BREAK keyword","supported":"no","notes":"BREAK is CLIP-tooling-specific chunking; the S3-DiT encoder takes one unified token stream."},{"syntax":"[from:to:step] blending","supported":"no","notes":"No evidence in official docs or diffusers ZImagePipeline."},{"syntax":"Negative prompt","supported":"yes","notes":"Official README: \"Negative prompts: Strongly recommended for better control\" for the base model. Turbo runs with guidance_scale=0.0 and CFG removed, so a negative prompt does nothing there."},{"syntax":"Special / trigger tokens","supported":"unknown","notes":"No textual-inversion / trigger-token documentation found in official sources."},{"syntax":"Regional / masked prompting","supported":"unknown","notes":"No official masked/regional prompting documentation found."}]', '[{"length":"Too short","effect":"A few vague words (\"a cat\") → the model fills in average-looking content; quality and specificity suffer. Use the official Prompt Enhancer or expand manually."},{"length":"Ideal","effect":"A descriptive paragraph (~50–200 words) covering subject, action, setting, style/medium, and lighting; quote any in-image text exactly."},{"length":"Too long","effect":"Beyond the sequence limit (~512 tokens in the demo, 1024 locally) the tail is truncated — long dumps of adjectives at the end silently vanish."}]', '[Subject + key attributes] + [action / pose] + [setting / background] → + [in-image text in "quotes" if any] + [medium / visual style] + [lighting + atmosphere]', '[{"include":"Concrete subject details","examples":"Age, clothing, textures, materials, colors (wrinkled skin, rough hands, intricate embroidery)"},{"include":"Explicit in-image text in quotes","examples":"a sign reading \"GARDEN OF LIFE\", the cover headline \"SUMMER SALE\" — English or Chinese"},{"include":"Medium / photographic grounding","examples":"shot on Leica M6, Kodak Portra 400, cinematic composition, natural light photography"},{"include":"Lighting and atmosphere","examples":"dappled sunlight, soft backlighting, neon glow, warm morning atmosphere"},{"include":"Composition cues","examples":"close-up, wide shot, shallow depth of field, rule of thirds"},{"include":"Positive quality phrasing (preferred over negative lists)","examples":"sharp focus, highly detailed, clean composition"}]', '[{"instead":"Tag-soup / keyword salad (girl, neon, 8k, cinematic, ((beautiful)))","write":"Full natural-language sentences describing the scene"},{"instead":"CLIP weighting syntax (word:1.4), ((word)), BREAK","write":"Plain descriptive emphasis — the encoder doesn''t parse these"},{"instead":"Loading the negative with blurry, bad quality, typo","write":"State quality positively: sharp focus, highly detailed, perfect text"},{"instead":"Vague single-word prompts (cat, poster)","write":"A descriptive sentence, or use the Prompt Enhancer to expand"},{"instead":"Writing text-to-render without quotes (GARDEN OF LIFE sign)","write":"Quote the exact string: a sign reading \"GARDEN OF LIFE\""},{"instead":"Very long adjective dumps that exceed the token limit","write":"Keep the descriptive core under ~512 tokens; front-load the subject"}]', '[{"param":"Steps","value":"Base: 28–50 (official); Turbo: 8 NFEs (9 num_inference_steps in diffusers = 8 DiT forwards)"},{"param":"Guidance / CFG Scale","value":"Base: 3.0–5.0; Turbo: 0.0 (CFG removed entirely)"},{"param":"Resolution","value":"512×512 to 2048×2048 total pixel area, any aspect ratio"},{"param":"Scheduler / Sampler","value":"diffusers ZImagePipeline defaults"},{"param":"Dtype / Precision","value":"bfloat16 recommended"},{"param":"CFG normalization","value":"False for general/stylized output, True for realism (base only, per official README)"}]', '[{"title":"Porting SDXL syntax","detail":"((word:1.4), ((word)), BREAK) → the encoder ignores or mangles these; write natural language instead."},{"title":"Using a negative prompt on Turbo","detail":"→ Turbo''s CFG is removed (guidance_scale=0.0), so negatives have no effect; phrase exclusions positively."},{"title":"Not quoting in-image text","detail":"→ text renders garbled unless the exact string is in double quotes with style/placement context."},{"title":"Prompts that exceed the token limit","detail":"→ the demo truncates around 512 tokens (1024 locally); trailing detail is silently dropped, so front-load."},{"title":"Carrying over CFG/steps from other models","detail":"→ the single most common misconfiguration per community guides: base wants guidance 3–5 and 28–50 steps, Turbo wants 8 steps and zero guidance."}]', 'Target model: Z-Image Z-Image (image).
How to prompt it: Write natural-language descriptive prompts, phrased positively — the Qwen-based encoder understands sentences, not tag soup, and responds best to concrete visual descriptions. If you want text rendered in the image, quote it exactly. Keep prompts descriptive rather than keyword-stuffed; the official Prompt Enhancer exists precisely to expand thin prompts for you.
Prompt length — too short: A few vague words ("a cat") → the model fills in average-looking content; quality and specificity suffer. Use the official Prompt Enhancer or expand manually. | ideal: A descriptive paragraph (~50–200 words) covering subject, action, setting, style/medium, and lighting; quote any in-image text exactly. | too long: Beyond the sequence limit (~512 tokens in the demo, 1024 locally) the tail is truncated — long dumps of adjectives at the end silently vanish.
Syntax — supported: Negative prompt | NOT supported: Weighting (word:1.4), Emphasis ((word)), BREAK keyword, [from:to:step] blending
Negative prompt: YES — Official README: "Negative prompts: Strongly recommended for better control" for the base model. Turbo runs with guidance_scale=0.0 and CFG removed, so a negative prompt does nothing there.
Include: Concrete subject details; Explicit in-image text in quotes; Medium / photographic grounding; Lighting and atmosphere; Composition cues; Positive quality phrasing (preferred over negative lists)
Avoid: Tag-soup / keyword salad (girl, neon, 8k, cinematic, ((beautiful))); CLIP weighting syntax (word:1.4), ((word)), BREAK; Loading the negative with blurry, bad quality, typo; Vague single-word prompts (cat, poster); Writing text-to-render without quotes (GARDEN OF LIFE sign); Very long adjective dumps that exceed the token limit
Recommended settings: Steps Base: 28–50 (official); Turbo: 8 NFEs (9 num_inference_steps in diffusers = 8 DiT forwards); Guidance / CFG Scale Base: 3.0–5.0; Turbo: 0.0 (CFG removed entirely); Resolution 512×512 to 2048×2048 total pixel area, any aspect ratio; Scheduler / Sampler diffusers ZImagePipeline defaults; Dtype / Precision bfloat16 recommended; CFG normalization False for general/stylized output, True for realism (base only, per official README)
Common mistakes: Porting SDXL syntax; Using a negative prompt on Turbo; Not quoting in-image text; Prompts that exceed the token limit; Carrying over CFG/steps from other models', 'Z-Image is a 6-billion-parameter text-to-image family built on a Scalable Single-Stream DiT (S3-DiT) architecture, where text tokens, visual semantic tokens, and VAE tokens are concatenated into one unified sequence. It is released under Apache-2.0. The base Z-Image checkpoint (released 2026-01-27) prioritizes high-quality generation, rich aesthetics, diversity, and controllability with real classifier-free guidance and 28–50 steps; the distilled Z-Image-Turbo (released 2025-11-26) generates in 8 function evaluations with guidance removed. Standout strengths are photorealism, bilingual (English + Chinese) text rendering, and an official Prompt Enhancer that expands short prompts with reasoning. The base model explicitly supports effective negative prompting, while Turbo''s CFG-free design makes negatives meaningless there.', '[{"url":"https://github.com/Tongyi-MAI/Z-Image","note":"https://github.com/Tongyi-MAI/Z-Image (official repo: model zoo, base/Turbo recommended parameters, inference examples, Prompt Enhancer, bilingual text rendering)"},{"url":"https://hackmd.io/@PixSprout/SkYdKrvNZe","note":"https://hackmd.io/@PixSprout/SkYdKrvNZe (Z-Image Prompt Engineering Guide: 4-layer structure, positive phrasing, quoting text)"},{"url":"https://github.com/maciejdzierzek/z-image-prompt-generator","note":"https://github.com/maciejdzierzek/z-image-prompt-generator (token budget 512/1024, Turbo low-diversity notes, verified against Tongyi-MAI sources)"},{"url":"https://github.com/ZizheRuan/awesome-Alibaba-Z-Image","note":"https://github.com/ZizheRuan/awesome-Alibaba-Z-Image (community prompt gallery; family variants)"},{"url":"https://vast.ai/model/z-image-turbo","note":"https://vast.ai/model/z-image-turbo (architecture, Qwen3 4B encoder, 6B parameters, 8 function evaluations)"},{"url":"https://lovegen.ai/z-image-turbo","note":"https://lovegen.ai/z-image-turbo (release date, license, prompt-length/aspect-ratio specs)"}]', '1df4381c2c947df9c1fcfd24268ff587');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('video/kling/0', 'video', 'kling', 'Kling', '2.x', '2.x', 0, 'video', 'Prompt Guide: Kling 2.x', 'models/video/kling-2.x.md', 6, 'Write cinematic direction in flowing prose, not keyword soup: a complete shot description with a specific subject, one clean action, scene, camera, lighting, and atmosphere. Kling 1.x–2.x dislikes fragmented tag-style inputs and punishes overlong prompts with melted outputs.', '[{"syntax":"Weighting (word:1.4)","supported":"unknown","notes":"No documented support in official materials or API schemas"},{"syntax":"Emphasis ((word))","supported":"unknown","notes":"Community prompting skills report a ++emphasis++ convention (max 2), but this is not officially verified"},{"syntax":"BREAK keyword","supported":"unknown","notes":""},{"syntax":"[from:to:step] blending","supported":"unknown","notes":""},{"syntax":"Negative prompt","supported":"yes","notes":"Dedicated negative_prompt field (API default: \"blur, distort, and low quality\"). Critical rule: the field auto-interprets input as exclusion — write the thing itself, never \"no X\" (write robots, not no robots). Keep the list short; long negative stacks reduce motion and detail."},{"syntax":"Special / trigger tokens","supported":"unknown","notes":""},{"syntax":"Regional / masked prompting","supported":"partial","notes":"Platform-side Motion Brush tool exists; not a prompt-syntax feature"}]', '[{"length":"Too short","effect":"Vague prompts (\"make it cool\") produce generic results; short prompts miss the subject/scene specificity 2.x needs"},{"length":"Ideal","effect":"Text-to-video: 50–80 words (2.5 Turbo: 3–4 elements max; 2.6 Pro: 5–7 elements). Image-to-video: 20–40 words, motion-focused. Community references put the API prompt ceiling around ~2500 characters."},{"length":"Too long","effect":"On 1.x–2.x, long prompts = melted outputs. Compress ruthlessly; one continuous take can only hold so much. (Longer, structured prompts become viable in 3.0.)"}]', '[Subject (with specific details)] + [Subject Movement (one clean verb phrase)] → + [Scene (3–5 elements max)] + [Camera Language] + [Lighting] + [Atmosphere]', '[{"include":"Specific subject details","examples":"Age, ethnicity, clothing, distinguishing features"},{"include":"One clean action verb phrase","examples":"\"slowly turns toward the window\", \"first… then… finally…\""},{"include":"Limited scene elements (3–5)","examples":"Street, weather, key props — not a laundry list"},{"include":"Camera language with motivation","examples":"\"tracking shot, dolly zoom, slow push-in, gentle pan right, handheld\""},{"include":"Lens/framing terms","examples":"\"35mm, 50mm, shallow depth of field, wide shot, medium shot, close-up\""},{"include":"Lighting specifics","examples":"\"warm kitchen light, cool palette, golden hour, neon glow\""},{"include":"Atmosphere words","examples":"\"melancholic, triumphant, eerie, hopeful, quiet ambience\""},{"include":"On 2.6: audio cues","examples":"Quoted dialogue, \"ambient city noise\", music mood; lowercase English speech, uppercase acronyms/proper nouns"},{"include":"First/last frame intent","examples":"\"Take the start frame, camera slowly zooms out revealing…\""}]', '[{"instead":"Tag soup: \"cinematic, woman, neon, 4k, masterpiece\"","write":"Flowing prose with subject + action + scene + camera + lighting"},{"instead":"Vague asks: \"make it cool\"","write":"Concrete subject, action, and camera direction"},{"instead":"Negative field: \"no robots, no blurry faces\"","write":"robots, blurry faces, distorted hands, melted features (the field already excludes)"},{"instead":"Multiple locations/scene changes in one prompt","write":"One continuous take per generation; split scenes into separate clips"},{"instead":"Overlong prompts stuffed with elements","write":"3–7 elements max; compress ruthlessly"},{"instead":"Open-ended/looping motion","write":"A defined action with a start and an end"},{"instead":"Relying on native audio on 2.0/2.1/2.5","write":"No audio generation exists before 2.6 — add sound in post"},{"instead":"Describing the input image in i2v","write":"Motion only — the frame already exists"}]', '[{"param":"Steps","value":"(leave blank — cloud API; not exposed/documented)"},{"param":"Guidance / CFG Scale","value":"cfg_scale 0–1, default 0.5; 0.3–0.4 = more creative freedom, 0.7–1.0 = strict prompt adherence (product/explainer work)"},{"param":"Resolution","value":"1080p (Master/Pro tiers); 720p base with AI upscaling to 1080p/4K in pro modes per third-party reports"},{"param":"Scheduler / Sampler","value":"(leave blank — not exposed)"},{"param":"Dtype / Precision","value":"(leave blank — not exposed)"}]', '[{"title":"Tag soup instead of prose","detail":"→ Kling 1.x–2.x dislikes fragmented keyword inputs; write flowing shot descriptions."},{"title":"\"no X\" in the negative prompt","detail":"→ the field already excludes; write the thing itself."},{"title":"Multiple scene changes in one prompt","detail":"→ 2.x generates one continuous take; split scenes into separate clips."},{"title":"Overlong prompts","detail":"→ melted outputs on 2.x; stay in the 50–80 word t2v band, 20–40 for i2v."},{"title":"Re-describing the image in i2v","detail":"→ describe motion only."},{"title":"Expecting audio on 2.0/2.1/2.5","detail":"→ native audio starts at 2.6; add sound in post for earlier versions."},{"title":"Long negative stacks","detail":"→ they reduce motion and detail; keep negatives short."}]', 'Target model: Kling 2.x (video).
How to prompt it: Write cinematic direction in flowing prose, not keyword soup: a complete shot description with a specific subject, one clean action, scene, camera, lighting, and atmosphere. Kling 1.x–2.x dislikes fragmented tag-style inputs and punishes overlong prompts with melted outputs.
Prompt length — too short: Vague prompts ("make it cool") produce generic results; short prompts miss the subject/scene specificity 2.x needs | ideal: Text-to-video: 50–80 words (2.5 Turbo: 3–4 elements max; 2.6 Pro: 5–7 elements). Image-to-video: 20–40 words, motion-focused. Community references put the API prompt ceiling around ~2500 characters. | too long: On 1.x–2.x, long prompts = melted outputs. Compress ruthlessly; one continuous take can only hold so much. (Longer, structured prompts become viable in 3.0.)
Syntax — supported: Negative prompt | partial: Regional / masked prompting
Negative prompt: YES — Dedicated negative_prompt field (API default: "blur, distort, and low quality"). Critical rule: the field auto-interprets input as exclusion — write the thing itself, never "no X" (write robots, not no robots). Keep the list short; long negative stacks reduce motion and detail.
Include: Specific subject details; One clean action verb phrase; Limited scene elements (3–5); Camera language with motivation; Lens/framing terms; Lighting specifics
Avoid: Tag soup: "cinematic, woman, neon, 4k, masterpiece"; Vague asks: "make it cool"; Negative field: "no robots, no blurry faces"; Multiple locations/scene changes in one prompt; Overlong prompts stuffed with elements; Open-ended/looping motion
Recommended settings: Steps (leave blank — cloud API; not exposed/documented); Guidance / CFG Scale cfg_scale 0–1, default 0.5; 0.3–0.4 = more creative freedom, 0.7–1.0 = strict prompt adherence (product/explainer work); Resolution 1080p (Master/Pro tiers); 720p base with AI upscaling to 1080p/4K in pro modes per third-party reports; Scheduler / Sampler (leave blank — not exposed); Dtype / Precision (leave blank — not exposed)
Common mistakes: Tag soup instead of prose; "no X" in the negative prompt; Multiple scene changes in one prompt; Overlong prompts; Re-describing the image in i2v', 'Kling 2.x is Kuaishou''s closed, cloud-based video generation family between Kling 1.x (2024) and the Kling 3.0 series (Feb 2026). Verified releases: Kling 2.0 (April 15, 2025 — major motion/realism jump; Master tier), Kling 2.1 (May 29, 2025 — three quality tiers: Standard/Pro/Master; cost-efficient quality at Pro), Kling 2.5 Turbo (September 23, 2025 — fastest inference, ~30% lower cost than 2.1 Pro, aimed at simple scenes and rapid drafts), and Kling 2.6 Pro (December 3, 2025 — native audio generation in English and Chinese, smoother motion, 1080p at 48 fps). All 2.x models top out at 10-second clips (5 or 10 s) at up to 1080p, with no native audio before 2.6 and no multi-shot in a single generation (that arrives in 3.0) — every prompt describes one continuous take. The platform offers a DeepSeek prompt enhancer, Motion Brush, first-and-last-frame control, and an Elements/reference feature for visual consistency. Per-version prompting differences Version Prompting differences 2.0 Baseline formula (Subject + Movement + Scene + Camera + Lighting + Atmosphere). Master tier = premium prompt precision. No native audio — no audio cues needed in prompt. 2.1 Same formula; Master tier offers the highest prompt precision of the 2.x line. Three tiers (Standard/Pro/Master) — keep prompts within the model''s single-take, 5/10 s scope. 2.5 Turbo Optimized for fast drafts of simple scenes: 3–4 elements max, 50–80 words, short prompts. No audio. Over-detailed prompts waste its speed advantage. 2.6 Pro 5–7 elements, 50–80 words. Native audio is on — include audio cues in the prompt: ambient sounds, music mood, and dialogue in quotation marks (English/Chinese voice output; other languages auto-translated to English; use lowercase for English speech, uppercase for acronyms/proper nouns).', '[{"url":"https://aiwiki.ai/wiki/kling_2_1","note":"https://aiwiki.ai/wiki/kling_2_1 (2.x release table: 2.0/2.1/2.5 Turbo/2.6 dates, tiers, audio)"},{"url":"https://fal.ai/models/fal-ai/kling-video/v2.1/master/text-to-video/api","note":"https://fal.ai/models/fal-ai/kling-video/v2.1/master/text-to-video/api (2.1 Master t2v schema: negative_prompt, cfg_scale)"},{"url":"https://fal.ai/models/fal-ai/kling-video/v2.1/master/image-to-video/api","note":"https://fal.ai/models/fal-ai/kling-video/v2.1/master/image-to-video/api (2.1 Master i2v schema and motion-focused example prompt)"},{"url":"https://fal.ai/models/fal-ai/kling-video/v2.1/standard/image-to-video/api","note":"https://fal.ai/models/fal-ai/kling-video/v2.1/standard/image-to-video/api (2.1 Standard i2v schema)"},{"url":"https://fal.ai/models/fal-ai/kling-video/v2.5-turbo/standard/image-to-video/api","note":"https://fal.ai/models/fal-ai/kling-video/v2.5-turbo/standard/image-to-video/api (2.5 Turbo i2v schema and motion-focused example prompt)"},{"url":"https://fal.ai/learn/devs/kling-2-6-pro-vs-kling-2-5-turbo-pro","note":"https://fal.ai/learn/devs/kling-2-6-pro-vs-kling-2-5-turbo-pro (2.6 vs 2.5 Turbo: native audio, Elements, speed)"},{"url":"https://github.com/smixs/visual-skills/blob/HEAD/video/references/kling.md","note":"https://github.com/smixs/visual-skills/blob/HEAD/video/references/kling.md (prompt formula 1.x–2.x, per-model length bands, negative-prompt rules, 2.x vs 3.0 differences)"},{"url":"https://github.com/chirag6653/visual-skills/blob/HEAD/video/references/kling.md","note":"https://github.com/chirag6653/visual-skills/blob/HEAD/video/references/kling.md (same reference, corroborating length bands and formulas)"},{"url":"https://github.com/falling-ts/comfy/blob/HEAD/.agents/skills/comfyui/MODELS/video-api.md","note":"https://github.com/falling-ts/comfy/blob/HEAD/.agents/skills/comfyui/MODELS/video-api.md (2.x five-part style, emphasis convention, prompt ~2500 chars)"},{"url":"https://gaga.art/blog/kling-ai/","note":"https://gaga.art/blog/kling-ai/ (official-style prompt structures for t2v and i2v, start/end frame workflows)"},{"url":"https://www.cometapi.com/kling-2-1-vs-veo-3/","note":"https://www.cometapi.com/kling-2-1-vs-veo-3/ (2.1 tiers, durations, reference/multi-image features)"},{"url":"https://github.com/brndngln/nodetool/blob/HEAD/packages/system-skills/kling-video-prompting/SKILL.md","note":"https://github.com/brndngln/nodetool/blob/HEAD/packages/system-skills/kling-video-prompting/SKILL.md (per-version feature table incl. cfg_scale/negative-prompt support)"},{"url":"https://github.com/santiagoromero27/creative-workflow/blob/HEAD/.claude/skills/kling-ai/SKILL.md","note":"https://github.com/santiagoromero27/creative-workflow/blob/HEAD/.claude/skills/kling-ai/SKILL.md (2.x i2v/t2v workflows, Turbo prototyping pattern)"}]', '004f02e6e6a6a8a0caadecc922da6d52');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('video/kling/1', 'video', 'kling', 'Kling', '3.0', '3.0', 1, 'video', 'Prompt Guide: Kling 3.0', 'models/video/kling-3.0.md', 5, 'Write shots, not paragraphs: a 3.0 prompt is a structured multi-shot plan with labeled characters, explicit per-shot framing/action/camera, and named edits — a single dense paragraph throws away multi-shot, audio, and character-tagging and comes back as one drifting take.', '[{"syntax":"Weighting (word:1.4)","supported":"unknown","notes":"No documented support"},{"syntax":"Emphasis ((word))","supported":"unknown","notes":"No documented support"},{"syntax":"BREAK keyword","supported":"unknown","notes":""},{"syntax":"[from:to:step] blending","supported":"unknown","notes":""},{"syntax":"Negative prompt","supported":"yes","notes":"negative_prompt field supported on v3 (API default \"blur, distort, and low quality\"). Same rule as 2.x: write the thing itself, never \"no X\"."},{"syntax":"Special / trigger tokens","supported":"yes","notes":"Element tags: reference uploaded elements in the prompt as @Element1, @Element2, etc. Character labels like [Character A: …] are a documented community convention for locking identity across shots."},{"syntax":"Regional / masked prompting","supported":"partial","notes":"Motion Control variant transfers motion from a reference clip; Omni supports video element reference and video editing. Not prompt-syntax features."}]', '[{"length":"Too short","effect":"Under-structured prompts collapse multi-shot into one drifting take; empty shot descriptions (\"static frame, ambient mood\") do the same"},{"length":"Ideal","effect":"100–200 words total; plan ~30–60 words per shot. Longer prompts are welcome on 3.0 — structure beats length."},{"length":"Too long","effect":"Unstructured walls of text still underperform; the answer is explicit shot structure, not more adjectives"}]', '[Character/Element labels] → [Master intent] → [Shot 1 (timing). Framing. Subject + action. Camera.] → → [Shot 2 …] → [Camera] → [Lighting] → [Audio]', '[{"include":"Labeled characters/elements anchored early","examples":"[Character A: …], @Element1 walks into the coffee shop…"},{"include":"Explicit per-shot timing","examples":"Shot 1 (0-3s)., durations summing to ≤ 15 s"},{"include":"Named edits between shots","examples":"\"shot-reverse-shot, match cut, smash cut, J-cut, L-cut\""},{"include":"Full cinematic vocabulary","examples":"See structure table — used as instructions, not flavor"},{"include":"Audio design","examples":"Quoted dialogue, ambient beds, explicit \"No music\" when scoring later"},{"include":"Consistency instructions","examples":"\"Keep wardrobe and weather consistent.\""},{"include":"Identity-locking across shots","examples":"Same label reused verbatim; reference images via Elements"},{"include":"Native-audio language cues","examples":"EN/ZH/JA/KO/ES supported; lowercase English speech, uppercase acronyms/proper nouns"}]', '[{"instead":"One dense paragraph for a multi-shot scene","write":"Labeled shot blocks with timing, framing, subject, motion"},{"instead":"Empty shot descriptions (\"static frame, ambient mood\")","write":"Every shot answers: framing + subject + motion"},{"instead":"Pronouns/synonyms for characters across shots","write":"The same [Character A] / @Element1 label every time"},{"instead":"Combining every control by default (elements + refs + multi-shot + audio)","write":"The smallest set of controls that fixes the problem; more references can conflict"},{"instead":"Relying on post-hoc stitching for audio","write":"Generate dialogue scenes in one multi-shot call — separately generated clips drop sound at each join"},{"instead":"Open-ended looping motion","write":"Defined actions with starts and ends"},{"instead":"\"no X\" in the negative prompt","write":"The thing itself: robots, blurry faces"}]', '[{"param":"Steps","value":"(leave blank — cloud API; not exposed)"},{"param":"Guidance / CFG Scale","value":"cfg_scale 0–1, default 0.5; 0.3–0.4 = creative freedom, 0.7–1.0 = strict adherence"},{"param":"Resolution","value":"Up to 1080p base; 4K tier available (separate native-4K release, April 2026). Turbo: 720p–1080p, no 4K"},{"param":"Scheduler / Sampler","value":"(leave blank — not exposed)"},{"param":"Dtype / Precision","value":"(leave blank — not exposed)"}]', '[{"title":"Single dense paragraph for multi-shot","detail":"→ one drifting take; use labeled shot blocks."},{"title":"Empty shot descriptions","detail":"→ every shot must answer framing + subject + motion."},{"title":"Pronouns/synonyms across shots","detail":"→ reuse the exact [Character A] / @ElementN label."},{"title":"Stacking every control at once","detail":"→ smallest effective control set; extra references can conflict."},{"title":"Stitching separately generated clips for dialogue","detail":"→ sound drops at each join; generate multi-shot dialogue in one call."},{"title":"\"no X\" in the negative prompt","detail":"→ write the thing itself."},{"title":"Expecting 4K or audio from Turbo","detail":"→ Turbo is 720p–1080p with no 4K tier; choose the variant for the job (Turbo = drafts, 3.0/Omni = delivery)."}]', 'Target model: Kling 3.0 (video).
How to prompt it: Write shots, not paragraphs: a 3.0 prompt is a structured multi-shot plan with labeled characters, explicit per-shot framing/action/camera, and named edits — a single dense paragraph throws away multi-shot, audio, and character-tagging and comes back as one drifting take.
Prompt length — too short: Under-structured prompts collapse multi-shot into one drifting take; empty shot descriptions ("static frame, ambient mood") do the same | ideal: 100–200 words total; plan ~30–60 words per shot. Longer prompts are welcome on 3.0 — structure beats length. | too long: Unstructured walls of text still underperform; the answer is explicit shot structure, not more adjectives
Syntax — supported: Negative prompt, Special / trigger tokens | partial: Regional / masked prompting
Negative prompt: YES — negative_prompt field supported on v3 (API default "blur, distort, and low quality"). Same rule as 2.x: write the thing itself, never "no X".
Include: Labeled characters/elements anchored early; Explicit per-shot timing; Named edits between shots; Full cinematic vocabulary; Audio design; Consistency instructions
Avoid: One dense paragraph for a multi-shot scene; Empty shot descriptions ("static frame, ambient mood"); Pronouns/synonyms for characters across shots; Combining every control by default (elements + refs + multi-shot + audio); Relying on post-hoc stitching for audio; Open-ended looping motion
Recommended settings: Steps (leave blank — cloud API; not exposed); Guidance / CFG Scale cfg_scale 0–1, default 0.5; 0.3–0.4 = creative freedom, 0.7–1.0 = strict adherence; Resolution Up to 1080p base; 4K tier available (separate native-4K release, April 2026). Turbo: 720p–1080p, no 4K; Scheduler / Sampler (leave blank — not exposed); Dtype / Precision (leave blank — not exposed)
Common mistakes: Single dense paragraph for multi-shot; Empty shot descriptions; Pronouns/synonyms across shots; Stacking every control at once; Stitching separately generated clips for dialogue', 'Kling 3.0 is the February 2026 flagship series (community release trackers cite Jan 31–Feb 5, 2026), succeeding the 2.x line on Kuaishou''s Multi-modal Visual Language (MVL) framework — a shift from basic video generation toward professional shot orchestration. Verified existence is confirmed by multiple independent sources; note "Kling 3.0" is a series, not one model: VIDEO 3.0 (base: cinematic storytelling, multi-shot, native audio), VIDEO 3.0 Turbo (faster/cheaper per second, strongest lip sync, no 4K), VIDEO 3.0 Omni (adds video element reference, element voice control, and video editing), VIDEO 3.0 Motion Control (motion transfer with high facial consistency, up to 30 s), and Avatar 2.0 (talking avatars from 1 image + 1 audio, up to 5 min). Headline changes vs 2.x: multi-shot generation (up to 6 shots) in a single call, native audio with lip sync on by default, 3–15 s durations, up to 4K output (native 4K as a separate April 2026 release), tagged character elements (@Element1), and full cinematic-language understanding ("shot-reverse-shot", "POV", "macro close-up" are read as instructions).', '[{"url":"https://github.com/mandjouh/kling-ai-prompt-generator","note":"https://github.com/mandjouh/kling-ai-prompt-generator (3.0 series model table: variants, prompt lengths, release dates)"},{"url":"https://github.com/watreesir/awesome-kling-4","note":"https://github.com/watreesir/awesome-kling-4 (Kling release timeline 1.0→3.0, 3.0 feature summary)"},{"url":"https://github.com/brndngln/nodetool/blob/HEAD/packages/system-skills/kling-video-prompting/SKILL.md","note":"https://github.com/brndngln/nodetool/blob/HEAD/packages/system-skills/kling-video-prompting/SKILL.md (per-version feature table: shot lists, tagged elements, native audio, cfg_scale/negative support; \"write shots, not paragraphs\")"},{"url":"https://github.com/smixs/visual-skills/blob/HEAD/video/references/kling.md","note":"https://github.com/smixs/visual-skills/blob/HEAD/video/references/kling.md (2.x vs 3.0 capability table, five-layer structure, multi-shot syntax, character labels)"},{"url":"https://github.com/dseastar/awesome-kling/blob/HEAD/README-en.md","note":"https://github.com/dseastar/awesome-kling/blob/HEAD/README-en.md (3.0 prompt formula, multi-shot template, i2v template)"},{"url":"https://github.com/flaqai/awesome-kling-4-0/blob/HEAD/docs/PROMPT-GUIDE.md","note":"https://github.com/flaqai/awesome-kling-4-0/blob/HEAD/docs/PROMPT-GUIDE.md (seven-layer prompt, input-mode selection)"},{"url":"https://github.com/santiagoromero27/creative-workflow/blob/HEAD/.claude/skills/kling-ai/SKILL.md","note":"https://github.com/santiagoromero27/creative-workflow/blob/HEAD/.claude/skills/kling-ai/SKILL.md (3.0 i2v/t2v workflows, Turbo prototyping pattern)"},{"url":"https://github.com/neurodropp/prompt-resources/blob/HEAD/prompt_docs/kling-ai/kling-ai-kling-video-30-omni-readme.md","note":"https://github.com/neurodropp/prompt-resources/blob/HEAD/prompt_docs/kling-ai/kling-ai-kling-video-30-omni-readme.md (Omni: element references, @-style tags, video editing)"},{"url":"https://fal.ai/models/fal-ai/kling-video/v3/4k/image-to-video/api","note":"https://fal.ai/models/fal-ai/kling-video/v3/4k/image-to-video/api (v3 i2v schema: negative_prompt, cfg_scale, elements, end frames, multi_prompt)"},{"url":"https://lifestyle.pluralist.com/story/769365/kling-ai-launches-3-0-model-ushering-in-an-era-where-everyone-can-be-a-director-5/","note":"https://lifestyle.pluralist.com/story/769365/kling-ai-launches-3-0-model-ushering-in-an-era-where-everyone-can-be-a-director-5/ (3.0 launch: MVL framework, Omni storyboarding, multi-shot)"},{"url":"https://www.versely.studio/blog/kling-v3-standard-i2v-is-63-credits","note":"https://www.versely.studio/blog/kling-v3-standard-i2v-is-63-credits (3.0 variant/credit catalog: Turbo silent, Standard/O3 audio rows)"}]', 'be8e8d8c8a63dab828f626259b33778c');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('video/ltx/0', 'video', 'ltx', 'LTX-Video', '2.3', '2.3', 0, 'video', 'Prompt Guide: LTX-2.3', 'models/video/ltx-2.3.md', 5, 'Write one flowing, present-tense paragraph that describes the action chronologically, like a cinematographer dictating a shot list — never comma-separated tag soup or a shot list with sluglines.', '[{"syntax":"Weighting (word:1.4)","supported":"unknown","notes":"No documented support in official prompting guidance"},{"syntax":"Emphasis ((word))","supported":"unknown","notes":"No documented support"},{"syntax":"BREAK keyword","supported":"unknown","notes":""},{"syntax":"[from:to:step] blending","supported":"unknown","notes":""},{"syntax":"Negative prompt","supported":"yes","notes":"Pipeline recipes supply a default negative prompt; ComfyUI integrations expose it (e.g. \"still image, no movements\" for i2v stiffness). However, the official prompting guide gives no general negative-prompt instruction."},{"syntax":"Special / trigger tokens","supported":"unknown","notes":""},{"syntax":"Regional / masked prompting","supported":"unknown","notes":""}]', '[{"length":"Too short","effect":"Under-described motion and scene; LTX''s automatic prompt enhancer (enhance_prompt) is recommended when the prompt is short, rough, or was written for a different model"},{"length":"Ideal","effect":"4–8 descriptive sentences, within 200 words (official guidance); every sentence must add concrete visual or audio detail"},{"length":"Too long","effect":"Overcomplicated prompts with too many characters, layered actions, or excessive objects reduce clarity and model accuracy (scene complexity overload)"}]', '[Scene/Environment]. [Subject]. [Action/Motion]. [Camera movement]. [Style/Aesthetic]. [Audio]', '[{"include":"Scene set FIRST (official tip: prevents morphing/scene changes)","examples":"\"Rain-soaked neon-lit Tokyo alley at night.\""},{"include":"Present-tense action verbs","examples":"\"walks, turns, exhales, reaches, strides, grips\""},{"include":"Chronological sequencing","examples":"\"first… then… as… while…\"; note any changes or sudden events"},{"include":"Cinematic camera language","examples":"\"slow dolly in, handheld tracking, over-the-shoulder, wide establishing shot, rack focus, static frame\""},{"include":"Precise physical detail","examples":"Age, ethnicity, clothing, facial micro-expressions; exact body/hand positions"},{"include":"Lighting and color specifics","examples":"\"golden hour, fluorescent, neon glow, flickering candles, dramatic shadows, muted palette\""},{"include":"Atmospheric elements","examples":"\"fog, rain, dust, particles, smoke, mist\""},{"include":"Audio description","examples":"Ambient sounds, music, dialogue in quotation marks, language/accent"},{"include":"Era/genre terms","examples":"\"1940s film, 70s TV drama, 80s news broadcast, film noir, documentary\""},{"include":"Style terms named early","examples":"\"painterly, noir, analog film look, fashion editorial, stop-motion, cyberpunk\""}]', '[{"instead":"Emotional labels (\"she is sad, confused\")","write":"Physical cues: \"her face crumples; she takes a shaky breath\""},{"instead":"Comma-separated tag lists","write":"A single flowing paragraph with present-tense verbs"},{"instead":"Mixed/conflicting light sources (\"warm sunset with cold fluorescent glow\")","write":"One coherent light logic per shot, unless clearly motivated"},{"instead":"Prompts written for other models (e.g. Kling/Seedance shot lists) pasted in unchanged","write":"Rewrite into LTX''s flowing-paragraph structure, or run through the prompt enhancer"},{"instead":"Text, signage, logos, brand names","write":"Leave out — 2.3 does not render readable on-screen text"},{"instead":"Chaotic fast-twisting motion (jumping, juggling)","write":"Simpler, plausible motion; dancing works better than acrobatics"},{"instead":"Crowded frames with many characters and layered actions","write":"A few clear characters and actions per shot"}]', '[{"param":"Steps","value":"30 (one-stage default for LTX-2.3; distilled pipelines reduce further)"},{"param":"Guidance / CFG Scale","value":"Video 3.0 / audio 7.0 (pipeline defaults)"},{"param":"Resolution","value":"768×512 default; up to ~1024×1536 reported in community integrations; native 4K rendering claimed for the family"},{"param":"Scheduler / Sampler","value":"(leave blank — not documented in official materials)"},{"param":"Dtype / Precision","value":"(leave blank — not documented in official materials)"}]', '[{"title":"Pasting a Kling/Seedance prompt unchanged","detail":"→ tag syntax and shot-list formatting from other models underperform on LTX; rewrite into a flowing paragraph or use the prompt enhancer."},{"title":"Describing appearance without action in t2v","detail":"→ appearance alone gives the model nothing to animate; every sentence needs an active verb."},{"title":"Re-describing the input image in i2v","detail":"→ the model already sees the image; spend the prompt on motion, action sequencing, and camera moves."},{"title":"Using abstract emotion words","detail":"→ \"sad,\" \"confused\" don''t render; describe posture, gesture, and facial expression instead."},{"title":"Stacking too many characters/actions","detail":"→ crowded scenes lose clarity; keep the shot focused on a few clear subjects."},{"title":"Forgetting to write pauses into the prompt","detail":"→ the model will not add beats you didn''t describe."}]', 'Target model: LTX-Video 2.3 (video).
How to prompt it: Write one flowing, present-tense paragraph that describes the action chronologically, like a cinematographer dictating a shot list — never comma-separated tag soup or a shot list with sluglines.
Prompt length — too short: Under-described motion and scene; LTX''s automatic prompt enhancer (enhance_prompt) is recommended when the prompt is short, rough, or was written for a different model | ideal: 4–8 descriptive sentences, within 200 words (official guidance); every sentence must add concrete visual or audio detail | too long: Overcomplicated prompts with too many characters, layered actions, or excessive objects reduce clarity and model accuracy (scene complexity overload)
Syntax — supported: Negative prompt
Negative prompt: YES — Pipeline recipes supply a default negative prompt; ComfyUI integrations expose it (e.g. "still image, no movements" for i2v stiffness). However, the official prompting guide gives no general negative-prompt instruction.
Include: Scene set FIRST (official tip: prevents morphing/scene changes); Present-tense action verbs; Chronological sequencing; Cinematic camera language; Precise physical detail; Lighting and color specifics
Avoid: Emotional labels ("she is sad, confused"); Comma-separated tag lists; Mixed/conflicting light sources ("warm sunset with cold fluorescent glow"); Prompts written for other models (e.g. Kling/Seedance shot lists) pasted in unchanged; Text, signage, logos, brand names; Chaotic fast-twisting motion (jumping, juggling)
Recommended settings: Steps 30 (one-stage default for LTX-2.3; distilled pipelines reduce further); Guidance / CFG Scale Video 3.0 / audio 7.0 (pipeline defaults); Resolution 768×512 default; up to ~1024×1536 reported in community integrations; native 4K rendering claimed for the family; Scheduler / Sampler (leave blank — not documented in official materials); Dtype / Precision (leave blank — not documented in official materials)
Common mistakes: Pasting a Kling/Seedance prompt unchanged; Describing appearance without action in t2v; Re-describing the input image in i2v; Using abstract emotion words; Stacking too many characters/actions', 'LTX-2.3 is the March 2026 open-weight release of Lightricks'' LTX-2 audio-video foundation model (weights on HuggingFace as Lightricks/LTX-2.3; code repo Lightricks/LTX-2). It generates synchronized video and audio together in a single diffusion model, and was released alongside a desktop video editor enabling the model to run locally on consumer hardware. Like the rest of the LTX-2 family it is designed for very fast iteration (the "Fast" operating mode), so prompt refinement is part of the intended workflow. Versus LTX-2 (base, January 2026 open release), 2.3 brought higher resolution, richer color, and improved subject consistency. It predates LTX-2.5''s native multi-shot generation, so 2.3 prompts are single continuous takes.', '[{"url":"https://github.com/Lightricks/LTX-2","note":"https://github.com/Lightricks/LTX-2 (official repo — \"Prompting for LTX-2\" section, prompt enhancement)"},{"url":"https://ltx.io/blog/prompting-guide-for-ltx-2","note":"https://ltx.io/blog/prompting-guide-for-ltx-2 (official LTX-2 prompting guide: key aspects, what works/avoid)"},{"url":"https://docs.ltx.io/api-documentation/implementation-guides/prompting-guide","note":"https://docs.ltx.io/api-documentation/implementation-guides/prompting-guide (official LTX docs prompting guide: structure, enhancer, multi-shot)"},{"url":"https://github.com/babakarto/promptiusmaximus/blob/HEAD/02-VIDEO/ltx-cineclaw/prompting-guide.md","note":"https://github.com/babakarto/promptiusmaximus/blob/HEAD/02-VIDEO/ltx-cineclaw/prompting-guide.md (community prompting guide citing official LTX Studio tips)"},{"url":"https://github.com/babakarto/promptiusmaximus/blob/HEAD/02-VIDEO/ltx-cineclaw/ltx2-prompt-guide-advanced.md","note":"https://github.com/babakarto/promptiusmaximus/blob/HEAD/02-VIDEO/ltx-cineclaw/ltx2-prompt-guide-advanced.md (community advanced guide)"},{"url":"https://replicate.com/lightricks/ltx-2-pro","note":"https://replicate.com/lightricks/ltx-2-pro (prompt guidelines for the LTX-2 family)"},{"url":"https://github.com/liunix61/vllm-omni/blob/HEAD/recipes/LTX/LTX-2.md","note":"https://github.com/liunix61/vllm-omni/blob/HEAD/recipes/LTX/LTX-2.md (pipeline defaults: steps, CFG, default negative prompt)"},{"url":"https://huggingface.co/Kijai/LTX2.3_comfy/discussions/49","note":"https://huggingface.co/Kijai/LTX2.3_comfy/discussions/49 (community i2v motion-prompting and negative-prompt practice)"},{"url":"https://en.wikipedia.org/wiki/LTX_(text-to-video_model","note":"https://en.wikipedia.org/wiki/LTX_(text-to-video_model) (release timeline, feature overview)"}]', 'a5f5bd034e20dbbd79c21eaf01b00c69');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('video/ltx/1', 'video', 'ltx', 'LTX-Video', '2.5', '2.5', 1, 'video', 'Prompt Guide: LTX-2.5', 'models/video/ltx-2.5.md', 5, 'Same family rule as 2.3: write a single flowing, present-tense paragraph with chronological action — and for multi-shot scenes, write the cuts in prose ("A hard cut transitions to…"), never as a shot list or screenplay sluglines.', '[{"syntax":"Weighting (word:1.4)","supported":"unknown","notes":"No documented support in official prompting guidance"},{"syntax":"Emphasis ((word))","supported":"unknown","notes":"No documented support"},{"syntax":"BREAK keyword","supported":"unknown","notes":""},{"syntax":"[from:to:step] blending","supported":"unknown","notes":""},{"syntax":"Negative prompt","supported":"yes","notes":"Pipeline recipes supply a default negative prompt; community integrations expose it. The official prompting guide has \"no general negative-prompt instruction\" (per independent capability audit)."},{"syntax":"Special / trigger tokens","supported":"unknown","notes":""},{"syntax":"Regional / masked prompting","supported":"unknown","notes":""}]', '[{"length":"Too short","effect":"Under-described motion/scene; the prompt enhancer is recommended when the prompt is short, rough, or written for another model"},{"length":"Ideal","effect":"Single shot: 4–8 descriptive sentences, within ~200 words. Multi-shot: a full scene as one chronological paragraph; prefer 2–4 shots per generation, with shorter, clearer beats per shot as cuts increase"},{"length":"Too long","effect":"Too many characters, layered actions, or excessive objects reduce clarity; with the duration predictor on, overstuffed prompts also mislead the predicted clip length"}]', '[Scene/Environment]. [Subject]. [Action/Motion]. [Camera movement]. [Style/Aesthetic]. [Audio]', '[{"include":"Scene set FIRST","examples":"Prevents morphing/scene changes"},{"include":"Present-tense action verbs","examples":"\"walks, turns, exhales, reaches\" — every sentence needs a verb that does something"},{"include":"Chronological sequencing","examples":"\"Initially…\", \"A moment later…\", \"Simultaneously…\""},{"include":"Cinematic camera language","examples":"\"slow dolly in, handheld tracking, over-the-shoulder, rack focus\""},{"include":"Precise physical detail","examples":"Age, clothing, micro-expressions; exact body/hand positions"},{"include":"Lighting and color specifics","examples":"\"golden hour, neon glow, flickering candles, muted palette\""},{"include":"Atmospheric elements","examples":"\"fog, rain, dust, mist, reflections\""},{"include":"Audio description","examples":"Dialogue in quotation marks with language/accent; ambient sounds"},{"include":"Era/genre terms","examples":"\"1940s film, film noir, documentary, 80s news broadcast\""},{"include":"At every cut (multi-shot): transition named, shot re-established, identities re-stated, audio continuity stated","examples":"\"A match cut connects…\"; \"the woman in the red coat, earlier at the table, now…\"; \"the music drops to a low drone\""},{"include":"Written-in pauses","examples":"\"she pauses\", \"a beat of silence\" — the duration predictor times the clip to the action you describe and will not add pauses you didn''t prompt for"}]', '[{"instead":"Emotional labels (\"she is sad, confused\")","write":"Physical cues: \"her face crumples; she takes a shaky breath\""},{"instead":"Shot lists, numbered beats, screenplay sluglines (unless the cut is also described in prose)","write":"One chronological paragraph with transitions in natural language"},{"instead":"Prompts for other models pasted unchanged (Kling/Seedance shot lists)","write":"Rewrite into LTX''s flowing-paragraph structure or use the prompt enhancer"},{"instead":"Conflicting geography or unexplained costume changes between cuts","write":"Only jump time/place/costume if you say so explicitly"},{"instead":"Mixed/conflicting light sources","write":"One coherent light logic per shot"},{"instead":"Comma-separated tag lists","write":"Single flowing paragraph, present tense"},{"instead":"Text, signage, logos (as relied-upon elements)","write":"Leave out — 2.5 improves short-text accuracy but exact spelling/consistency is not guaranteed; add titles in post"},{"instead":"Chaotic fast-twisting motion","write":"Simpler, plausible motion; dancing works better than acrobatics"},{"instead":"Crowded frames","write":"A few clear characters and actions per shot"}]', '[{"param":"Steps","value":"(leave blank — 2.5-specific defaults not published; 2.3 one-stage default is 30, base LTX-2 40)"},{"param":"Guidance / CFG Scale","value":"Video 3.0 / audio 7.0 (family pipeline defaults; 2.5-specific values not published)"},{"param":"Resolution","value":"Up to 4K rendering reported for the family; OpenEXR/HDR input-output workflows"},{"param":"Scheduler / Sampler","value":"(leave blank — not documented in official materials)"},{"param":"Dtype / Precision","value":"(leave blank — not documented in official materials)"}]', '[{"title":"Using a shot list for multi-shot prompts","detail":"→ LTX-2.5''s multi-shot mode explicitly wants cuts described in prose; numbered shots/sluglines without prose transitions underperform."},{"title":"Forgetting audio continuity across cuts","detail":"→ at every cut, state whether music/dialogue/ambience continues or changes, or the soundscape will drift."},{"title":"Not re-identifying subjects after a cut","detail":"→ reuse the same visual identifiers (\"the woman in the red coat, earlier at the table, now…\") to keep identity consistent across shots."},{"title":"Writing pacing for the duration predictor without writing the beats","detail":"→ \"she pauses\", \"a beat of silence\" must be in the prompt; the model adds no pauses of its own."},{"title":"Pasting other models'' prompts unchanged","detail":"→ tag syntax and shot-list formatting from Kling/Seedance don''t carry over; rewrite into flowing paragraphs or run the prompt enhancer."},{"title":"Re-describing the input image in i2v","detail":"→ spend the prompt on action sequencing and camera movement instead."},{"title":"Abstract emotion labels","detail":"→ describe posture, gesture, facial expression; never rely on \"sad\"/\"confused\" alone."}]', 'Target model: LTX-Video 2.5 (video).
How to prompt it: Same family rule as 2.3: write a single flowing, present-tense paragraph with chronological action — and for multi-shot scenes, write the cuts in prose ("A hard cut transitions to…"), never as a shot list or screenplay sluglines.
Prompt length — too short: Under-described motion/scene; the prompt enhancer is recommended when the prompt is short, rough, or written for another model | ideal: Single shot: 4–8 descriptive sentences, within ~200 words. Multi-shot: a full scene as one chronological paragraph; prefer 2–4 shots per generation, with shorter, clearer beats per shot as cuts increase | too long: Too many characters, layered actions, or excessive objects reduce clarity; with the duration predictor on, overstuffed prompts also mislead the predicted clip length
Syntax — supported: Negative prompt
Negative prompt: YES — Pipeline recipes supply a default negative prompt; community integrations expose it. The official prompting guide has "no general negative-prompt instruction" (per independent capability audit).
Include: Scene set FIRST; Present-tense action verbs; Chronological sequencing; Cinematic camera language; Precise physical detail; Lighting and color specifics
Avoid: Emotional labels ("she is sad, confused"); Shot lists, numbered beats, screenplay sluglines (unless the cut is also described in prose); Prompts for other models pasted unchanged (Kling/Seedance shot lists); Conflicting geography or unexplained costume changes between cuts; Mixed/conflicting light sources; Comma-separated tag lists
Recommended settings: Steps (leave blank — 2.5-specific defaults not published; 2.3 one-stage default is 30, base LTX-2 40); Guidance / CFG Scale Video 3.0 / audio 7.0 (family pipeline defaults; 2.5-specific values not published); Resolution Up to 4K rendering reported for the family; OpenEXR/HDR input-output workflows; Scheduler / Sampler (leave blank — not documented in official materials); Dtype / Precision (leave blank — not documented in official materials)
Common mistakes: Using a shot list for multi-shot prompts; Forgetting audio continuity across cuts; Not re-identifying subjects after a cut; Writing pacing for the duration predictor without writing the beats; Pasting other models'' prompts unchanged', 'LTX-2.5 is the August 2026 open-weight release of the LTX-2 family (weights on HuggingFace as Lightricks/LTX-2.5; code repo Lightricks/LTX-2). It keeps the LTX-2 formula — synchronized audio-video generation in one diffusion model, very fast iteration — and adds two headline capabilities with no equivalent in LTX-2/2.3: native multi-shot generation (several distinct shots in a single inference pass, cutting together as one cohesive scene) and an optional duration predictor head that sizes the clip to the action described in the prompt. It also ships an optional diffusion decoder (replacing the convolutional VAE decoder) and a pretrained checkpoint intended for domain-specific fine-tuning. Reported speed: a 10-second video in under 7 seconds. Prompting is the same flowing-paragraph style as 2.3, plus a new prose-based multi-shot pattern — explicitly not a shot list.', '[{"url":"https://github.com/Lightricks/LTX-2","note":"https://github.com/Lightricks/LTX-2 (official repo — \"Prompting for LTX-2\" section, prompt enhancement)"},{"url":"https://ltx.io/blog/prompting-guide-for-ltx-2","note":"https://ltx.io/blog/prompting-guide-for-ltx-2 (official LTX-2 prompting guide)"},{"url":"https://docs.ltx.io/api-documentation/implementation-guides/prompting-guide","note":"https://docs.ltx.io/api-documentation/implementation-guides/prompting-guide (official LTX docs: structure, multi-shot, prompt enhancer, Dub-It, sample prompts)"},{"url":"https://github.com/babakarto/promptiusmaximus/blob/HEAD/02-VIDEO/ltx-cineclaw/prompting-guide.md","note":"https://github.com/babakarto/promptiusmaximus/blob/HEAD/02-VIDEO/ltx-cineclaw/prompting-guide.md (community guide citing official LTX Studio tips)"},{"url":"https://github.com/babakarto/promptiusmaximus/blob/HEAD/02-VIDEO/ltx-cineclaw/ltx2-prompt-guide-advanced.md","note":"https://github.com/babakarto/promptiusmaximus/blob/HEAD/02-VIDEO/ltx-cineclaw/ltx2-prompt-guide-advanced.md (community advanced guide)"},{"url":"https://github.com/liunix61/vllm-omni/blob/HEAD/recipes/LTX/LTX-2.md","note":"https://github.com/liunix61/vllm-omni/blob/HEAD/recipes/LTX/LTX-2.md (pipeline defaults: steps, CFG, negative prompt, duration head, diffusion decoder)"},{"url":"https://github.com/rh-runninghub/minimax-h3-multigpu-lightning/blob/HEAD/sglang/docs/cookbook/diffusion/LTX/LTX2.5.mdx","note":"https://github.com/rh-runninghub/minimax-h3-multigpu-lightning/blob/HEAD/sglang/docs/cookbook/diffusion/LTX/LTX2.5.mdx (LTX-2.5 components: duration head, diffusion decoder)"},{"url":"https://www.scriptbyai.com/local-ai-video-editor-ltx-desktop/","note":"https://www.scriptbyai.com/local-ai-video-editor-ltx-desktop/ (LTX Desktop / LTX-2.5 Fast as default local model)"},{"url":"https://gen-ai.news/stories/ltx-2-5-ltx-s-latest-ai-open-source-foundation-model-ltx-2e69a2","note":"https://gen-ai.news/stories/ltx-2-5-ltx-s-latest-ai-open-source-foundation-model-ltx-2e69a2 (LTX-2.5 release overview: multi-shot, speed)"},{"url":"https://huggingface.co/Kijai/LTX2.3_comfy/discussions/49","note":"https://huggingface.co/Kijai/LTX2.3_comfy/discussions/49 (community i2v motion-prompting practice, applicable across 2.x)"},{"url":"https://github.com/nickpittas/directorsconsole/blob/HEAD/CinemaPromptEngineering/Documentation/model_prompting/video_capability_matrix.md","note":"https://github.com/nickpittas/directorsconsole/blob/HEAD/CinemaPromptEngineering/Documentation/model_prompting/video_capability_matrix.md (capability audit: no general negative-prompt instruction in official guide)"},{"url":"https://en.wikipedia.org/wiki/LTX_(text-to-video_model","note":"https://en.wikipedia.org/wiki/LTX_(text-to-video_model) (release timeline, feature overview)"}]', 'bedeb0d07e435af3f4d112df9c9899f4');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('video/seedance/0', 'video', 'seedance', 'Seedance', '2.0', '2.0', 0, 'video', 'Prompt Guide: Seedance 2.0', 'models/video/seedance-2.0.md', 5, 'Think like a director handing a shot list to a crew, not a tourist describing a postcard. The model responds best to cinematographic language: named subjects, concrete action beats, one camera move per shot, and explicit audio. Vague adjectives ("beautiful", "cinematic") do far less work than concrete blocking.', '[{"syntax":"Weighting (word:1.4)","supported":"no","notes":"No weight syntax documented for Seedance 2.0; use concrete wording instead."},{"syntax":"Emphasis ((word))","supported":"no","notes":""},{"syntax":"BREAK keyword","supported":"no","notes":""},{"syntax":"[from:to:step] blending","supported":"no","notes":""},{"syntax":"Negative prompt","supported":"as inline constraint words only","notes":"No separate negative-prompt API field; exclusions go in the prompt as natural-language constraints (e.g. \"keep it subtitle-free\", \"do not generate a watermark\")."},{"syntax":"Special / trigger tokens","supported":"yes","notes":"@Image N, @Video N, @Audio N reference binding tokens; Define keyword to name subjects from references; {dialogue} or quoted dialogue for lip-sync."},{"syntax":"Regional / masked prompting","supported":"no","notes":""}]', '[{"length":"Too short","effect":"The model guesses missing slots — subject detail, camera, motion, audio — producing generic output."},{"length":"Ideal","effect":"BytePlus recommends keeping prompts under 1,000 words so information stays focused. Community evidence suggests 60–100 characters for a single shot, 200–700 for multi-shot prompts."},{"length":"Too long","effect":"Dilutes focus; the official ceiling is 32,000 characters per prompt (hard limit, not a quality target). Generation parameters (duration, resolution, aspect ratio) belong in the API/UI, not the prompt."}]', 'Asset preparation: → Subject definitions: → Prompt: (task type) → Shot 1: → Shot 2: → Quality and constraints:', '[{"include":"Cinematographic camera language","examples":"slow push-in, whip pan, crane rise, handheld follow, medium tracking shot from the left, low angle, over-the-shoulder"},{"include":"Time-segmented beats (when you want them)","examples":"Between 0 and 4 seconds, this happens. Between 4 and 8 seconds... (documented as supported by community practice)"},{"include":"Explicit audio design","examples":"Audio: rain patter and distant thunder, sizzling oil and jazz music, quiet room ambience"},{"include":"Dialogue with speaker and emotion","examples":"{How did the exam go? Did you pass?} or {Speaker A, urgent}: Did you hear that? — use when generate_audio is on for lip-sync"},{"include":"Reference binding in every shot","examples":"Girl @Image 1, dormitory entrance from @Image 2, Match the medium-shot dolly movement from @Video 1, Blend the indoor ambience from @Audio 1"},{"include":"Body-part-level action detail","examples":"fingers tighten briefly around her bag strap, lowers her head and lets her shoulders drop"},{"include":"Spatial continuity contract for movement-heavy scenes","examples":"Start: [positions] → Travel axis: [origin → destination] → End: [final positions]"},{"include":"Lens/format anchors","examples":"Sony A7S3, 35mm follow, shallow depth of field, subtle film grain (community evidence shows lens tokens work)"}]', '[{"instead":"A sad woman walks away (abstract emotion)","write":"Externalize: she lowers her head, shoulders trembling slightly, fingers unconsciously clutching her coat"},{"instead":"He runs very fast and jumps dramatically (high-burst action)","write":"he walks briskly; slowly raise a hand — prefer slow, gentle, continuous motion; avoid sprinting, big jumps, violent rolls"},{"instead":"\"very sad\", \"extremely angry\" (intensity adverbs)","write":"Physical details from the emotion table (anger = both fists clenched, jawline tense, chest heaving)"},{"instead":"no people, no text (bare negations)","write":"Positive constraint phrasing: an empty street, keep it subtitle-free, do not generate a logo, watermark, or text overlay"},{"instead":"Shot 1 (0-4s), Shot 2 (4-8s) when the API duration is different","write":"Set total length with the API duration parameter; use second-level timecodes only when explicitly needed, contiguous and matching the API duration"},{"instead":"Describing expression/pose as a subject''s fixed identity","write":"Define subjects with static features only (clothing, hairstyle, build) — never mutable attributes like expression or pose"},{"instead":"Uploading real human faces as references","write":"Not accepted directly; use Seedance/Seedream-generated outputs (within 30 days), preset digital characters, or verified authorized assets"},{"instead":"Relying on \"no aura\" to suppress a reference''s unwanted pixels","write":"Clean or replace the reference — reference content overpowers negative wording"}]', '[{"param":"Duration","value":"4–15 s per generation (set via API duration parameter)"},{"param":"Resolution","value":"Standard: 480P / 720P / 1080P / 4K; Fast & Mini: 480P / 720P only"},{"param":"Aspect ratio","value":"16:9, 9:16, 4:3, 3:4, 21:9, 1:1 (match to composition: vertical favors portraits, ultrawide favors establishing shots)"},{"param":"Audio","value":"generate_audio: true to enable native synchronized audio; dialogue needs the spoken line in {braces} or quotes"},{"param":"Seed","value":"Pin once a look is approved to reproduce the same visual family"},{"param":"camera_fixed","value":"Default false; set true to lock camera position"},{"param":"return_last_frame","value":"Set true to chain multi-shot continuity"}]', '[{"title":"Contradicting the brief across sections","detail":"(e.g. \"single continuous shot\" plus several cuts, or \"no powers\" plus a reference containing an aura) — a contradiction is more damaging than a missing adjective; check for them before generating."},{"title":"Only naming references in the inventory but never binding them inline","detail":"— the asset list alone doesn''t bind; every shot must repeat the applicable @Image N / @Video N / @Audio N where it''s used."},{"title":"Using mutable attributes in Define","detail":"(expression, pose) — labels must use stable static features (clothing, hairstyle, build) so they survive across shots."},{"title":"Requesting high-burst action","detail":"(sprinting, big jumps, violent rolls) — prefer slow, gentle, continuous motion for clean results."},{"title":"Stacking too many beats into 15 seconds","detail":"— cap at ~3 major action beats or 4 tightly related shots; split larger scenes into separate generations chained with return_last_frame."},{"title":"Putting generation parameters in the prompt text","detail":"— duration, resolution, and aspect ratio go in the API/UI, not the prompt."},{"title":"Re-describing first-frame content in I2V","detail":"— describe motion, camera, and audio; leave the image''s content alone."}]', 'Target model: Seedance 2.0 (video).
How to prompt it: Think like a director handing a shot list to a crew, not a tourist describing a postcard. The model responds best to cinematographic language: named subjects, concrete action beats, one camera move per shot, and explicit audio. Vague adjectives ("beautiful", "cinematic") do far less work than concrete blocking.
Prompt length — too short: The model guesses missing slots — subject detail, camera, motion, audio — producing generic output. | ideal: BytePlus recommends keeping prompts under 1,000 words so information stays focused. Community evidence suggests 60–100 characters for a single shot, 200–700 for multi-shot prompts. | too long: Dilutes focus; the official ceiling is 32,000 characters per prompt (hard limit, not a quality target). Generation parameters (duration, resolution, aspect ratio) belong in the API/UI, not the prompt.
Syntax — supported: Special / trigger tokens | NOT supported: Weighting (word:1.4), Emphasis ((word)), BREAK keyword, [from:to:step] blending, Regional / masked prompting
Negative prompt: AS INLINE CONSTRAINT WORDS ONLY — No separate negative-prompt API field; exclusions go in the prompt as natural-language constraints (e.g. "keep it subtitle-free", "do not generate a watermark").
Include: Cinematographic camera language; Time-segmented beats (when you want them); Explicit audio design; Dialogue with speaker and emotion; Reference binding in every shot; Body-part-level action detail
Avoid: A sad woman walks away (abstract emotion); He runs very fast and jumps dramatically (high-burst action); "very sad", "extremely angry" (intensity adverbs); no people, no text (bare negations); Shot 1 (0-4s), Shot 2 (4-8s) when the API duration is different; Describing expression/pose as a subject''s fixed identity
Recommended settings: Duration 4–15 s per generation (set via API duration parameter); Resolution Standard: 480P / 720P / 1080P / 4K; Fast & Mini: 480P / 720P only; Aspect ratio 16:9, 9:16, 4:3, 3:4, 21:9, 1:1 (match to composition: vertical favors portraits, ultrawide favors establishing shots); Audio generate_audio: true to enable native synchronized audio; dialogue needs the spoken line in {braces} or quotes; Seed Pin once a look is approved to reproduce the same visual family; camera_fixed Default false; set true to lock camera position
Common mistakes: Contradicting the brief across sections; Only naming references in the inventory but never binding them inline; Using mutable attributes in Define; Requesting high-burst action; Stacking too many beats into 15 seconds', 'Seedance 2.0 is a multimodal video generation model that reads text, images, video, and audio simultaneously and decomposes them into a spatial layer (what is in the frame) and a temporal layer (how things change over time). It natively co-generates synchronized audio (dialogue with lip-sync, SFX, ambience, music) alongside video in a single pass. Its signature strength is multi-shot storytelling from one prompt — it holds character identity and style across cuts better than most contemporaries — and precise interpretation of reference assets via an @Image N / @Video N / @Audio N binding syntax.', '[{"url":"https://github.com/byteplus-sa/seed-prompt-studio/blob/HEAD/.agents/skills/seedance-prompt-20/SKILL.md","note":"https://github.com/byteplus-sa/seed-prompt-studio/blob/HEAD/.agents/skills/seedance-prompt-20/SKILL.md (structure and rules sourced from the official BytePlus Seedance 2.0 prompt guide at docs.byteplus.com/en/docs/ModelArk/2222480)"},{"url":"https://github.com/rrebiz/seedance-2.0-api","note":"https://github.com/rrebiz/seedance-2.0-api (cinematographic prompting template and lip-sync/reference guidance)"},{"url":"https://medium.com/@cliprise/writing-seedance-2-0-prompts-like-a-director-not-a-tourist-db70af20e7b8","note":"https://medium.com/@cliprise/writing-seedance-2-0-prompts-like-a-director-not-a-tourist-db70af20e7b8 (six-slot formula and worked example)"},{"url":"https://www.socialmediaexaminer.com/how-to-think-like-a-filmmaker-ai-video-with-seedance/","note":"https://www.socialmediaexaminer.com/how-to-think-like-a-filmmaker-ai-video-with-seedance/ (time-segmented prompting, 5–30s duration guidance)"},{"url":"https://github.com/Hao0321/ai-media-generator/releases/tag/v1.1.0","note":"https://github.com/Hao0321/ai-media-generator/releases/tag/v1.1.0 (community evidence: lens tokens, time-block formats, bilingual prompts)"}]', '034445e2935e62dfa3a16d67dbdbe2e3');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('video/seedance/1', 'video', 'seedance', 'Seedance', '2.5', '2.5', 1, 'video', 'Prompt Guide: Seedance 2.5', 'models/video/seedance-2.5.md', 5, 'Write a compact directing brief, not a pile of style adjectives: state the subject and its action first, then add only the parts that matter — scene, visual style, camera move, audio. 2.5''s strength is time: the prompt should read as a timeline (establishment → action → turn → final frame), with each stage containing one primary change and a clear end state.', '[{"syntax":"Weighting (word:1.4)","supported":"no","notes":"No weight syntax documented; use concrete wording instead."},{"syntax":"Emphasis ((word))","supported":"no","notes":""},{"syntax":"BREAK keyword","supported":"no","notes":""},{"syntax":"[from:to:step] blending","supported":"no","notes":""},{"syntax":"Negative prompt","supported":"as inline constraint words only","notes":"No separate negative-prompt field documented; exclusions go in the prompt as natural language (e.g. \"no redesign, duplicates, fake text, watermark\")."},{"syntax":"Special / trigger tokens","supported":"yes","notes":"Reference binding tokens (@Image N-style asset labels; give each reference an explicit role), dialogue in double quotes, timestamp ranges like 00:00–00:04."},{"syntax":"Regional / masked prompting","supported":"no","notes":""}]', '[{"length":"Too short","effect":"The model fills gaps in subject, motion, and audio with defaults; multi-beat scenes lose their pacing."},{"length":"Ideal","effect":"State subject + action first, then add detail only to critical movements. Describe the primary action at body-part level (range, speed, force). One strong action beats four unrelated actions for short clips."},{"length":"Too long","effect":"A third-party platform guide advises staying under 15,000 characters and spending the budget on composition, lighting, and motion rather than filler adjectives. (Platform guidance, not official BytePlus.)"}]', '[Subject] + [Action or Event] + [Scene and Environment (optional)] + [Visual Style (optional)] + [Camera Movement/Cut (optional)] + [Audio (optional)]', '[{"include":"Subject + action first, always","examples":"A lone cyclist + rides through a neon-lit alley"},{"include":"Named reference roles","examples":"Image 1 locks identity; Video 1 provides camera path only — give every asset a job and a \"do not use for\" boundary"},{"include":"Continuity invariants","examples":"What must never change: bottle silhouette, cap, label position — restate where it matters"},{"include":"Timestamped beats for multi-shot scenes","examples":"00:00–00:04 — establish... (time allocation, not edit points)"},{"include":"Observable motion acceptance criteria","examples":"Direction, relationship, contact, or end state — e.g. arc 20 degrees and stop on the hero frame"},{"include":"Concrete camera moves with endpoints","examples":"eye-level medium shot, 20-degree arc, slow rack focus to the bottle"},{"include":"Audio as sound direction","examples":"Cap click at 00:08, fine bubbles, low original rhythm — dialogue, SFX, ambience with sync cues"},{"include":"Dialogue: short, quoted, with delivery tone","examples":"\"Watch the wheel.\" — keep lines short; name the tone if a specific read is needed"},{"include":"Explicit editing instructions (edit mode)","examples":"One editing master, edit scope, target quantity, and what to preserve"}]', '[{"instead":"A then B then C then D event stacking","write":"Timestamped beats or numbered stages, each with one primary change"},{"instead":"very sad, extremely angry (abstract emotion)","write":"Externalize: shoulders drop, eyes redden, voice softens (generalized from the Seedance family rule — documented for 2.0)"},{"instead":"Prompting every reference to appear at once","write":"Select references per scene: \"Image 2 controls the set only\" — the goal is selecting correct materials, not piling them in"},{"instead":"30 seconds of everything in one pass","write":"Set the actual duration via the duration parameter; split ideas needing location + costume + VFX + dialogue changes into separate generations"},{"instead":"Putting duration/aspect ratio/resolution in the prompt text","write":"Use the generation controls; keep the prompt about the frame''s look and motion"},{"instead":"Assuming timestamps are edit points","write":"They allocate time; do not rely on them for frame-accurate cuts"}]', '[{"param":"Duration","value":"4–30 s per generation (set via API duration parameter; 30 s is the ceiling, not the target)"},{"param":"Resolution","value":"480p / 720p (per platform; 4K is not supported by 2.5 — use Seedance 2.0 for 4K output)"},{"param":"Aspect ratio","value":"16:9, 4:3, 1:1, 3:4, 9:16 (21:9 also reported via BytePlus docs)"},{"param":"Audio","value":"Co-generated natively; dialogue needs short quoted lines and a delivery tone"},{"param":"Seed","value":"Pin for reproducible looks (generalized from Seedance family)"},{"param":"Task auto-locks","value":"Video editing locks aspect ratio and duration to the input; first/last-frame generation locks ratio to the first image; extension locks ratio to the input"}]', '[{"title":"Describing the same action twice","detail":"— the six-part formula warns against it; repetition reads as a second, conflicting action."},{"title":"Overloading one generation","detail":"— a beat needing location + costume + complex VFX + dialogue at once should be split; 2.5 can stage a lot, but each stage should hold one primary change."},{"title":"Treating timestamps as edit points","detail":"— they allocate time, not frame-accurate cuts; plan transitions loosely."},{"title":"Letting references leak","detail":"— a motion-reference video or control diagram can bleed pixels and colors into the frame; translate control images to text and give every asset a role plus a \"do not use for\" boundary."},{"title":"Expecting pixel-accurate text or typography","detail":"— for subtitles, signage, or product specs that must be exact, combine prepared references with post-production; the model cannot guarantee frame-level accuracy."},{"title":"Chasing 4K on 2.5","detail":"— 4K output is unsupported by 2.5; use Seedance 2.0 (Standard) for 4K."}]', 'Target model: Seedance 2.5 (video).
How to prompt it: Write a compact directing brief, not a pile of style adjectives: state the subject and its action first, then add only the parts that matter — scene, visual style, camera move, audio. 2.5''s strength is time: the prompt should read as a timeline (establishment → action → turn → final frame), with each stage containing one primary change and a clear end state.
Prompt length — too short: The model fills gaps in subject, motion, and audio with defaults; multi-beat scenes lose their pacing. | ideal: State subject + action first, then add detail only to critical movements. Describe the primary action at body-part level (range, speed, force). One strong action beats four unrelated actions for short clips. | too long: A third-party platform guide advises staying under 15,000 characters and spending the budget on composition, lighting, and motion rather than filler adjectives. (Platform guidance, not official BytePlus.)
Syntax — supported: Special / trigger tokens | NOT supported: Weighting (word:1.4), Emphasis ((word)), BREAK keyword, [from:to:step] blending, Regional / masked prompting
Negative prompt: AS INLINE CONSTRAINT WORDS ONLY — No separate negative-prompt field documented; exclusions go in the prompt as natural language (e.g. "no redesign, duplicates, fake text, watermark").
Include: Subject + action first, always; Named reference roles; Continuity invariants; Timestamped beats for multi-shot scenes; Observable motion acceptance criteria; Concrete camera moves with endpoints
Avoid: A then B then C then D event stacking; very sad, extremely angry (abstract emotion); Prompting every reference to appear at once; 30 seconds of everything in one pass; Putting duration/aspect ratio/resolution in the prompt text; Assuming timestamps are edit points
Recommended settings: Duration 4–30 s per generation (set via API duration parameter; 30 s is the ceiling, not the target); Resolution 480p / 720p (per platform; 4K is not supported by 2.5 — use Seedance 2.0 for 4K output); Aspect ratio 16:9, 4:3, 1:1, 3:4, 9:16 (21:9 also reported via BytePlus docs); Audio Co-generated natively; dialogue needs short quoted lines and a delivery tone; Seed Pin for reproducible looks (generalized from Seedance family); Task auto-locks Video editing locks aspect ratio and duration to the input; first/last-frame generation locks ratio to the first image; extension locks ratio to the input
Common mistakes: Describing the same action twice; Overloading one generation; Treating timestamps as edit points; Letting references leak; Expecting pixel-accurate text or typography', 'Seedance 2.5 is the successor to Seedance 2.0 and the long-form specialist of the family: up to 30 seconds of video in a single pass with natively co-generated audio (dialogue, SFX, ambience, music in one latent space). The biggest changes from 2.0 are scale and control: up to 50 multimodal reference materials (vs 15), structured video editing (subject/background replacement, audio editing, edits by timestamp), forward/backward video extension, first/last-frame generation, one-click video, and seamless transitions. Prompting moves from 2.0''s strict headed structure to a more flexible six-part formula — only Subject + Action is required — with timestamp pacing for longer scene arcs.', '[{"url":"https://github.com/byteplus-sa/seed-prompt-studio/blob/HEAD/.agents/skills/seedance-prompt-25/SKILL.md","note":"https://github.com/byteplus-sa/seed-prompt-studio/blob/HEAD/.agents/skills/seedance-prompt-25/SKILL.md (six-part formula, 50-reference budget, task auto-locks, and usage limitations sourced from the official Dreamina Seedance 2.5 prompt guide)"},{"url":"https://github.com/seaimagineai/awesome-seedance-2-5-prompts/blob/HEAD/docs/prompting-guide.md","note":"https://github.com/seaimagineai/awesome-seedance-2-5-prompts/blob/HEAD/docs/prompting-guide.md (nine-part prompt anatomy, timestamp pacing)"},{"url":"https://www.seedance.tv/blog/how-to-use-seedance-2-5","note":"https://www.seedance.tv/blog/how-to-use-seedance-2-5 (t2v/i2v workflow, 30s single-pass capability)"},{"url":"https://venice.ai/blog/seedance-2-5-prompt-tips","note":"https://venice.ai/blog/seedance-2-5-prompt-tips (dialogue quoting, camera-move naming, 15,000-char platform guidance)"},{"url":"https://github.com/gbeyrouti/seedance-prompting-claude-skill","note":"https://github.com/gbeyrouti/seedance-prompting-claude-skill (model spec: 97–721 frames, reference budgets, API model IDs)"},{"url":"https://synthesys.io/blog/seedance-vs-kling/","note":"https://synthesys.io/blog/seedance-vs-kling/ (Seedance 2.0 vs 2.5 comparison: durations, resolutions, reference counts, dialogue languages)"}]', '2a5c757cc68efc8ae19f9ff290554c33');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('video/veo/0', 'video', 'veo', 'Veo', '2', '2', 0, 'video', 'Prompt Guide: Veo 2', 'models/video/veo-2.md', 5, 'Write one richly specific sentence or two, aimed at a single focused moment — then let enhancePrompt do the cinematic expansion. Vague one-liners ("a cool video of a car") starve the model; chaining multiple events ("then he drives away, then...") muddies it.', '[{"syntax":"Weighting (word:1.4)","supported":"no","notes":"No weight syntax; use descriptive language instead."},{"syntax":"Emphasis ((word))","supported":"no","notes":""},{"syntax":"BREAK keyword","supported":"no","notes":""},{"syntax":"[from:to:step] blending","supported":"no","notes":""},{"syntax":"Negative prompt","supported":"yes","notes":"negativePrompt parameter — describe what to exclude."},{"syntax":"Special / trigger tokens","supported":"unknown","notes":""},{"syntax":"Regional / masked prompting","supported":"no","notes":""}]', '[{"length":"Too short","effect":"Generic, under-composed output — e.g. \"sunset over ocean\" gives a flat default render."},{"length":"Ideal","effect":"1–3 well-structured sentences naming subject, action, setting, style, mood, and camera (per Google''s documented prompt elements). Official docs show markedly better results from the \"more detail\" revision of the same prompt."},{"length":"Too long","effect":""}]', '[Subject] + [Action] + [Context] + [Style] + [Camera motion & composition] + [Ambiance]', '[{"include":"Richly specific, concise description","examples":"1–3 sentences; \"be richly specific, yet concise\""},{"include":"Visual, camera-readable language","examples":"Describe what the camera sees, not how you feel about it"},{"include":"Film terminology","examples":"slow dolly-in, wide establishing shot, tracking drone view, top-down, low angle"},{"include":"Focus and lens effects","examples":"shallow focus, deep focus, macro, wide-angle"},{"include":"One scene, one action per clip","examples":"A single focused moment; generate multi-event stories as separate clips"},{"include":"Named mood","examples":"melancholic, ominous, tranquil — guides color grade and pacing"},{"include":"Aspect-ratio-aware composition","examples":"9:16 for portraits/tall objects (buildings, trees, waterfalls); 16:9 for landscapes"}]', '[{"instead":"A detective finds a clue in a library, then drives across the city at night, and then confronts a suspect in a warehouse","write":"One focused moment per clip; generate three separate clips (documented \"not recommended\" example)"},{"instead":"I envision a scene where, like, the main focus, a dude, is kinda sad...","write":"Low-angle close-up shot of a man with a somber expression. The scene is dimly lit, conveying a melancholic mood"},{"instead":"A woman says: \"My name is Clara.\" (quotes can render as text in the video)","write":"A woman says: My name is Clara. — colon after the speaker''s action, no quotation marks"},{"instead":"no cars, no people (bare negations in negativePrompt)","write":"Positive exclusion phrasing: a street with no cars or traffic"},{"instead":"Audio cues (SFX:, dialogue, ambience)","write":"Nothing — Veo 2 is silent; leave sound out of the prompt and plan post-production audio"}]', '[{"param":"Duration","value":"8 s standard; durationSeconds 5–8 supported on Vertex AI"},{"param":"Resolution","value":"720p (1080p not supported for Veo 2)"},{"param":"Aspect ratio","value":"16:9 or 9:16"},{"param":"enhancePrompt","value":"true — Veo 2-only automatic prompt rewriter that adds cinematic detail (default on)"},{"param":"negativePrompt","value":"Free text describing what to exclude (Vertex AI)"},{"param":"personGeneration","value":"allow_adult / allow_all / dont_allow (region-restricted; i2v modes allow allow_adult only)"},{"param":"seed","value":"Integer for semi-reproducible output (Vertex AI; not perfectly deterministic)"},{"param":"sampleCount","value":"1–4 videos per request"}]', '[{"title":"Chaining multiple events in one 8-second prompt","detail":"— the documented top failure; one focused moment per clip."},{"title":"Writing audio cues","detail":"(dialogue, SFX, ambience) — Veo 2 is silent; they are ignored, so keep prompts visual-only."},{"title":"Using quotation marks","detail":"— they risk rendered text; use a colon after the speaker''s action instead."},{"title":"Re-describing the source image in image-to-video","detail":"— prompt for motion only; redundant description degrades results."},{"title":"Disabling enhancePrompt while writing sparse prompts","detail":"— if you rely on the auto-rewriter, keep it on; if you turn it off, you must supply the cinematic detail yourself."}]', 'Target model: Veo 2 (video).
How to prompt it: Write one richly specific sentence or two, aimed at a single focused moment — then let enhancePrompt do the cinematic expansion. Vague one-liners ("a cool video of a car") starve the model; chaining multiple events ("then he drives away, then...") muddies it.
Prompt length — too short: Generic, under-composed output — e.g. "sunset over ocean" gives a flat default render. | ideal: 1–3 well-structured sentences naming subject, action, setting, style, mood, and camera (per Google''s documented prompt elements). Official docs show markedly better results from the "more detail" revision of the same prompt. | too long: 
Syntax — supported: Negative prompt | NOT supported: Weighting (word:1.4), Emphasis ((word)), BREAK keyword, [from:to:step] blending, Regional / masked prompting
Negative prompt: YES — negativePrompt parameter — describe what to exclude.
Include: Richly specific, concise description; Visual, camera-readable language; Film terminology; Focus and lens effects; One scene, one action per clip; Named mood
Avoid: A detective finds a clue in a library, then drives across the city at night, and then confronts a suspect in a warehouse; I envision a scene where, like, the main focus, a dude, is kinda sad...; A woman says: "My name is Clara." (quotes can render as text in the video); no cars, no people (bare negations in negativePrompt); Audio cues (SFX:, dialogue, ambience)
Recommended settings: Duration 8 s standard; durationSeconds 5–8 supported on Vertex AI; Resolution 720p (1080p not supported for Veo 2); Aspect ratio 16:9 or 9:16; enhancePrompt true — Veo 2-only automatic prompt rewriter that adds cinematic detail (default on); negativePrompt Free text describing what to exclude (Vertex AI); personGeneration allow_adult / allow_all / dont_allow (region-restricted; i2v modes allow allow_adult only)
Common mistakes: Chaining multiple events in one 8-second prompt; Writing audio cues; Using quotation marks; Re-describing the source image in image-to-video; Disabling enhancePrompt while writing sparse prompts', 'Veo 2 is Google DeepMind''s earlier-generation video model: silent 8-second clips at up to 720p from text or a single input image. It has no native audio — dialogue, SFX, and ambience prompts are ignored, so sound design belongs in post-production. Its standout prompting feature is enhancePrompt, an automatic prompt rewriter (Veo 2 only) that enriches sparse prompts with cinematic detail. Prompt structure follows Google''s documented prompt-writing basics — subject/context, action, style, camera motion & composition, ambiance — with the Vertex AI best-practice rule of one focused scene per short clip.', '[{"url":"https://ai.google.dev/gemini-api/docs/veo","note":"https://ai.google.dev/gemini-api/docs/veo (prompt writing basics, element examples, model versions)"},{"url":"https://docs.cloud.google.com/vertex-ai/generative-ai/docs/video/best-practice","note":"https://docs.cloud.google.com/vertex-ai/generative-ai/docs/video/best-practice (recommended/not-recommended pairs, single-scene rule, quotation-mark guidance, image-to-video motion-only guidance)"},{"url":"https://github.com/chef-daio/agentic-skills/blob/HEAD/content-gen/video-meme/SKILL.md","note":"https://github.com/chef-daio/agentic-skills/blob/HEAD/content-gen/video-meme/SKILL.md (Veo 2 parameter reference: enhancePrompt, durations, negative prompt)"},{"url":"https://github.com/sutt/vidstr","note":"https://github.com/sutt/vidstr (Veo 2 config notes: 8 s, 720p, no 1080p)"},{"url":"https://github.com/alexnodeland-bot/skill-veo/blob/HEAD/SKILL.md","note":"https://github.com/alexnodeland-bot/skill-veo/blob/HEAD/SKILL.md (input modes, Gemini API limitations)"}]', '12d29f4c4e56a3f5432d557801182e0c');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('video/veo/1', 'video', 'veo', 'Veo', '3', '3', 1, 'video', 'Prompt Guide: Veo 3', 'models/video/veo-3.md', 4, 'Veo 3 renders what it can see and hear simultaneously — so direct both. A prompt that describes the scene but stays silent about sound gets a less complete clip; a prompt that names the speaker, their delivery, the sound effects, and the ambience gets a full scene with synced audio.', '[{"syntax":"Weighting (word:1.4)","supported":"no","notes":"No weight syntax; use descriptive language instead."},{"syntax":"Emphasis ((word))","supported":"no","notes":""},{"syntax":"BREAK keyword","supported":"no","notes":""},{"syntax":"[from:to:step] blending","supported":"no","notes":""},{"syntax":"Negative prompt","supported":"yes","notes":"negativePrompt parameter — describe what to exclude."},{"syntax":"Special / trigger tokens","supported":"unknown","notes":""},{"syntax":"Regional / masked prompting","supported":"no","notes":""}]', '[{"length":"Too short","effect":"Generic composition and thin or missing audio design."},{"length":"Ideal","effect":"1–3 well-structured sentences carrying the visual elements plus the audio layer (dialogue lines with speaker/delivery, named SFX, ambience). More detailed prompts improve motion and scene fidelity."},{"length":"Too long","effect":""}]', '[Cinematography] + [Subject] + [Action] + [Context] + [Style & Ambiance] + [Audio]', '[{"include":"Subject → action → setting → style → mood (+ audio)","examples":"The one-sentence-screenplay structure"},{"include":"Film language for camera","examples":"slow dolly-in, wide establishing shot, aerial view, POV, tracking drone"},{"include":"Identified speakers with delivery","examples":"A woman says in a weary voice, \"...\""},{"include":"Synchronized SFX","examples":"Sounds tied to visible events, described clearly"},{"include":"Defined ambience","examples":"The environmental soundscape, not just \"background noise\""},{"include":"One focused scene per clip","examples":"Multi-event stories work better as separate clips"},{"include":"Rich, specific, concise language","examples":"Visual description, not quality superlatives"}]', '[{"instead":"A detective finds a clue in a library, then drives across the city at night... (event chain)","write":"One focused moment per 8-second clip; separate clips for each beat"},{"instead":"Dialogue with no speaker or delivery (\"We have to leave now.\" floating unattributed)","write":"A woman says urgently, \"We have to leave now.\" — identify who speaks and how"},{"instead":"Sounds disconnected from the picture (thunder sounds)","write":"SFX: thunder cracks in the distance tied to a visible storm"},{"instead":"Bare negations (no cars)","write":"Exclusion phrasing: a street with no cars or traffic"},{"instead":"Quotation marks for dialogue where text-rendering is a risk","write":"Vertex AI best practice: use a colon after the speaker''s action (Clara says: It has to be here) to avoid rendered text; the Veo 3.1 guide uses quotes for speech — check output either way"}]', '[{"param":"Duration","value":"8 s"},{"param":"Resolution","value":"720p or 1080p (Vertex AI)"},{"param":"Aspect ratio","value":"16:9 or 9:16"},{"param":"Audio","value":"Native, enabled by default (includeAudio); disable only to cut cost on visual-only drafts"},{"param":"negativePrompt","value":"Free text describing what to exclude (Vertex AI)"},{"param":"personGeneration","value":"allow_adult / allow_all / dont_allow (region-restricted)"},{"param":"seed","value":"Integer for semi-reproducible output (Vertex AI)"}]', '[{"title":"Forgetting the audio layer","detail":"— Veo 3''s headline feature is native audio; prompts that describe only visuals leave dialogue, SFX, and ambience undesigned."},{"title":"Unattributed dialogue","detail":"— floating quoted lines with no speaker or delivery weaken lip-sync and performance; name who speaks and how."},{"title":"Chaining multiple events in one 8-second clip","detail":"— one focused moment per clip; split multi-beat stories into separate generations."},{"title":"Re-describing the source image in image-to-video","detail":"— the image owns the look; direct motion, camera, and sound."},{"title":"Using Veo 3''s deprecated API IDs in new work","detail":"— veo-3.0-generate-001 is listed as deprecated on the Gemini API; new builds should target Veo 3.1."}]', 'Target model: Veo 3 (video).
How to prompt it: Veo 3 renders what it can see and hear simultaneously — so direct both. A prompt that describes the scene but stays silent about sound gets a less complete clip; a prompt that names the speaker, their delivery, the sound effects, and the ambience gets a full scene with synced audio.
Prompt length — too short: Generic composition and thin or missing audio design. | ideal: 1–3 well-structured sentences carrying the visual elements plus the audio layer (dialogue lines with speaker/delivery, named SFX, ambience). More detailed prompts improve motion and scene fidelity. | too long: 
Syntax — supported: Negative prompt | NOT supported: Weighting (word:1.4), Emphasis ((word)), BREAK keyword, [from:to:step] blending, Regional / masked prompting
Negative prompt: YES — negativePrompt parameter — describe what to exclude.
Include: Subject → action → setting → style → mood (+ audio); Film language for camera; Identified speakers with delivery; Synchronized SFX; Defined ambience; One focused scene per clip
Avoid: A detective finds a clue in a library, then drives across the city at night... (event chain); Dialogue with no speaker or delivery ("We have to leave now." floating unattributed); Sounds disconnected from the picture (thunder sounds); Bare negations (no cars); Quotation marks for dialogue where text-rendering is a risk
Recommended settings: Duration 8 s; Resolution 720p or 1080p (Vertex AI); Aspect ratio 16:9 or 9:16; Audio Native, enabled by default (includeAudio); disable only to cut cost on visual-only drafts; negativePrompt Free text describing what to exclude (Vertex AI); personGeneration allow_adult / allow_all / dont_allow (region-restricted)
Common mistakes: Forgetting the audio layer; Unattributed dialogue; Chaining multiple events in one 8-second clip; Re-describing the source image in image-to-video; Using Veo 3''s deprecated API IDs in new work', 'Veo 3 (announced at Google I/O in May 2025) was the first Veo generation to natively generate audio with video — dialogue and speech, sound effects, and ambient sound, all synchronized to the visuals in a single generation. It kept the 8-second clip format and the same prompt fundamentals as Veo 2 (subject/context, action, style, camera, ambiance), but prompts now also carry a sound layer: who speaks, how they deliver it, and what the environment sounds like. On the Gemini API it is now listed as deprecated in favor of Veo 3.1, which Google says improves prompt adherence and image-to-video audiovisual quality.', '[{"url":"https://ai.google.dev/gemini-api/docs/veo","note":"https://ai.google.dev/gemini-api/docs/veo (Veo 3 dialogue/SFX examples, model version table showing Veo 3 as deprecated)"},{"url":"https://cloud.google.com/blog/products/ai-machine-learning/ultimate-prompting-guide-for-veo-3-1","note":"https://cloud.google.com/blog/products/ai-machine-learning/ultimate-prompting-guide-for-veo-3-1 (five-part prompt formula; Veo 3.1 builds on Veo 3 with stronger prompt adherence and improved image-to-video quality)"},{"url":"https://www.escapism.ai/p/how-to-use-google-veo-3-1-in-flora","note":"https://www.escapism.ai/p/how-to-use-google-veo-3-1-in-flora (Veo 3 baseline capabilities: 8 s clips, native audio, photo-to-video workflow)"},{"url":"https://docs.cloud.google.com/vertex-ai/generative-ai/docs/video/best-practice","note":"https://docs.cloud.google.com/vertex-ai/generative-ai/docs/video/best-practice (single-scene rule, quotation-mark guidance, image-to-video motion-only guidance)"},{"url":"https://github.com/lixpi/lixpi/issues/216","note":"https://github.com/lixpi/lixpi/issues/216 (summary of Google''s Veo prompt guidance: audio cue types, speaker identification, SFX synchronization)"}]', 'a805e692945e4e0f5d2a00628655f6e1');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('video/veo/2', 'video', 'veo', 'Veo', '3.1', '3.1', 2, 'video', 'Prompt Guide: Veo 3.1', 'models/video/veo-3.1.md', 5, 'Veo 3.1 is a directing instrument, not a slot machine: the five-part formula — cinematography, subject, action, context, style & ambiance — plus an explicit soundstage direction gives it complete, testable instructions for picture and sound. Treat the 8 seconds as one unbroken take you are choreographing, not a story you are summarizing.', '[{"syntax":"Weighting (word:1.4)","supported":"no","notes":"No weight syntax; use descriptive language instead."},{"syntax":"Emphasis ((word))","supported":"no","notes":""},{"syntax":"BREAK keyword","supported":"no","notes":""},{"syntax":"[from:to:step] blending","supported":"no","notes":""},{"syntax":"Negative prompt","supported":"yes","notes":"negativePrompt parameter (Vertex AI). Describe what to exclude as a positive statement: \"a desolate landscape with no buildings or roads\" rather than \"no man-made structures\"."},{"syntax":"Special / trigger tokens","supported":"yes","notes":"Timestamp ranges ([00:00-00:02]), audio labels (SFX:, Ambient noise:), quotation marks for dialogue, colon-after-speaker for speech."},{"syntax":"Regional / masked prompting","supported":"no","notes":""}]', '[{"length":"Too short","effect":"The model guesses composition, motion, and audio — thin, generic 8-second clips."},{"length":"Ideal","effect":"1–3 well-structured sentences carrying all five formula elements plus audio direction. Google''s docs demonstrate that the \"more detail\" revision of the same prompt produces markedly better motion fidelity and scene quality."},{"length":"Too long","effect":"Text input is capped at 1,024 tokens on the Gemini API — content beyond that is cut off, so prioritize subject, action, camera, and audio cues."}]', '[Cinematography] + [Subject] + [Action] + [Context] + [Style & Ambiance]', '[{"include":"The five formula elements in every prompt","examples":"Cinematography, subject, action, context, style & ambiance"},{"include":"Camera movement vocabulary","examples":"dolly shot, tracking shot, crane shot, aerial view, slow pan, POV shot"},{"include":"Composition","examples":"wide shot, close-up, extreme close-up, low angle, two-shot"},{"include":"Lens & focus","examples":"shallow depth of field, wide-angle lens, soft focus, macro lens, deep focus"},{"include":"Full character description for consistency","examples":"Name + unchangeable features (build, hair, eyes, marks) + voice style — pasted unchanged into every scene''s prompt, with the same seed"},{"include":"Timestamped beats for multi-shot pacing","examples":"[00:00-00:02], [00:02-00:04]... with SFX per beat"},{"include":"Audio direction for every scene that needs it","examples":"Dialogue with delivery, synced SFX, defined ambience"},{"include":"Aspect-ratio-intent","examples":"16:9 widescreen / 9:16 portrait chosen for the platform and subject"}]', '[{"instead":"A detective finds a clue in a library, then drives across the city at night, and then confronts a suspect in a warehouse","write":"One focused moment per clip, or timestamped beats if the shots fit in 8 seconds"},{"instead":"negativePrompt: \"no man-made structures\" (bare negation)","write":"\"a desolate landscape with no buildings or roads\" — describe the exclusion positively"},{"instead":"A woman says: \"My name is Clara.\" (quotes risk rendered text)","write":"Vertex best practice: A woman says: My name is Clara. — colon, no quotes. (The 3.1 guide uses quotes for dialogue; verify output either way.)"},{"instead":"Prompting past the 1,024-token cap","write":"Prioritize subject, action, camera, audio; cut filler adjectives"},{"instead":"Vague quality terms (stunning, masterpiece, 8k quality)","write":"Descriptive visual language — what the camera sees, not superlatives"},{"instead":"Extending a clip whose voice isn''t in the last second","write":"Voice can''t be effectively extended unless present in the final ~1 s (24 frames) of the source clip"}]', '[{"param":"Duration","value":"4, 6, or 8 s (set per request; default 8 s)"},{"param":"Resolution","value":"720p / 1080p / 4K (1080p and 4K for 8 s only)"},{"param":"Aspect ratio","value":"16:9 or 9:16"},{"param":"Audio","value":"Native, enabled by default; the complete soundtrack is directed from the prompt"},{"param":"negativePrompt","value":"Free text describing exclusions, phrased positively (Vertex AI)"},{"param":"personGeneration","value":"Text-to-video: allow_all only; image-to-video, interpolation, and reference-image modes: allow_adult only (region restrictions apply)"},{"param":"seed","value":"Integer for consistency across scenes (Vertex AI)"},{"param":"Variants","value":"veo-3.1 (quality, default) / veo-3.1-fast (speed) / veo-3.1-lite (cheapest; no video extension) — same prompting language, different price/quality/speed"}]', '[{"title":"Prompting past the 1,024-token cap","detail":"— excess text is silently cut; prioritize subject, action, camera, audio."},{"title":"Asking for cuts in a plain prompt","detail":"— 3.1 generates one unbroken take; use timestamp prompting for multi-shot sequences."},{"title":"Re-describing the source image in image-to-video","detail":"— prompt for motion only; redundancy degrades results."},{"title":"Writing negative prompts as bare negations","detail":"— describe the exclusion positively (\"a landscape with no buildings\")."},{"title":"Forgetting the audio layer","detail":"— dialogue needs identified speakers with delivery; SFX need clarity and sync; ambience needs definition."},{"title":"Expecting the Lite variant to extend video","detail":"— extension is not available for Veo 3.1 Lite."}]', 'Target model: Veo 3.1 (video).
How to prompt it: Veo 3.1 is a directing instrument, not a slot machine: the five-part formula — cinematography, subject, action, context, style & ambiance — plus an explicit soundstage direction gives it complete, testable instructions for picture and sound. Treat the 8 seconds as one unbroken take you are choreographing, not a story you are summarizing.
Prompt length — too short: The model guesses composition, motion, and audio — thin, generic 8-second clips. | ideal: 1–3 well-structured sentences carrying all five formula elements plus audio direction. Google''s docs demonstrate that the "more detail" revision of the same prompt produces markedly better motion fidelity and scene quality. | too long: Text input is capped at 1,024 tokens on the Gemini API — content beyond that is cut off, so prioritize subject, action, camera, and audio cues.
Syntax — supported: Negative prompt, Special / trigger tokens | NOT supported: Weighting (word:1.4), Emphasis ((word)), BREAK keyword, [from:to:step] blending, Regional / masked prompting
Negative prompt: YES — negativePrompt parameter (Vertex AI). Describe what to exclude as a positive statement: "a desolate landscape with no buildings or roads" rather than "no man-made structures".
Include: The five formula elements in every prompt; Camera movement vocabulary; Composition; Lens & focus; Full character description for consistency; Timestamped beats for multi-shot pacing
Avoid: A detective finds a clue in a library, then drives across the city at night, and then confronts a suspect in a warehouse; negativePrompt: "no man-made structures" (bare negation); A woman says: "My name is Clara." (quotes risk rendered text); Prompting past the 1,024-token cap; Vague quality terms (stunning, masterpiece, 8k quality); Extending a clip whose voice isn''t in the last second
Recommended settings: Duration 4, 6, or 8 s (set per request; default 8 s); Resolution 720p / 1080p / 4K (1080p and 4K for 8 s only); Aspect ratio 16:9 or 9:16; Audio Native, enabled by default; the complete soundtrack is directed from the prompt; negativePrompt Free text describing exclusions, phrased positively (Vertex AI); personGeneration Text-to-video: allow_all only; image-to-video, interpolation, and reference-image modes: allow_adult only (region restrictions apply)
Common mistakes: Prompting past the 1,024-token cap; Asking for cuts in a plain prompt; Re-describing the source image in image-to-video; Writing negative prompts as bare negations; Forgetting the audio layer', 'Veo 3.1 (released October 2025; current on the Gemini API as of early 2026) is Google''s flagship video model: 8-second clips at up to 4K with natively generated, synchronized audio — dialogue with lip-sync, precisely timed sound effects, and ambient soundscapes, all directed from the prompt. It builds on Veo 3 with stronger prompt adherence and improved audiovisual quality when turning images into videos. Its distinctive creative controls are timestamp prompting (multi-shot sequences with timed segments in one generation), first-and-last-frame transitions, ingredients-to-video reference images (up to 3), and video extension. The Fast and Lite variants trade speed/cost for quality with the same prompting language.', '[{"url":"https://ai.google.dev/gemini-api/docs/veo","note":"https://ai.google.dev/gemini-api/docs/veo (prompt writing basics, dialogue/SFX examples, element-by-element examples, image-to-video/reference/first-last-frame/extension sections, model version table)"},{"url":"https://cloud.google.com/blog/products/ai-machine-learning/ultimate-prompting-guide-for-veo-3-1","note":"https://cloud.google.com/blog/products/ai-machine-learning/ultimate-prompting-guide-for-veo-3-1 (five-part formula, soundstage directing, timestamp prompting, first/last frame and ingredients-to-video workflows)"},{"url":"https://docs.cloud.google.com/vertex-ai/generative-ai/docs/video/best-practice","note":"https://docs.cloud.google.com/vertex-ai/generative-ai/docs/video/best-practice (recommended/not-recommended pairs, single-scene rule, quotation-mark guidance, image-to-video motion-only guidance, character/voice consistency)"},{"url":"https://blog.buildfastwithai.com/google-veo-3-1-ai-video-generator","note":"https://blog.buildfastwithai.com/google-veo-3-1-ai-video-generator (Veo 3.1 release context, resolution/audio/extension capabilities)"},{"url":"https://github.com/finpeakinc/frevana-skills/blob/HEAD/skills/veo-3.1/SKILL.md","note":"https://github.com/finpeakinc/frevana-skills/blob/HEAD/skills/veo-3.1/SKILL.md (Veo 3.1 parameter reference: resolutions, durations, reference images, negativePrompt, personGeneration)"}]', 'fd15d499cfb15e4ddfa71448e01ee1ca');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('video/wan/0', 'video', 'wan', 'WAN', '2.1', '2.1', 0, 'video', 'Prompt Guide: Wan 2.1', 'models/video/wan-2.1.md', 4, 'Wan''s UMT5-XXL encoder rewards full-sentence, cinematography-flavored natural language over keyword tag soup — describe the scene the way you would brief a cinematographer, and always name the motion explicitly, since video capacity is allocated to change-over-time.', '[{"syntax":"Weighting (word:1.4)","supported":"no","notes":"Community testing reports weighting syntax is unreliable with T5-based encoders; use wording order instead"},{"syntax":"Emphasis ((word))","supported":"no","notes":"No evidence it works; T5 reads natural language"},{"syntax":"BREAK keyword","supported":"no","notes":"No evidence"},{"syntax":"[from:to:step] blending","supported":"no","notes":"No evidence"},{"syntax":"Negative prompt","supported":"yes","notes":"Strongly recommended; a Chinese default negative prompt is the ecosystem standard (see below)"},{"syntax":"Special / trigger tokens","supported":"unknown","notes":"No documented trigger tokens for the base models"},{"syntax":"Regional / masked prompting","supported":"unknown","notes":"Not for base T2V/I2V (see Wan2.1-Fun variants under Prompt Modes)"}]', '[{"length":"Too short","effect":"Under-uses the encoder; the model fills gaps with generic motion and composition"},{"length":"Ideal","effect":"~100–150 words of coherent descriptive sentences; one documented rule of thumb: lead with subject and action since the model weighs the start of the prompt most heavily"},{"length":"Too long","effect":"UMT5-XXL truncates at 512 tokens; community measurement shows quality degrades around 320–350 tokens (~200–250 words) as it exits the cross-attention training distribution"}]', 'Subject + Scene + Motion', '[{"include":"Named motion","examples":"\"waves rolling in\", \"hair blowing in the wind\", \"camera slowly dollying right\""},{"include":"Subject-first ordering","examples":"Subject → Motion → Camera → Scene; the start of the prompt is weighted most"},{"include":"Camera terminology","examples":"\"tracking shot\", \"shallow depth of field\", \"slow pan left to right\", \"overhead crane shot\", \"handheld\""},{"include":"Lighting quality","examples":"\"golden hour\", \"volumetric fog\", \"soft morning light\", \"rim lighting\", \"neon city lights\""},{"include":"Materials/textures","examples":"\"weathered wood\", \"brushed steel\", \"rain-slicked asphalt\""},{"include":"One scene per clip","examples":"Single continuous shot; prompts describing scene cuts produce mush"},{"include":"Language choice","examples":"English and Chinese both work (bilingual training); keep each prompt in one language"}]', '[{"instead":"Keyword soup: \"cinematic, sunset, horse, desert, 4k, detailed\"","write":"A coherent sentence: \"A lone horse galloping across rippling sand dunes at sunset...\""},{"instead":"Static scene description with no motion","write":"Explicit change-over-time: \"waves rolling in, hair blowing in the wind\""},{"instead":"Vague quality words: \"nice lighting\", \"good quality\", \"professional\"","write":"Specifics: \"soft morning light filtering through venetian blinds\""},{"instead":"Multiple scenes / cuts in one prompt","write":"One scene per clip (5-second clips are shots, not films)"},{"instead":"Over-prompting style","write":"Trust the cinematic engine; excessive style keywords can conflict with its native look"}]', '[{"param":"Steps","value":"50 (official generate.py default); 20–30 acceptable for local drafts"},{"param":"Guidance / CFG Scale","value":"5.0 (official default)"},{"param":"Resolution","value":"832×480 (480p) or 1280×720 (720p); frame count follows the 4n+1 grid (81 frames typical)"},{"param":"Scheduler / Sampler","value":"UniPC (flow matching, order 2); flow shift 8–12 (5 for 720p, 12 for 480p per community recipes)"},{"param":"Dtype / Precision","value":"bfloat16"}]', '[{"title":"Prompting I2V like T2V","detail":"— re-describing the image''s content instead of describing motion and camera; the prompt should be Motion Description + Camera Movement."},{"title":"Leaving motion unnamed","detail":"— a static scene description gives the model nothing to animate; every prompt needs change-over-time (\"waves rolling in, hair blowing\")."},{"title":"Multiple scenes per prompt","detail":"— one clip is one shot; cuts and timelines produce mush (except specialist Enhanced/Timeline LoRAs that expect them)."},{"title":"Keyword soup","detail":"— the UMT5 encoder is instruction-grade; grammatically coherent sentences beat comma-separated tags."},{"title":"Overlong prompts","detail":"— quality degrades past ~320–350 tokens; lead with subject/action since the start is weighted most."}]', 'Target model: WAN 2.1 (video).
How to prompt it: Wan''s UMT5-XXL encoder rewards full-sentence, cinematography-flavored natural language over keyword tag soup — describe the scene the way you would brief a cinematographer, and always name the motion explicitly, since video capacity is allocated to change-over-time.
Prompt length — too short: Under-uses the encoder; the model fills gaps with generic motion and composition | ideal: ~100–150 words of coherent descriptive sentences; one documented rule of thumb: lead with subject and action since the model weighs the start of the prompt most heavily | too long: UMT5-XXL truncates at 512 tokens; community measurement shows quality degrades around 320–350 tokens (~200–250 words) as it exits the cross-attention training distribution
Syntax — supported: Negative prompt | NOT supported: Weighting (word:1.4), Emphasis ((word)), BREAK keyword, [from:to:step] blending
Negative prompt: YES — Strongly recommended; a Chinese default negative prompt is the ecosystem standard (see below)
Include: Named motion; Subject-first ordering; Camera terminology; Lighting quality; Materials/textures; One scene per clip
Avoid: Keyword soup: "cinematic, sunset, horse, desert, 4k, detailed"; Static scene description with no motion; Vague quality words: "nice lighting", "good quality", "professional"; Multiple scenes / cuts in one prompt; Over-prompting style
Recommended settings: Steps 50 (official generate.py default); 20–30 acceptable for local drafts; Guidance / CFG Scale 5.0 (official default); Resolution 832×480 (480p) or 1280×720 (720p); frame count follows the 4n+1 grid (81 frames typical); Scheduler / Sampler UniPC (flow matching, order 2); flow shift 8–12 (5 for 720p, 12 for 480p per community recipes); Dtype / Precision bfloat16
Common mistakes: Prompting I2V like T2V; Leaving motion unnamed; Multiple scenes per prompt; Keyword soup; Overlong prompts', 'Wan 2.1 is Alibaba''s second-generation open-weight video diffusion family, built on a DiT (diffusion transformer) with flow matching and a 3D causal VAE (Wan-VAE). It ships as text-to-video (1.3B and 14B) and image-to-video (14B) variants at 480p and 720p, and became the open-source baseline for cinematic short clips. Relative to the later Wan 2.2, it is a dense single-model architecture rather than a mixture-of-experts, and its I2V model is separate from T2V (2.2 adds the unified TI2V-5B model). Official guidance recommends enabling prompt extension (Qwen-based rewriting) to enrich detail before generation.', '[{"url":"https://huggingface.co/Wan-AI/Wan2.1-T2V-14B-Diffusers","note":"https://huggingface.co/Wan-AI/Wan2.1-T2V-14B-Diffusers (official model card: prompts, negative prompt, prompt extension, settings)"},{"url":"https://huggingface.co/jc-builds/Wan2.2-TI2V-5B-iOS","note":"https://huggingface.co/jc-builds/Wan2.2-TI2V-5B-iOS (community prompting guide: order matters, name the motion, Chinese negative prompt)"},{"url":"https://github.com/s-nagaev/chibi/blob/HEAD/skills/wan_prompting_skill.md","note":"https://github.com/s-nagaev/chibi/blob/HEAD/skills/wan_prompting_skill.md (Wan 2.1/2.2 prompting rules: 100–150 words, narrative structure)"},{"url":"https://medium.com/@mvpkenlin/mastering-ai-video-generation-with-alibaba-cloud-model-studio-a-practical-guide-to-wan-prompt-d7c8c22d1a0e","note":"https://medium.com/@mvpkenlin/mastering-ai-video-generation-with-alibaba-cloud-model-studio-a-practical-guide-to-wan-prompt-d7c8c22d1a0e (official Basic/Advanced/I2V prompt formulas)"},{"url":"https://github.com/fastflair/wan2gp/blob/HEAD/docs/PROMPTS.md","note":"https://github.com/fastflair/wan2gp/blob/HEAD/docs/PROMPTS.md (instruction-style prompting for edit models; timeline prompts for Enhanced models)"},{"url":"https://github.com/willhs/lossy/blob/HEAD/docs/tasks/0004-prompt-reformatting/task.md","note":"https://github.com/willhs/lossy/blob/HEAD/docs/tasks/0004-prompt-reformatting/task.md (512-token truncation, quality degradation ~320–350 tokens, weighting unreliable)"},{"url":"https://github.com/flyinggiraffe/vidax/blob/HEAD/docs/models/wan2_1.md","note":"https://github.com/flyinggiraffe/vidax/blob/HEAD/docs/models/wan2_1.md (I2V architecture, negative prompt default)"},{"url":"https://github.com/vllm-project/vllm-omni/blob/main/recipes/Wan-AI/Wan2.1-VACE.md","note":"https://github.com/vllm-project/vllm-omni/blob/main/recipes/Wan-AI/Wan2.1-VACE.md (VACE T2V/I2V/V2LF/FLF2V recipes: steps 30, guidance 5.0, 81 frames)"},{"url":"https://github.com/mreflow/ai-slop-detector/blob/HEAD/eval/WAN_GENERATION_RUNTIME.md","note":"https://github.com/mreflow/ai-slop-detector/blob/HEAD/eval/WAN_GENERATION_RUNTIME.md (UniPC scheduler, flow shift, max text length 512)"}]', 'c7c05eb6af6990295ee1f62b52b7620c');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('video/wan/1', 'video', 'wan', 'WAN', '2.2', '2.2', 1, 'video', 'Prompt Guide: Wan 2.2', 'models/video/wan-2.2.md', 5, 'Wan 2.2''s UMT5-XXL encoder rewards full-sentence, cinematography-flavored natural language over keyword tag soup — order matters: subject → motion → camera → scene, with the prompt''s start weighted most heavily. Name the motion explicitly, since video capacity is allocated to change-over-time.', '[{"syntax":"Weighting (word:1.4)","supported":"no","notes":"Same encoder family as 2.1: weighting syntax is unreliable with T5-based encoders; use prompt ordering instead"},{"syntax":"Emphasis ((word))","supported":"no","notes":"No evidence it works; T5 reads natural language"},{"syntax":"BREAK keyword","supported":"no","notes":"No evidence"},{"syntax":"[from:to:step] blending","supported":"no","notes":"No evidence"},{"syntax":"Negative prompt","supported":"yes","notes":"The Chinese default negative prompt is the ecosystem standard (see below)"},{"syntax":"Special / trigger tokens","supported":"unknown","notes":"No documented trigger tokens for the base models"},{"syntax":"Regional / masked prompting","supported":"unknown","notes":"Not for base T2V/I2V (see Fun variants under Prompt Modes)"},{"syntax":"Timeline slash commands","supported":"yes","notes":"The \"Enhanced\"/wan2gp class of Wan 2.2 builds accepts segmented prompts with commands like [/duration=30%,/overlap=9] and a second-by-second (at N seconds: ...) format"}]', '[{"length":"Too short","effect":"Under-uses the encoder; the model fills gaps with generic motion and composition"},{"length":"Ideal","effect":"One community guide for Wan 2.2 cites 80–120 words as optimal; another Wan 2.2 guide uses ~100–150 words of coherent descriptive sentences. Rule of thumb: lead with subject and action since the model weighs the start of the prompt most heavily"},{"length":"Too long","effect":"UMT5-XXL truncates at 512 tokens (per official config logs). The Wan-family rule carries over: quality degrades past ~320–350 tokens (~200–250 words) as the prompt exits the cross-attention training distribution"}]', 'Subject + Scene + Motion', '[{"include":"Subject → motion → camera → scene ordering","examples":"The start of the prompt is weighted most heavily"},{"include":"Named motion with concrete verbs","examples":"\"waves crash\", \"the corgi paddles\", \"she spins slowly\""},{"include":"Explicit camera direction","examples":"\"tracking shot\", \"shallow depth of field\", \"slow pan left\", \"aerial view\", \"push in\""},{"include":"Light and mood","examples":"\"golden hour\", \"volumetric fog\", \"rim lighting\", \"neon glow\", \"heavy rain\""},{"include":"One scene per clip","examples":"A 2–5 second clip is a shot, not a film; scene-cut prompts produce mush"},{"include":"Materials/textures","examples":"\"weathered wood\", \"brushed steel\", \"rain-slicked asphalt\""},{"include":"Language choice","examples":"English and Chinese both work (bilingual training); keep each prompt in one language"},{"include":"Prompt extension","examples":"Officially recommended: --use_prompt_extend enriches short prompts via Qwen rewriting before generation"}]', '[{"instead":"Keyword soup: \"cinematic, sunset, horse, desert, 4k, detailed\"","write":"A coherent sentence: \"A lone horse galloping across rippling sand dunes at sunset...\""},{"instead":"Static scene description with no motion","write":"Explicit change-over-time: \"waves rolling in, hair blowing in the wind\""},{"instead":"Vague quality words: \"nice lighting\", \"good quality\", \"professional\"","write":"Specifics: \"soft morning light filtering through venetian blinds\""},{"instead":"Multiple scenes / cuts in one prompt","write":"One scene per clip — except Enhanced/wan2gp builds that explicitly take timeline formats"},{"instead":"Over-prompting style","write":"Trust the cinematic engine; the model is trained with detailed aesthetic labels, so excessive style keywords can conflict"}]', '[{"param":"Steps","value":"40 (official generate.py default; 20–30 acceptable for local drafts)"},{"param":"Guidance / CFG Scale","value":"Default sample_guide_scale=(3.5, 3.5) in generate.py. Documented community recipes vary by implementation: Diffusers guidance_scale 3.5–4.0 for the A14B MoE models (with a separate guidance_scale_2 for the second expert in the Lightning Diffusers example: 4.0 / 3.0); TI2V-5B Diffusers example uses 5.0"},{"param":"MoE boundary","value":"Default boundary 0.9 in official config (SNR split point between the high-noise and low-noise experts); some community recipes use a boundary ratio of 0.875 with dual guidance values (e.g. 5.0 low-noise / 6.0 high-noise)"},{"param":"Resolution","value":"1280×720 (720p) or 832×480 (480p) for T2V/I2V-A14B; TI2V-5B does 720p"},{"param":"Frame count / FPS","value":"81 frames at 16fps for the A14B models; 121 frames at 24fps for TI2V-5B"},{"param":"Scheduler / Sampler","value":"UniPC (flow matching); sample shift 5.0 in official configs (community 720p recipes use 5, 480p use 12 — generalization from Wan family recipes)"},{"param":"Dtype / Precision","value":"bfloat16"}]', '[{"title":"Prompting I2V like T2V","detail":"— re-describing the image''s content instead of describing motion and camera; the prompt should be Motion Description + Camera Movement."},{"title":"Leaving motion unnamed","detail":"— a static scene description gives the model nothing to animate; every prompt needs change-over-time (\"waves rolling in, hair blowing\")."},{"title":"Multiple scenes per prompt","detail":"— one clip is one shot; cuts produce mush (except Enhanced/Lightning builds that expect timeline formats)."},{"title":"Keyword soup","detail":"— the UMT5 encoder is instruction-grade; grammatically coherent sentences beat comma-separated tags."},{"title":"Using the timeline format on the base A14B models","detail":"— (at N seconds: ...) structure is for Enhanced/Lightning builds; the base T2V/I2V models expect one continuous scene description."},{"title":"Skipping the negative prompt","detail":"— the Chinese default is the ecosystem standard for suppressing video-model failure modes (above cfg 1.0, where the negative branch is active)."},{"title":"Ignoring prompt extension","detail":"— short prompts are officially recommended for Qwen-based extension; writing the extension yourself is wasted effort the pipeline does better."}]', 'Target model: WAN 2.2 (video).
How to prompt it: Wan 2.2''s UMT5-XXL encoder rewards full-sentence, cinematography-flavored natural language over keyword tag soup — order matters: subject → motion → camera → scene, with the prompt''s start weighted most heavily. Name the motion explicitly, since video capacity is allocated to change-over-time.
Prompt length — too short: Under-uses the encoder; the model fills gaps with generic motion and composition | ideal: One community guide for Wan 2.2 cites 80–120 words as optimal; another Wan 2.2 guide uses ~100–150 words of coherent descriptive sentences. Rule of thumb: lead with subject and action since the model weighs the start of the prompt most heavily | too long: UMT5-XXL truncates at 512 tokens (per official config logs). The Wan-family rule carries over: quality degrades past ~320–350 tokens (~200–250 words) as the prompt exits the cross-attention training distribution
Syntax — supported: Negative prompt, Timeline slash commands | NOT supported: Weighting (word:1.4), Emphasis ((word)), BREAK keyword, [from:to:step] blending
Negative prompt: YES — The Chinese default negative prompt is the ecosystem standard (see below)
Include: Subject → motion → camera → scene ordering; Named motion with concrete verbs; Explicit camera direction; Light and mood; One scene per clip; Materials/textures
Avoid: Keyword soup: "cinematic, sunset, horse, desert, 4k, detailed"; Static scene description with no motion; Vague quality words: "nice lighting", "good quality", "professional"; Multiple scenes / cuts in one prompt; Over-prompting style
Recommended settings: Steps 40 (official generate.py default; 20–30 acceptable for local drafts); Guidance / CFG Scale Default sample_guide_scale=(3.5, 3.5) in generate.py. Documented community recipes vary by implementation: Diffusers guidance_scale 3.5–4.0 for the A14B MoE models (with a separate guidance_scale_2 for the second expert in the Lightning Diffusers example: 4.0 / 3.0); TI2V-5B Diffusers example uses 5.0; MoE boundary Default boundary 0.9 in official config (SNR split point between the high-noise and low-noise experts); some community recipes use a boundary ratio of 0.875 with dual guidance values (e.g. 5.0 low-noise / 6.0 high-noise); Resolution 1280×720 (720p) or 832×480 (480p) for T2V/I2V-A14B; TI2V-5B does 720p; Frame count / FPS 81 frames at 16fps for the A14B models; 121 frames at 24fps for TI2V-5B; Scheduler / Sampler UniPC (flow matching); sample shift 5.0 in official configs (community 720p recipes use 5, 480p use 12 — generalization from Wan family recipes)
Common mistakes: Prompting I2V like T2V; Leaving motion unnamed; Multiple scenes per prompt; Keyword soup; Using the timeline format on the base A14B models', 'Wan 2.2 is Alibaba''s third-generation open-weight video diffusion family and the first to use a Mixture-of-Experts (MoE) architecture in video generation. The flagship A14B models (T2V and I2V) split the denoising process between a high-noise expert (early steps, overall layout/composition) and a low-noise expert (later steps, detail refinement) — ~14B parameters per expert, 27B total, but only 14B active per step, so inference cost stays near Wan 2.1''s. A separate TI2V-5B dense model unifies text-to-video and image-to-video in one checkpoint and renders 720p at 24fps thanks to a high-compression Wan2.2-VAE. The lineup also includes S2V-14B (audio-driven speech-to-video from a reference image + audio) and Animate-14B (character animation/replacement). Relative to Wan 2.1: richer cinematic training labels (lighting, composition, contrast, color tone), stronger complex motion, and official prompt extension via Qwen (qwen-plus for T2V, qwen-vl-max for I2V).', '[{"url":"https://github.com/Wan-Video/Wan2.2","note":"https://github.com/Wan-Video/Wan2.2 (official repo: MoE architecture, model lineup, prompt extension, generate.py defaults)"},{"url":"https://huggingface.co/Wan-AI/Wan2.2-T2V-A14B-Diffusers","note":"https://huggingface.co/Wan-AI/Wan2.2-T2V-A14B-Diffusers (official T2V model card: examples, negative prompt, prompt extension, guidance_scale)"},{"url":"https://huggingface.co/Wan-AI/Wan2.2-I2V-A14B-Diffusers","note":"https://huggingface.co/Wan-AI/Wan2.2-I2V-A14B-Diffusers (official I2V model card: examples, settings)"},{"url":"https://huggingface.co/Wan-AI/Wan2.2-TI2V-5B","note":"https://huggingface.co/Wan-AI/Wan2.2-TI2V-5B (official TI2V-5B card: MoE design, VAE compression, 720P@24fps, unified T2V+I2V)"},{"url":"https://huggingface.co/Wan-AI/Wan2.2-TI2V-5B-Diffusers","note":"https://huggingface.co/Wan-AI/Wan2.2-TI2V-5B-Diffusers (Diffusers example: 121 frames, steps 50, guidance 5.0, 704×1280, fps=24)"},{"url":"https://huggingface.co/Wan-AI/Wan2.2-T2V-A14B-Diffusers/discussions/8","note":"https://huggingface.co/Wan-AI/Wan2.2-T2V-A14B-Diffusers/discussions/8 (official config log: sample_guide_scale=(3.5,3.5), boundary 0.9, sample_shift 5.0, sample_fps 16, text_len 512)"},{"url":"https://huggingface.co/magespace/Wan2.2-I2V-A14B-Lightning-Diffusers","note":"https://huggingface.co/magespace/Wan2.2-I2V-A14B-Lightning-Diffusers (Lightning example: guidance_scale=4.0, guidance_scale_2=3.0, steps 40)"},{"url":"https://huggingface.co/jc-builds/Wan2.2-TI2V-5B-iOS","note":"https://huggingface.co/jc-builds/Wan2.2-TI2V-5B-iOS (prompting guide: subject→motion→camera→scene, weigh the start, name the motion, one scene per clip, Chinese negative prompt)"},{"url":"https://huggingface.co/jc-builds/Wan2.2-TI2V-5B-Turbo-iOS","note":"https://huggingface.co/jc-builds/Wan2.2-TI2V-5B-Turbo-iOS (prompting guide: ordering, concrete verbs, camera direction, cfg 1.0 note, bilingual training)"},{"url":"https://huggingface.co/geceff/Wan2.2-Custom-Models-GGUF","note":"https://huggingface.co/geceff/Wan2.2-Custom-Models-GGUF (community quant notes: high-noise expert for creative motion/camera, low-noise expert for fidelity and prompt adherence; NSFW finetune entry)"},{"url":"https://github.com/vllm-project/vllm-omni/blob/HEAD/examples/offline_inference/image_to_video/README.md","note":"https://github.com/vllm-project/vllm-omni/blob/HEAD/examples/offline_inference/image_to_video/README.md (MoE I2V recipe: guidance-scale 5.0, guidance-scale-high 6.0, boundary-ratio 0.875, flow-shift 5/12)"},{"url":"https://github.com/deepbeepmeep/wan2gp/blob/HEAD/docs/PROMPTS.md","note":"https://github.com/deepbeepmeep/wan2gp/blob/HEAD/docs/PROMPTS.md (Enhanced timeline format (at N seconds: ...), [/duration=30%,/overlap=9], Enhanced Lightning v2 default prompt)"},{"url":"https://github.com/xujinghao221/construction-video-prompt-skill","note":"https://github.com/xujinghao221/construction-video-prompt-skill (FLF2V/InP prompt semantics: first frame = start condition, last frame = target, prompt = allowed action between)"},{"url":"https://civitai.com/articles/22845/wan22-studio-prompt-generator-and-guide","note":"https://civitai.com/articles/22845/wan22-studio-prompt-generator-and-guide (Wan 2.2 community guide: 80–120 words optimal, Subject + Scene + Motion + Camera + Aesthetics, I2V = Motion + Camera)"},{"url":"https://arxiv.org/pdf/2508.18621v1","note":"https://arxiv.org/pdf/2508.18621v1 (Wan-S2V paper: reference image + audio + content-describing prompt, wav2vec audio conditioning)"},{"url":"https://www.youtube.com/watch?v=laAj4N-Es4w","note":"https://www.youtube.com/watch?v=laAj4N-Es4w (Dasiwa Wan 2.2 uncensored I2V workflows: uncensored text encoders, Qwen3-VL time-separated prompting, vs \"Smooth Mix\"/\"Remix\")"},{"url":"https://www.youtube.com/watch?v=uFIoiIrRmP0","note":"https://www.youtube.com/watch?v=uFIoiIrRmP0 (ComfyUI update notes: Wan 2.2 FLF2V, Fun Inpaint, Fun Control [Canny/Depth/OpenPose/MLSD], Fun Camera Control, S2V)"}]', 'dd44f827006fc5edf806d2ac3885796e');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('video/wan/2', 'video', 'wan', 'WAN', '2.5', '2.5', 2, 'video', 'Prompt Guide: Wan 2.5', 'models/video/wan-2.5.md', 4, 'Wan 2.5 keeps the family rule — natural-language, cinematography-flavored prompts ordered subject-first — and adds an audio slot: describe what is heard (voice tone, sound effects, music) as plainly as what is seen. Keep each prompt in a single language (Chinese or English) for best compliance.', '[{"syntax":"Weighting (word:1.4)","supported":"unknown","notes":"No documented support; assume unreliable as with earlier Wan encoders"},{"syntax":"Emphasis ((word))","supported":"unknown","notes":"No evidence"},{"syntax":"BREAK keyword","supported":"unknown","notes":"No evidence"},{"syntax":"[from:to:step] blending","supported":"unknown","notes":"No evidence"},{"syntax":"Negative prompt","supported":"yes","notes":"negative_prompt parameter exposed on API endpoints"},{"syntax":"Special / trigger tokens","supported":"unknown","notes":"No documented trigger tokens"},{"syntax":"Regional / masked prompting","supported":"unknown","notes":"Not documented for 2.5"}]', '[{"length":"Too short","effect":"Model fills gaps itself; less control over pacing, sound, and camera"},{"length":"Ideal","effect":"Start with a concise scene sentence, then add 2–3 temporal beats; keep camera motion explicit and sparse (slow push in, track left, hold)"},{"length":"Too long","effect":"Max token count not publicly specified — leave blank"}]', 'Subject + Scene + Motion + Sound Description', '[{"include":"Concise scene sentence first","examples":"\"A robot chef stirs a glowing soup in a futuristic pantry\""},{"include":"2–3 temporal beats","examples":"Sequential actions within the shot"},{"include":"Explicit but sparse camera motion","examples":"slow push in, track left, hold — strong consistency from minimal moves"},{"include":"Sound slot components","examples":"Voice: tone, emotion, accent, pacing; SFX: object + action + ambience; music: genre, mood"},{"include":"Emotional anchors for faces","examples":"\"focus on soft eyes\", \"small confident smile\", \"eyes track the door\""},{"include":"Atmospheric cues as motion direction","examples":"\"mist drifting\", \"light shifting through trees\", \"leaves falling, water reflecting\""},{"include":"Single language per prompt","examples":"Chinese or English — the model was trained on a bilingual Chinese-English corpus with separate semantic pathways; mixing languages degrades compliance"}]', '[{"instead":"Tag soup: \"rainy city street, jazz soundtrack, cinematic\"","write":"Sentence + audio: \"Rain falls on an empty neon-lit city street at night... Soft jazz piano plays in the background...\""},{"instead":"Mixing Chinese and English in one prompt","write":"One language per prompt"},{"instead":"Conflicting camera movement in I2V","write":"Motion that inherits the source composition; explicit but sparse moves"},{"instead":"Overstuffing sound and visual demands into one short prompt","write":"Prioritize: scene sentence first, then 2–3 temporal beats, then sound"},{"instead":"Silence where audio should be (when generating with audio)","write":"Always fill the sound slot — voice, SFX, music — since 2.5 syncs them"}]', '[{"param":"Steps","value":"(not publicly specified — blank)"},{"param":"Guidance / CFG Scale","value":"(not publicly specified — blank)"},{"param":"Resolution","value":"480p / 720p / 1080p"},{"param":"Scheduler / Sampler","value":"(not publicly specified — blank)"},{"param":"Dtype / Precision","value":"(not publicly specified — blank)"},{"param":"Duration","value":"5s or 10s"}]', '[{"title":"Leaving the sound slot empty","detail":"— 2.5''s headline feature is synced audio; a prompt with no voice/SFX/music description wastes it."},{"title":"Mixing languages in one prompt","detail":"— keep Chinese or English throughout for best compliance."},{"title":"Prompting I2V like T2V","detail":"— re-describing the image instead of giving motion, camera, and audio direction."},{"title":"Vague audio tags","detail":"(\"jazz soundtrack\", \"cooking sounds\") — specify voice tone/pace, SFX object + action + ambience, music genre + mood."},{"title":"Overcomplicated single prompts","detail":"— scene sentence first, then 2–3 temporal beats; don''t cram multi-scene narratives into one clip."}]', 'Target model: WAN 2.5 (video).
How to prompt it: Wan 2.5 keeps the family rule — natural-language, cinematography-flavored prompts ordered subject-first — and adds an audio slot: describe what is heard (voice tone, sound effects, music) as plainly as what is seen. Keep each prompt in a single language (Chinese or English) for best compliance.
Prompt length — too short: Model fills gaps itself; less control over pacing, sound, and camera | ideal: Start with a concise scene sentence, then add 2–3 temporal beats; keep camera motion explicit and sparse (slow push in, track left, hold) | too long: Max token count not publicly specified — leave blank
Syntax — supported: Negative prompt
Negative prompt: YES — negative_prompt parameter exposed on API endpoints
Include: Concise scene sentence first; 2–3 temporal beats; Explicit but sparse camera motion; Sound slot components; Emotional anchors for faces; Atmospheric cues as motion direction
Avoid: Tag soup: "rainy city street, jazz soundtrack, cinematic"; Mixing Chinese and English in one prompt; Conflicting camera movement in I2V; Overstuffing sound and visual demands into one short prompt; Silence where audio should be (when generating with audio)
Recommended settings: Steps (not publicly specified — blank); Guidance / CFG Scale (not publicly specified — blank); Resolution 480p / 720p / 1080p; Scheduler / Sampler (not publicly specified — blank); Dtype / Precision (not publicly specified — blank); Duration 5s or 10s
Common mistakes: Leaving the sound slot empty; Mixing languages in one prompt; Prompting I2V like T2V; Vague audio tags; Overcomplicated single prompts', 'Note: this version is verified to exist as of October 2026. Wan 2.5 was unveiled as Wan 2.5-Preview in September 2025 on Alibaba Cloud''s Model Studio and released as a text/image-to-video model with native audio generation — voice/dialogue, sound effects, and background music synthesized in the same pass, synced to the visuals. It produces up to 10-second 1080p clips (720p also available, 5s or 10s durations), is offered on DashScope/fal/WaveSpeed, and is reported open-weight (Apache 2.0) by third parties. Prompting adds a fourth slot to the Wan formula: Subject + Scene + Motion + Sound Description. The core visual-prompting language (full sentences, cinematographic vocabulary, subject-first ordering) is the same family as Wan 2.1/2.2.', '[{"url":"https://wavespeed.ai/models/alibaba/wan-2.5/image-to-video","note":"https://wavespeed.ai/models/alibaba/wan-2.5/image-to-video"},{"url":"https://bluelightningtv.com/2025/09/26/alibaba-unveils-wan-2-5-preview-native-multimodality-for-synchronized-text-image-video-and-audio/","note":"https://bluelightningtv.com/2025/09/26/alibaba-unveils-wan-2-5-preview-native-multimodality-for-synchronized-text-image-video-and-audio/ (Wan 2.5-Preview launch: 10s 1080p, native audio, director-style control)"},{"url":"https://medium.com/@mvpkenlin/mastering-ai-video-generation-with-alibaba-cloud-model-studio-a-practical-guide-to-wan-prompt-d7c8c22d1a0e","note":"https://medium.com/@mvpkenlin/mastering-ai-video-generation-with-alibaba-cloud-model-studio-a-practical-guide-to-wan-prompt-d7c8c22d1a0e (Subject + Scene + Motion + Sound Description formula; documented sound example)"},{"url":"https://web.archive.org/web/20250924034839/https://wavespeed.ai/models/alibaba/wan-2.5/image-to-video","note":"https://web.archive.org/web/20250924034839/https://wavespeed.ai/models/alibaba/wan-2.5/image-to-video (WaveSpeed Wan 2.5 I2V docs: resolutions, prompt, negative_prompt, enable_prompt_expansion)"},{"url":"https://mixhubai.com/blog/what-is-wan-2-5-alibabas-game-changing-audio-visual-synced-ai-video-model-explained-","note":"https://mixhubai.com/blog/what-is-wan-2-5-alibabas-game-changing-audio-visual-synced-ai-video-model-explained- (prompt formula; Subject + Scene + Motion + Sound Description)"},{"url":"https://github.com/buildoak/fieldwork-skills/blob/HEAD/skills/video-gen/references/model-wan.md","note":"https://github.com/buildoak/fieldwork-skills/blob/HEAD/skills/video-gen/references/model-wan.md (Wan 2.5/2.6: T2V/I2V modes, native audio flag, one-language rule, sparse camera motion, emotional anchors, pricing)"},{"url":"https://pixeldojo.ai/guides/wan-2-5-prompting-guide","note":"https://pixeldojo.ai/guides/wan-2-5-prompting-guide (Wan 2.5 I2V flash guide: same prompt language as the family, atmospheric cues as motion)"},{"url":"https://veemo.ai/wan-2.5","note":"https://veemo.ai/wan-2.5 (FAQ: open-source Apache 2.0, bilingual training, cost-effectiveness, Wan 2.6 context confirming 2.5 as released)"}]', 'a7070047cd85ea63d2034194954e8fe4');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('video/wan/3', 'video', 'wan', 'WAN', '2.6', '2.6', 3, 'video', 'Prompt Guide: Wan 2.6', 'models/video/wan-2.6.md', 5, 'Each of the three modes wants a differently shaped prompt — getting the shape wrong is the most common reason a clip comes back generic. Text-to-video takes a global style line followed by timing-bracketed shots; image-to-video should describe only what changes over time (the image already supplies the look); reference-to-video tags subjects as @Video1 / @Video2 / @Video3.', '[{"syntax":"Weighting (word:1.4)","supported":"unknown","notes":"No documented support; use word order and repetition of key details across shots instead"},{"syntax":"Emphasis ((word))","supported":"unknown","notes":""},{"syntax":"BREAK keyword","supported":"unknown","notes":""},{"syntax":"[from:to:step] blending","supported":"unknown","notes":""},{"syntax":"Negative prompt","supported":"yes","notes":"negative_prompt parameter, max 500 characters; prioritize visible artifacts"},{"syntax":"Special / trigger tokens","supported":"yes","notes":"@Video1, @Video2, @Video3 tag reference clips in R2V mode"},{"syntax":"Regional / masked prompting","supported":"unknown","notes":""}]', '[{"length":"Too short","effect":"A vague prompt gets rewritten by prompt expansion anyway — you keep less control, and the clip tends toward generic \"AI video\" looks"},{"length":"Ideal","effect":"A global style line plus 2–4 timing-bracketed shots, comfortably inside the 800-character budget"},{"length":"Too long","effect":"Main prompt is capped at 800 characters; excess is cut, so spend words on camera action and motion first"}]', '[Global style line] + [Shot 1 [start-end] camera action + scene elements] + [Shot 2 ...]', '[{"include":"Timing brackets per shot","examples":"Shot 1 [0-3s], Shot 2 [3-7s]"},{"include":"Explicit camera movement","examples":"camera tracks forward, slow push-in, gentle orbit, pull back to reveal"},{"include":"Lighting changes over time","examples":"light changes from morning to golden hour, neon flickers on"},{"include":"Environmental animation","examples":"clouds drift, rain ripples in puddles, dust floats in light beams, fabric moves in breeze"},{"include":"Dialogue speaker cues (with audio input)","examples":"she says \"...\", a deep narrator voice — guides lip-sync when supplying audio"},{"include":"Quality descriptors in the style line","examples":"photoreal, cinematic, 4K, film grain"},{"include":"Motion intensity wording","examples":"Minimal: subtle camera drift, gentle movement · Moderate: smooth camera track, flowing motion · Dramatic: dynamic sweeping motion, rapid camera movement"}]', '[{"instead":"Re-describing the input image in I2V (a mountain with snow and a lake...)","write":"Describe only the change: gentle camera push toward the peak as clouds drift overhead"},{"instead":"Stacking several camera moves in one shot (orbit while zooming and panning)","write":"One camera action per shot: slow push-in"},{"instead":"Unrelated shots with new characters each time","write":"Repeat the same characters, locations, and objects across every shot"},{"instead":"Framing that ignores the aspect ratio","write":"Wide establishing shots and horizontal movement for 16:9; tighter framing and vertical composition for 9:16; centered subjects for 1:1"},{"instead":"A one-line vague prompt relying on expansion","write":"A style line plus shot-by-shot beats you control"}]', '[{"param":"Steps","value":""},{"param":"Guidance / CFG Scale","value":""},{"param":"Resolution","value":"720p or 1080p (T2V); 480p / 720p / 1080p (I2V)"},{"param":"Scheduler / Sampler","value":""},{"param":"Dtype / Precision","value":""}]', '[]', 'Target model: WAN 2.6 (video).
How to prompt it: Each of the three modes wants a differently shaped prompt — getting the shape wrong is the most common reason a clip comes back generic. Text-to-video takes a global style line followed by timing-bracketed shots; image-to-video should describe only what changes over time (the image already supplies the look); reference-to-video tags subjects as @Video1 / @Video2 / @Video3.
Prompt length — too short: A vague prompt gets rewritten by prompt expansion anyway — you keep less control, and the clip tends toward generic "AI video" looks | ideal: A global style line plus 2–4 timing-bracketed shots, comfortably inside the 800-character budget | too long: Main prompt is capped at 800 characters; excess is cut, so spend words on camera action and motion first
Syntax — supported: Negative prompt, Special / trigger tokens
Negative prompt: YES — negative_prompt parameter, max 500 characters; prioritize visible artifacts
Include: Timing brackets per shot; Explicit camera movement; Lighting changes over time; Environmental animation; Dialogue speaker cues (with audio input); Quality descriptors in the style line
Avoid: Re-describing the input image in I2V (a mountain with snow and a lake...); Stacking several camera moves in one shot (orbit while zooming and panning); Unrelated shots with new characters each time; Framing that ignores the aspect ratio; A one-line vague prompt relying on expansion
Recommended settings: Steps ; Guidance / CFG Scale ; Resolution 720p or 1080p (T2V); 480p / 720p / 1080p (I2V); Scheduler / Sampler ; Dtype / Precision ', 'Wan 2.6 is the December 2025 generation of Alibaba''s Wan video family, released as a commercial, API-served model. It ships three video modes — text-to-video, image-to-video, and the series'' first reference-to-video model (R2V, which carries a subject''s appearance and voice from a reference clip) — plus a fast i2v-flash variant for drafts. Its headline additions over the previous generation are intelligent multi-shot storytelling (several timed shots inside one generation), audio-guided generation (supply an audio file to drive the clip, including lip-sync for dialogue), and longer clips up to 15 seconds. A faster "Prime" tier exists on some providers.', '[{"url":"https://fal.ai/learn/devs/wan-2-6-prompt-guide-mastering-all-three-generation-modes","note":"https://fal.ai/learn/devs/wan-2-6-prompt-guide-mastering-all-three-generation-modes (fal Wan 2.6 prompt guide)"},{"url":"https://github.com/brndngln/nodetool/blob/HEAD/packages/system-skills/wan-2-6-prompting/SKILL.md","note":"https://github.com/brndngln/nodetool/blob/HEAD/packages/system-skills/wan-2-6-prompting/SKILL.md (Wan 2.6 prompting skill, adapted from fal''s guide)"},{"url":"https://wan2.video/wan2.7","note":"https://wan2.video/wan2.7 (Wan 2.6 vs 2.7 capability comparison)"},{"url":"https://mid-east.info/alibaba-unveils-wan2-6-series-enabling-everyone-to-star-in-videos/","note":"https://mid-east.info/alibaba-unveils-wan2-6-series-enabling-everyone-to-star-in-videos/ (Wan 2.6 launch details)"},{"url":"https://runware.ai/docs/models/alibaba-wan2-6-flash.md","note":"https://runware.ai/docs/models/alibaba-wan2-6-flash.md (Wan 2.6 Flash prompting examples)"},{"url":"https://github.com/seventailcat/skills/blob/HEAD/skills/wan-video/SKILL.md","note":"https://github.com/seventailcat/skills/blob/HEAD/skills/wan-video/SKILL.md (Wan 2.6 model IDs and workflows)"}]', '7801aa70c15de39a11a21372f4f429f8');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('video/wan/4', 'video', 'wan', 'WAN', '2.7', '2.7', 4, 'video', 'Prompt Guide: Wan 2.7', 'models/video/wan-2.7.md', 5, 'The prompt is a compact storyboard: Wan 2.7 interprets shot changes written directly into the prompt with time ranges, replacing the separate shot-control parameter that 2.6 used. Write natural language like a director — subject, action, camera, lighting, style — and keep the same identity descriptors repeated across every shot so characters hold together.', '[{"syntax":"Weighting (word:1.4)","supported":"unknown","notes":"No documented support; use word order and repeated identity descriptors instead"},{"syntax":"Emphasis ((word))","supported":"unknown","notes":""},{"syntax":"BREAK keyword","supported":"unknown","notes":""},{"syntax":"[from:to:step] blending","supported":"unknown","notes":""},{"syntax":"Negative prompt","supported":"yes","notes":"Max 500 characters; use for failure modes (deformed hands, flicker, unstable face, watermark), not to re-describe the scene"},{"syntax":"Special / trigger tokens","supported":"changed","notes":"2.6''s @Video1 tags replaced by a typed media array; name references as Image 1, Image 2, Video 1 in per-type order (per official Alibaba Cloud docs)"},{"syntax":"Regional / masked prompting","supported":"unknown","notes":""}]', '[{"length":"Too short","effect":"Thin prompts lean on prompt_extend (on by default), which rewrites them — convenient for ideas, risky once you are art directing; disable it when wording must be honored exactly"},{"length":"Ideal","effect":"One rich paragraph for a single shot, or a timed shot plan (Shot 1 [0–2s]...) for multi-shot sequences; third-party API docs report a 5,000-character prompt limit for native T2V"},{"length":"Too long","effect":"Extremely long prompts dilute the must-have beats; keep one dominant action per shot and put critical details early"}]', '[Subject + action] + [environment] + [camera movement] + [lighting] + [visual style] + [timeline] + [audio direction] + [constraints]', '[{"include":"Timed shot plan for multi-shot","examples":"Shot 1 [0–2s]: ... Shot 2 [2–4s]: ... Shot 3 [4–5s]: ..."},{"include":"One explicit camera behavior per shot","examples":"locked camera, slow push-in, pullback, pan, tilt, tracking shot, gentle orbit, FPV drone dive, 360-degree orbital"},{"include":"Repeated identity anchors","examples":"Same coat, face, and lighting palette restated in every shot; per-subject reference_voice in R2V"},{"include":"Dialogue as quoted speech with speaker","examples":"\"Why is no one coming to play with me?\" — lip-sync follows automatically"},{"include":"Ordered action beats (i2v)","examples":"she laughs, glances away, then looks back to camera — one progression, not competing actions"},{"include":"Continuity guard only where needed (i2v)","examples":"Keep her face unchanged, no new objects, keep the background stable"},{"include":"Lighting consistency cues","examples":"maintain perfect lighting consistency, context-aware lighting"}]', '[{"instead":"2.6-style @Video1 tags in 2.7 prompts","write":"Image 1, Video 1 — the typed media array naming"},{"instead":"Re-describing the whole input image in i2v","write":"Motion, timing, and camera direction only"},{"instead":"Several simultaneous camera moves (orbit while zooming and panning)","write":"One camera behavior per shot"},{"instead":"Cramming 10–15 seconds with unrelated actions","write":"One continuous shot per generation; longer clips extend the same action"},{"instead":"Long choreographed multi-scene sequences","write":"One dominant verb per clip; rapid scene changes are unreliable"},{"instead":"Relying on the prompt to fix a bad source image","write":"Choose a clean frame first — a motion prompt cannot repair anatomy, pose, or missing detail"}]', '[{"param":"Steps","value":""},{"param":"Guidance / CFG Scale","value":""},{"param":"Resolution","value":"720P or 1080P"},{"param":"Scheduler / Sampler","value":""},{"param":"Dtype / Precision","value":""}]', '[]', 'Target model: WAN 2.7 (video).
How to prompt it: The prompt is a compact storyboard: Wan 2.7 interprets shot changes written directly into the prompt with time ranges, replacing the separate shot-control parameter that 2.6 used. Write natural language like a director — subject, action, camera, lighting, style — and keep the same identity descriptors repeated across every shot so characters hold together.
Prompt length — too short: Thin prompts lean on prompt_extend (on by default), which rewrites them — convenient for ideas, risky once you are art directing; disable it when wording must be honored exactly | ideal: One rich paragraph for a single shot, or a timed shot plan (Shot 1 [0–2s]...) for multi-shot sequences; third-party API docs report a 5,000-character prompt limit for native T2V | too long: Extremely long prompts dilute the must-have beats; keep one dominant action per shot and put critical details early
Syntax — supported: Negative prompt
Negative prompt: YES — Max 500 characters; use for failure modes (deformed hands, flicker, unstable face, watermark), not to re-describe the scene
Include: Timed shot plan for multi-shot; One explicit camera behavior per shot; Repeated identity anchors; Dialogue as quoted speech with speaker; Ordered action beats (i2v); Continuity guard only where needed (i2v)
Avoid: 2.6-style @Video1 tags in 2.7 prompts; Re-describing the whole input image in i2v; Several simultaneous camera moves (orbit while zooming and panning); Cramming 10–15 seconds with unrelated actions; Long choreographed multi-scene sequences; Relying on the prompt to fix a bad source image
Recommended settings: Steps ; Guidance / CFG Scale ; Resolution 720P or 1080P; Scheduler / Sampler ; Dtype / Precision ', 'Wan 2.7 is the April 2026 generation of Alibaba''s Wan video family, framed as a "director-level" toolkit: four specialized models — text-to-video, image-to-video, reference-to-video, and a dedicated video-editing model — that unify text, image, video, and audio inputs. The headline shift from 2.6 is control: dozens of named camera movements expressed in natural language, shot plans written directly into the prompt, cross-video consistency for up to five characters (with per-subject reference voices), automatic lip-sync for rewritten dialogue, and an i2v endpoint that now covers first-frame, first/last-frame, and continuation in one place. Clips run 2–15 seconds at 720p or 1080p. A rolling alias (e.g. wan2.7-t2v) can move to newer provider snapshots; dated IDs (e.g. wan2.7-t2v-2026-06-12) pin a specific build.', '[{"url":"https://remix.camera/blog/wan-2-7-spicy-prompt-guide","note":"https://remix.camera/blog/wan-2-7-spicy-prompt-guide (WAN 2.7 Spicy Prompt Guide for Image-to-Video)"},{"url":"https://medium.com/@olivia.hayes_21886/wan-2-7-api-capabilities-parameters-prompts-and-cometapi-access-a9bbace7bfb9","note":"https://medium.com/@olivia.hayes_21886/wan-2-7-api-capabilities-parameters-prompts-and-cometapi-access-a9bbace7bfb9 (Wan 2.7 API capabilities, parameters, prompt structure)"},{"url":"https://help.aliyun.com/en/model-studio/video-to-video-guide","note":"https://help.aliyun.com/en/model-studio/video-to-video-guide (Alibaba Cloud: using the Wan reference-to-video model, typed media array, Image N naming)"},{"url":"https://wan2.video/wan2.7","note":"https://wan2.video/wan2.7 (Wan 2.6 vs 2.7 capability comparison)"},{"url":"https://www.4rfv.co.uk/industrynews/329211/alibaba_launches_wan2_7_video","note":"https://www.4rfv.co.uk/industrynews/329211/alibaba_launches_wan2_7_video (Wan2.7-Video launch, four models)"},{"url":"https://github.com/openclaw/skills/blob/HEAD/skills/dlazyai/dlazy-wan2-7/SKILL.md","note":"https://github.com/openclaw/skills/blob/HEAD/skills/dlazyai/dlazy-wan2-7/SKILL.md (Wan 2.7 parameters: prompt_extend, duration, resolution)"}]', 'e416caef955a3f05aec3edd8598ae1b6');
INSERT OR REPLACE INTO prompt_guides (guide_key, group_id, model_family, model_label, version_label, version_match, tab_index, modality, title, source_file, pairs, principle_md, syntax_json, length_json, structure_md, include_json, avoid_json, settings_json, mistakes_json, enhancer_md, summary_md, sources_json, content_hash) VALUES ('video/wan/5', 'video', 'wan', 'WAN', '3.0', '3.0', 5, 'video', 'Prompt Guide: Wan 3.0', 'models/video/wan-3.0.md', 5, 'The prompt is one input among many — Wan 3 decides the mode from the shape of your payload, not from a mode flag. So the prompt''s job is to be a precise production brief of every visible beat and every sound: describe the action, the camera, the exact spoken words with their speaker, and the diegetic audio sources. For image-led work the frame sets the composition and the prompt invents only the motion.', '[{"syntax":"Weighting (word:1.4)","supported":"unknown","notes":"No documented support; assign reference roles and repeat key descriptors instead"},{"syntax":"Emphasis ((word))","supported":"unknown","notes":""},{"syntax":"BREAK keyword","supported":"unknown","notes":""},{"syntax":"[from:to:step] blending","supported":"unknown","notes":""},{"syntax":"Negative prompt","supported":"yes","notes":"negative_prompt parameter: what to keep out"},{"syntax":"Special / trigger tokens","supported":"yes","notes":"Name loose references as Image 1, Video 1, Audio 1 in per-type order and give each one explicit role in the prompt"},{"syntax":"Regional / masked prompting","supported":"unknown","notes":""}]', '[{"length":"Too short","effect":"prompt_extend (on by default) rewrites short prompts into richer ones — helpful for a five-word idea, harmful once you have blocked out the shot yourself"},{"length":"Ideal","effect":"A complete production brief: visible beats, camera behavior, quoted dialogue with speaker, voice/ambience/effects description — long enough that expansion has nothing useful to add"},{"length":"Too long","effect":"No published character limit found; but overstuffed prompts with competing beats produce muddled 30-second takes — keep to one continuous shot''s worth of action"}]', '[Visible beats in order] + [camera behavior] + [dialogue: quoted words + speaker + voice] + [diegetic audio: ambience/effects] + [constraints]', '[{"include":"Exact quoted dialogue with speaker","examples":"\"Welcome to the future,\" the presenter says — drives lip-sync"},{"include":"Voice, ambience, effects, music direction in the same brief","examples":"low hum of the wheel, water dripping into a bucket, distant gull calls"},{"include":"Diegetic-only audio for long takes","examples":"Name sources that exist in the scene; end with No music — explicit music requests risk refusal on copyright checks"},{"include":"Character name in capitals + wardrobe re-described per prompt","examples":"MAYA walks into the workshop... — cheapest defense against drift across shots"},{"include":"Reference roles for every attached input","examples":"Image 1 is the character; Image 2 is the location"},{"include":"Explicit duration","examples":"Set duration yourself (2–30s); combined input + output must stay ≤ 30s when using reference video"},{"include":"First/last frame pairing for a specific move","examples":"Pin both ends of the shot to get a defined camera move instead of default drift"}]', '[{"instead":"Requesting a music score (epic orchestral soundtrack)","write":"Diegetic sound only: Ambient room tone: ... No music"},{"instead":"Leaving prompt_extend on for an art-directed prompt","write":"Set prompt_extend: false — the rewrite will quietly redirect a shot you already blocked out"},{"instead":"Passing aspect_ratio alongside a first frame or reference","write":"It is silently ignored when framing input sets the shape — crop the input instead"},{"instead":"Attaching stray inputs \"just in case\"","write":"Every attached image/video/audio changes the inferred mode; a forgotten parameter silently moves you into a different mode"},{"instead":"Combining document/web context with first/last-frame anchors","write":"They are mutually exclusive — choose one conditioning style per request"},{"instead":"Depending on legible on-screen text or polished audio","write":"Alibaba flags both as still-improving; budget a second pass in a dedicated tool"}]', '[{"param":"Steps","value":""},{"param":"Guidance / CFG Scale","value":""},{"param":"Resolution","value":"480P / 720P / 1080P (set explicitly; providers differ on defaults)"},{"param":"Scheduler / Sampler","value":""},{"param":"Dtype / Precision","value":""}]', '[]', 'Target model: WAN 3.0 (video).
How to prompt it: The prompt is one input among many — Wan 3 decides the mode from the shape of your payload, not from a mode flag. So the prompt''s job is to be a precise production brief of every visible beat and every sound: describe the action, the camera, the exact spoken words with their speaker, and the diegetic audio sources. For image-led work the frame sets the composition and the prompt invents only the motion.
Prompt length — too short: prompt_extend (on by default) rewrites short prompts into richer ones — helpful for a five-word idea, harmful once you have blocked out the shot yourself | ideal: A complete production brief: visible beats, camera behavior, quoted dialogue with speaker, voice/ambience/effects description — long enough that expansion has nothing useful to add | too long: No published character limit found; but overstuffed prompts with competing beats produce muddled 30-second takes — keep to one continuous shot''s worth of action
Syntax — supported: Negative prompt, Special / trigger tokens
Negative prompt: YES — negative_prompt parameter: what to keep out
Include: Exact quoted dialogue with speaker; Voice, ambience, effects, music direction in the same brief; Diegetic-only audio for long takes; Character name in capitals + wardrobe re-described per prompt; Reference roles for every attached input; Explicit duration
Avoid: Requesting a music score (epic orchestral soundtrack); Leaving prompt_extend on for an art-directed prompt; Passing aspect_ratio alongside a first frame or reference; Attaching stray inputs "just in case"; Combining document/web context with first/last-frame anchors; Depending on legible on-screen text or polished audio
Recommended settings: Steps ; Guidance / CFG Scale ; Resolution 480P / 720P / 1080P (set explicitly; providers differ on defaults); Scheduler / Sampler ; Dtype / Precision ', 'Wan 3.0, released August 24, 2026 (public beta from August 6) via Alibaba Cloud Model Studio, is the first Wan generation built as one unified model: a single endpoint covers text-to-video, image-to-video (first frame and first/last frame), reference-to-video, and video editing, with the mode inferred from whatever media you attach. It generates up to 30 seconds in a single pass at a fixed 30fps — double Wan 2.7''s ceiling — at 480p, 720p, or 1080p, with a synchronized soundtrack generated in the same pass as the picture (native audio, on by default, free). It accepts unusually rich context: up to 10 reference images, 5 reference videos, 5 audio clips, and — upstream only — one public document (PDF/DOC/PPT up to 100MB, 50 pages) or one public webpage. Some providers offer a faster "Prime" tier. Alibaba''s own caveat: audio texture and on-screen text rendering are "improving but not yet where we want them."', '[{"url":"https://blog.segmind.com/wan-3-guide-features-examples-and-what-developers-should-know/","note":"https://blog.segmind.com/wan-3-guide-features-examples-and-what-developers-should-know/ (Wan 3 guide: parameters, 2.7 comparison, prompting practices)"},{"url":"https://www.sogni.ai/models/wan-3","note":"https://www.sogni.ai/models/wan-3 (Wan 3 prompting tips, reference naming, mode inference)"},{"url":"https://www.sogni.ai/models/wan-3-uncensored","note":"https://www.sogni.ai/models/wan-3-uncensored (Wan 3 Uncensored prompting tips and differences)"},{"url":"https://fal.ai/wan-3","note":"https://fal.ai/wan-3 (Wan 3 capabilities: 30s, 1080p, native audio, thinking mode, positional references)"},{"url":"https://www.reuters.com/business/retail-consumer/alibaba-launches-wan30-ai-video-model-after-10-billion-share-sale-2026-08-24/","note":"https://www.reuters.com/business/retail-consumer/alibaba-launches-wan30-ai-video-model-after-10-billion-share-sale-2026-08-24/ (Wan 3.0 launch, Aug 24 2026)"},{"url":"https://dataconomy.com/2026/08/24/alibaba-launches-wan30-a-30-second-ai-video-generation-model/","note":"https://dataconomy.com/2026/08/24/alibaba-launches-wan30-a-30-second-ai-video-generation-model/ (Wan 3.0 specs: 30s, 1080p, document input, pricing)"},{"url":"https://github.com/monid-ai/monid/blob/HEAD/openspec/changes/add-connector-alibaba/tasks.md","note":"https://github.com/monid-ai/monid/blob/HEAD/openspec/changes/add-connector-alibaba/tasks.md (wan3.0-video / prime tier API parameters)"}]', '5c40e612aae6f85400a71a191a345f7d');

